import json,re,sys
def parse_sections(fn):
    lines = open(fn).read().split('\n')
    secs={}
    cur=None; head=[]
    for l in lines:
        if l in ('Arguments:','Options:','Commands:'):
            cur=l.rstrip(':'); secs[cur]=[]; continue
        if l.startswith('Resources:'):
            cur='Resources'; secs[cur]=[]; continue
        if cur is not None: secs[cur].append(l)
        else: head.append(l)
    return head,secs

ARG_RE = re.compile(r'^  (-[a-zA-Z], |    )(--?[A-Za-z0-9-]+)(\[?<([^>]+)>\])?$')
POS_RE = re.compile(r'^  (<[^>]+>|\[[^\]]+\])$')
CMDS_RE = re.compile(r'^  ([a-z][a-z-]+) +')
SPECVAL_RE = re.compile(r'^          \[(default|env|possible values|aliases): ?(.*)\]$')
PV_RE = re.compile(r'^          Possible values:$')
PVD_RE = re.compile(r'^          - ([^:]+): +(.*)$')
def dedent_join(lines):
    """join wrapped lines, split on blank-ish lines"""
    paras=[]
    cur=[]
    for l in lines:
        assert l=='' or l.startswith(' '*(10 if True else 2)), repr(l)
        s = l.strip()
        if s=='' : 
            if cur: paras.append(' '.join(cur)); cur=[]
        else: cur.append(s)
    if cur: paras.append(' '.join(cur))
    return paras

def parse_cmd(fn, long_format):
    head,secs = parse_sections(fn)
    res={'head':'\n'.join(head)}
    for secname in secs:
        lines=secs[secname]
        items=[]
        i=0
        while i < len(lines):
            l=lines[i]
            if l.strip()=='' :
                i+=1; continue
            if secname=='Commands':
                m=CMDS_RE.match(l)
                name=m.group(1); desc=l[len(m.group(0)):].strip()
                i+=1; cont=[]
                while i<len(lines) and lines[i].startswith(' '*16):
                    cont.append(lines[i].strip()); i+=1
                items.append({'cmd':name,'desc':' '.join(([desc]+cont))})
                continue
            m = ARG_RE.match(l) if secname=='Options' else POS_RE.match(l)
            if secname=='Options':
                if not m: raise Exception(fn+' '+repr(l))
                flags = m.group(1).replace(' ','').strip(',')
                if flags=='': flags=None
                else: flags=[f for f in flags.split(',')]
                name=m.group(2); val=m.group(4); opt_val = bool(m.group(3))
                i+=1
                desc=[]; specvals=[]; pvdesc=[]
                while i<len(lines):
                    l2=lines[i]
                    if l2.strip()=='' : 
                        desc.append(l2); i+=1; continue
                    if ARG_RE.match(l2): break
                    sv=SPECVAL_RE.match(l2)
                    if sv:
                        specvals.append((sv.group(1), sv.group(2))); i+=1; continue
                    if PV_RE.match(l2):
                        i+=1
                        while i<len(lines):
                            pv=PVD_RE.match(lines[i])
                            if not pv: break
                            pvdesc.append((pv.group(1),pv.group(2))); i+=1
                        continue
                    if l2.startswith(' '*10) or l2=='': desc.append(l2); i+=1; continue
                    break
                # normalize desc: drop trailing blank, join paragraphs
                paras=dedent_join(desc)
                items.append({'kind':'opt','flags':flags,'name':name,'val':val,'optval':opt_val,
                              'paras':paras,'specvals':specvals,'pvdesc':pvdesc})
            else:
                if not m: raise Exception(fn+' '+repr(l))
                name=m.group(1); i+=1
                desc=[]
                while i<len(lines):
                    l2=lines[i]
                    if POS_RE.match(l2): break
                    if l2=='' or l2.startswith(' '*10): desc.append(l2); i+=1; continue
                    break
                paras=dedent_join(desc)
                items.append({'kind':'pos','name':name,'paras':paras})
        res[secname]=items
    return res

out={}
for name,fn in [('', 'ref/help_.txt'),('compile',('ref/help_compile.txt','ref/sum_compile.txt')),('watch',('ref/help_watch.txt','ref/sum_watch.txt')),('init',('ref/help_init.txt','ref/sum_init.txt')),('eval',('ref/help_eval.txt','ref/sum_eval.txt')),('fonts',('ref/help_fonts.txt','ref/sum_fonts.txt')),('completions','ref/help_completions.txt'),('info',('ref/help_info.txt','ref/sum_info.txt')),('query',('ref/help_query.txt','ref/sum_query.txt'))]:
    if isinstance(fn,str): long=parse_cmd(fn,True); short=long
    else: long=parse_cmd(fn[0],True); short=parse_cmd(fn[1],False)
    out[name or 'root']={'long':long,'short':short}
print(json.dumps(out,indent=1))
