POS2_RE = re.compile(r'^  (<[^>]+>|\[[^\]]+\])( {2,})(.*)$')
CMDS_RE = re.compile(r'^  ([a-z][a-z-]+)( {2,})(.*)$')
SPECVAL_RE = re.compile(r'^          \[(default|env|possible values|aliases): ?(.*)\]$')
PV_RE = re.compile(r'^          Possible values:$')
PVD_RE = re.compile(r'^          - ([^:]+): +(.*)$')

def parse_sections(fn):
    lines = open(fn).read().split('\n')
    secs={}; cur=None; head=[]
    for l in lines:
        if l in ('Arguments:','Options:','Commands:'):
            cur=l.rstrip(':'); secs[cur]=[]; continue
        if l.startswith('Resources:'):
            cur='Resources'; secs[cur]=[]; continue
        if cur is not None: secs[cur].append(l)
        else: head.append(l)
    return head,secs

def dedent_join(lines, ind=10):
    paras=[]; cur=[]
    for l in lines:
        if l.strip()=='':
            if cur: paras.append(' '.join(cur)); cur=[]
        else:
            assert l.startswith(' '*ind), repr(l)
            cur.append(l.strip())
    if cur: paras.append(' '.join(cur))
    return paras

