pub const COMMIT: &str = "97ac4370";
pub const COMMIT_FULL: &str = "97ac4370f3ef5ce1dd0034d735158d7ad9d494cd";

#[derive(Clone, Debug, PartialEq)]
pub enum Kind {
    Positional,
    Option_,
}

#[derive(Clone, Debug)]
pub struct PossibleValue {
    pub name: String,
    pub desc: Option<String>,
}

#[derive(Clone, Debug)]
pub struct Arg {
    pub kind: Kind,
    /// Short and long flags, e.g. `["-f", "--format"]`.
    pub flags: Vec<String>,
    /// Value placeholder, e.g. `FORMAT`.
    pub val: Option<String>,
    /// True when the value is optional: `--open [<VIEWER>]`.
    pub optval: bool,
    pub env: Option<String>,
    pub default: Option<String>,
    pub pv: Vec<PossibleValue>,
    pub short: String,
    pub long: Vec<String>,
    pub required: bool,
    pub is_help: bool,
    pub is_version: bool,
}

impl Arg {
    pub fn name(&self) -> &str {
        self.flags.last().map(|s| s.as_str()).unwrap_or("")
    }
    pub fn takes_value(&self) -> bool {
        self.val.is_some() && !self.is_help && !self.is_version
    }
    /// The way the argument is displayed in usage strings.
    pub fn usage_display(&self) -> String {
        if self.kind == Kind::Positional {
            return if self.required {
                format!("<{}>", self.val.as_deref().unwrap_or(self.name()))
            } else {
                format!("[{}]", self.val.as_deref().unwrap_or(self.name()))
            };
        }
        let flags = self.flags.join(", ");
        match &self.val {
            Some(v) if self.optval => format!("{} [<{}>]", flags, v),
            Some(v) => format!("{} <{}>", flags, v),
            None => flags,
        }
    }
    /// The left column in help listings.
    fn help_name(&self) -> String {
        let mut s = String::new();
        if self.kind == Kind::Option_ {
            if let Some(f) = self.flags.iter().find(|f| f.len() == 2) {
                s.push_str(f);
                s.push_str(", ");
            }
        }
        s.push_str(self.name());
        match &self.val {
            Some(v) if self.optval => {
                s.push_str(" [<");
                s.push_str(v);
                s.push_str(">]");
            }
            Some(v) => {
                s.push_str(" <");
                s.push_str(v);
                s.push_str(">");
            }
            None => {}
        }
        s
    }
}

#[derive(Clone, Debug)]
pub struct Sub {
    pub name: String,
    pub aliases: Vec<String>,
    pub desc: String,
}

#[derive(Clone, Debug)]
pub struct Cmd {
    pub name: String,
    pub about: String,
    pub positionals: Vec<Arg>,
    pub options: Vec<Arg>,
    pub subs: Vec<Sub>,
    pub resources: Vec<String>,
}

fn unescape(s: &str) -> String {
    let mut out = String::new();
    let b: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if c == '\\' && i + 1 < b.len() {
            let n = b[i + 1];
            match n {
                'n' => {
                    out.push('\n');
                    i += 2;
                }
                'r' => {
                    out.push('\r');
                    i += 2;
                }
                't' => {
                    out.push('\t');
                    i += 2;
                }
                'x' => {
                    let mut v = 0u32;
                    let mut j = i + 2;
                    let mut k = 0;
                    while j < b.len() && k < 2 && b[j].is_ascii_hexdigit() {
                        v = v * 16 + b[j].to_digit(16).unwrap();
                        j += 1;
                        k += 1;
                    }
                    out.push(char::from_u32(v).unwrap_or('\u{fffd}'));
                    i = j;
                }
                other => {
                    out.push(other);
                    i += 2;
                }
            }
        } else {
            out.push(c);
            i += 1;
        }
    }
    out
}

fn split_fields(line: &str) -> Vec<String> {
    line.split('\t').map(|s| unescape(s)).collect()
}

fn parse_pv(s: &str) -> Vec<PossibleValue> {
    if s.is_empty() {
        return vec![];
    }
    s.split('|')
        .map(|item| {
            match item.find('\u{2}') {
                Some(i) => PossibleValue {
                    name: item[..i].to_string(),
                    desc: Some(item[i + 1..].to_string()),
                },
                None => PossibleValue {
                    name: item.to_string(),
                    desc: None,
                },
            }
        })
        .collect()
}

fn parse_arg(kind: Kind, fields: &[String]) -> Arg {
    if kind == Kind::Positional {
        let name = fields[1].trim_start_matches('[').trim_end_matches(']');
        return Arg {
            kind,
            flags: vec![fields[1].clone()],
            val: Some(name.to_string()),
            optval: false,
            env: None,
            default: None,
            pv: vec![],
            short: fields[3].clone(),
            long: fields[4].split('\u{1}').map(|s| s.to_string()).collect(),
            required: fields[2] == "1",
            is_help: false,
            is_version: false,
        };
    }
    let flags: Vec<String> = fields[1].split(',').map(|s| s.to_string()).collect();
    let (val, optval) = match fields[2].strip_prefix('?') {
        Some(v) => (Some(v.to_string()), true),
        None => {
            if fields[2].is_empty() {
                (None, false)
            } else {
                (Some(fields[2].clone()), false)
            }
        }
    };
    let is_help = flags.iter().any(|f| f == "--help");
    let is_version = flags.iter().any(|f| f == "--version");
    Arg {
        kind,
        flags,
        val,
        optval,
        env: if fields[3].is_empty() {
            None
        } else {
            Some(fields[3].clone())
        },
        default: if fields[4].is_empty() {
            None
        } else {
            Some(fields[4].clone())
        },
        pv: parse_pv(&fields[5]),
        short: fields[6].clone(),
        long: fields[7].split('\u{1}').map(|s| s.to_string()).collect(),
        required: false,
        is_help,
        is_version,
    }
}

pub fn parse_spec(src: &str, name: &str) -> Cmd {
    let mut cmd = Cmd {
        name: name.to_string(),
        about: String::new(),
        positionals: vec![],
        options: vec![],
        subs: vec![],
        resources: vec![],
    };
    for line in src.split('\n') {
        if line.is_empty() {
            continue;
        }
        let f = split_fields(line);
        match f[0].as_str() {
            "A" => cmd.about = f[1].clone(),
            "P" => cmd.positionals.push(parse_arg(Kind::Positional, &f)),
            "O" => cmd.options.push(parse_arg(Kind::Option_, &f)),
            "C" => cmd.subs.push(Sub {
                name: f[1].clone(),
                aliases: f[2].split(',').filter(|s| !s.is_empty()).map(|s| s.to_string()).collect(),
                desc: f[3].clone(),
            }),
            "R" => cmd.resources.push(f[1].clone()),
            _ => {}
        }
    }
    cmd
}

// ---------------------------------------------------------------------------
// Help rendering
// ---------------------------------------------------------------------------

fn term_width() -> usize {
    use std::io::Stdin;
    let fds = [
        std::io::stdout().as_raw_fd(),
        std::io::stderr().as_raw_fd(),
        std::io::stdin().as_raw_fd(),
    ];
    for fd in fds {
        let mut wsz = libc_winsize(fd);
        if let Some(w) = wsz {
            if w > 0 {
                return w as usize;
            }
        }
    }
    let _ = std::mem::size_of::<Stdin>();
    80
}

fn libc_winsize(fd: i32) -> Option<u16> {
    #[repr(C)]
    struct Winsize {
        ws_row: u16,
        ws_col: u16,
        ws_xpixel: u16,
        ws_ypixel: u16,
    }
    extern "C" {
        fn ioctl(fd: i32, request: u64, ...) -> i32;
    }
    const TIOCGWINSZ: u64 = 0x5413;
    let mut ws = Winsize {
        ws_row: 0,
        ws_col: 0,
        ws_xpixel: 0,
        ws_ypixel: 0,
    };
    let r = unsafe { ioctl(fd, TIOCGWINSZ, &mut ws as *mut Winsize) };
    if r == 0 && ws.ws_col > 0 {
        Some(ws.ws_col)
    } else {
        None
    }
}

/// Wraps `text` into lines of at most `width` columns, breaking on spaces.
fn wrap(text: &str, width: usize) -> Vec<String> {
    let mut out = vec![];
    let mut cur = String::new();
    for word in text.split(' ') {
        if word.is_empty() {
            if cur.is_empty() {
                continue;
            }
            out.push(cur.clone());
            cur.clear();
            continue;
        }
        if cur.is_empty() {
            cur.push_str(word);
        } else if cur.chars().count() + 1 + word.chars().count() <= width {
            cur.push(' ');
            cur.push_str(word);
        } else {
            out.push(cur.clone());
            cur.clear();
            cur.push_str(word);
        }
    }
    if !cur.is_empty() {
        out.push(cur);
    }
    if out.is_empty() {
        out.push(String::new());
    }
    out
}

fn pad_to(line: &str, col: usize) -> String {
    let mut s = String::from(line);
    let n = line.chars().count();
    for _ in n..col {
        s.push(' ');
    }
    s
}

fn spec_vals(arg: &Arg, long: bool) -> String {
    let mut parts: Vec<String> = vec![];
    if let Some(e) = &arg.env {
        parts.push(format!("[env: {}]", e));
    }
    if let Some(d) = &arg.default {
        parts.push(format!("[default: {}]", d));
    }
    if !arg.pv.is_empty() {
        if arg.pv.iter().all(|p| p.desc.is_none()) {
            parts.push(format!(
                "[possible values: {}]",
                arg.pv.iter().map(|p| p.name.clone()).collect::<Vec<_>>().join(", ")
            ));
        }
    }
    parts.join(if long { "\n" } else { " " })
}

fn render_block(paras: &[String], indent: usize, width: usize, sep: &str) -> Vec<String> {
    let mut out = vec![];
    for (i, p) in paras.iter().enumerate() {
        if i > 0 {
            out.push(sep.to_string());
        }
        for l in wrap(p, width - indent) {
            let mut s = " ".repeat(indent);
            s.push_str(&l);
            out.push(s);
        }
    }
    out
}

fn next_line_help(args: &[&Arg], longest: usize, term_w: usize) -> bool {
    let taken = longest + 8;
    if term_w < taken {
        return true;
    }
    if (taken as f64) / (term_w as f64) <= 0.40 {
        return false;
    }
    args.iter().any(|a| {
        let help = if a.short.is_empty() {
            first_para(&a.long)
        } else {
            a.short.clone()
        };
        let sv = spec_vals(a, false);
        help.chars().count() + sv.chars().count() > term_w - taken
    })
}

fn first_para(long: &[String]) -> String {
    long.first().cloned().unwrap_or_default()
}

fn short_help_of(a: &Arg) -> String {
    if !a.short.is_empty() {
        return a.short.clone();
    }
    match a.long.first() {
        Some(p) => {
            if p.ends_with('.') && !p.ends_with("..") {
                p[..p.len() - 1].to_string()
            } else {
                p.clone()
            }
        }
        None => String::new(),
    }
}

fn long_help_of(a: &Arg) -> String {
    a.long.join("\u{1}")
}

fn render_section(
    title: &str,
    args: &[&Arg],
    term_w: usize,
    long: bool,
    out: &mut Vec<String>,
) {
    if args.is_empty() {
        return;
    }
    out.push(format!("{}:", title));
    let names: Vec<String> = args.iter().map(|a| a.help_name()).collect();
    let longest = names.iter().map(|n| n.chars().count()).max().unwrap_or(0);
    let nl = long || next_line_help(args, longest, term_w);
    for (a, name) in args.iter().zip(names.iter()) {
        if nl {
            let indent = 2 + name.chars().count();
            let pad = if a.kind == Kind::Option_ && a.flags.len() > 1 {
                2
            } else if a.kind == Kind::Option_ {
                6
            } else {
                2
            };
            let mut line = " ".repeat(pad);
            line.push_str(name);
            out.push(line);
            let sv = spec_vals(a, true);
            let desc = if long {
                let l = long_help_of(a);
                let mut paras: Vec<String> = l.split('\u{1}').map(|s| s.to_string()).collect();
                // In long help, the trailing hint for --help is the long one.
                for sv_part in sv.split('\n') {
                    if !sv_part.is_empty() {
                        if let Some(p) = arg_pv_desc(a) {
                            out.push(String::new());
                            out.push("          Possible values:".to_string());
                            let w = p.iter().map(|(n, _)| n.chars().count()).max().unwrap_or(0);
                            for (n, d) in p {
                                let mut s = format!("          - {}:", n);
                                for _ in n.chars().count()..w {
                                    s.push(' ');
                                }
                                s.push(' ');
                                s.push_str(&d);
                                out.push(s);
                            }
                            continue;
                        }
                        out.push("          ".to_string());
                        for wl in wrap(sv_part, term_w - 10) {
                            let mut s = " ".repeat(10);
                            s.push_str(&wl);
                            out.push(s);
                        }
                    }
                }
                let _ = &mut paras;
                continue;
            } else {
                short_help_of(a)
            };
            let full = if sv.is_empty() {
                desc.clone()
            } else if desc.is_empty() {
                sv.clone()
            } else {
                format!("{} {}", desc, sv)
            };
            if a.pv.iter().any(|p| p.desc.is_some()) && long {
                continue;
            }
            for l in wrap(&full, term_w - 10) {
                let mut s = " ".repeat(10);
                s.push_str(&l);
                out.push(s);
            }
            let _ = indent;
        } else {
            let pad = if a.kind == Kind::Option_ && a.flags.len() > 1 {
                2
            } else if a.kind == Kind::Option_ {
                6
            } else {
                2
            };
            let col = longest + 2 + pad;
            let line = pad_to(&format!("{}{}", " ".repeat(pad), name), col);
            let sv = spec_vals(a, false);
            let desc = short_help_of(a);
            let full = if sv.is_empty() {
                desc.clone()
            } else if desc.is_empty() {
                sv.clone()
            } else {
                format!("{} {}", desc, sv)
            };
            let lines = wrap(&full, term_w.saturating_sub(col));
            out.push(format!("{}{}", line, lines.first().cloned().unwrap_or_default()));
            for l in lines.iter().skip(1) {
                out.push(format!("{}{}", " ".repeat(col), l));
            }
        }
    }
}

fn arg_pv_desc(a: &Arg) -> Option<Vec<(String, String)>> {
    if a.pv.iter().any(|p| p.desc.is_some()) {
        Some(a.pv.iter().map(|p| (p.name.clone(), p.desc.clone().unwrap_or_default())).collect())
    } else {
        None
    }
}

pub fn render_help(cmd: &Cmd, path: &str, prog: &str, long: bool, term_w: usize) -> String {
    let mut out: Vec<String> = vec![];
    out.push(cmd.about.clone());
    out.push(String::new());
    // usage
    let mut usage = format!("Usage: {}{}", prog, if path.is_empty() { String::new() } else { format!(" {}", path) });
    let has_opts = cmd.options.iter().any(|a| !a.is_help && !a.is_version);
    if has_opts {
        usage.push_str(" [OPTIONS]");
    }
    for p in &cmd.positionals {
        usage.push(' ');
        usage.push_str(&p.usage_display());
    }
    if !cmd.subs.is_empty() {
        usage.push_str(" <COMMAND>");
    }
    out.push(usage);
    out.push(String::new());

    let pos: Vec<&Arg> = cmd.positionals.iter().collect();
    let opts: Vec<&Arg> = cmd.options.iter().collect();
    if !pos.is_empty() {
        render_section("Arguments", &pos, term_w, long, &mut out);
        out.push(String::new());
    }
    if !cmd.subs.is_empty() {
        let subs: Vec<&Arg> = vec![];
        let _ = subs;
        out.push("Commands:".to_string());
        let names: Vec<usize> = cmd.subs.iter().map(|s| s.name.chars().count()).collect();
        let longest = names.iter().copied().max().unwrap_or(0);
        let longest = if longest < 2 { 2 } else { longest };
        let nl = {
            let taken = longest + 8;
            (taken as f64) / (term_w as f64) > 0.40
        };
        for s in &cmd.subs {
            let mut desc = s.desc.clone();
            if !s.aliases.is_empty() {
                desc = format!("{} [aliases: {}]", desc, s.aliases.join(", "));
            }
            if nl {
                out.push(format!("  {}", s.name));
                for l in wrap(&desc, term_w - 10) {
                    out.push(format!("          {}", l));
                }
            } else {
                let col = 2 + longest + 2;
                let lines = wrap(&desc, term_w.saturating_sub(col));
                out.push(format!("{}{}", pad_to(&format!("  {}", s.name), col), lines[0]));
                for l in lines.iter().skip(1) {
                    out.push(format!("{}{}", " ".repeat(col), l));
                }
            }
        }
        out.push(String::new());
    }
    if !opts.is_empty() {
        render_section("Options", &opts, term_w, long, &mut out);
        out.push(String::new());
    }
    if !cmd.resources.is_empty() {
        for l in &cmd.resources {
            out.push(l.clone());
        }
    }
    while matches!(out.last(), Some(s) if s.is_empty()) {
        out.pop();
    }
    let mut s = out.join("\n");
    s.push('\n');
    s
}
