    let is_version = flags.iter().any(|f| f == "--version");
    Arg {
        kind,
        flags,
        val,
        optval,
        env: if fields[3].is_empty() {
            None
        } else {
            Some(fields[3].clone())
        },
        default: if fields[4].is_empty() {
