pub fn cmd_has_long_help(cmd: &Cmd) -> bool {
    cmd.positionals.iter().chain(cmd.options.iter()).any(|a| a.long.len() > 1) || a_pv_desc_any(cmd)
}

fn a_pv_desc_any(cmd: &Cmd) -> bool {
    cmd.positionals.iter().chain(cmd.options.iter()).any(|a| a.pv_detailed())
}

/// Builds the auto-generated help/version arguments for a command.
pub fn add_help_args(cmd: &mut Cmd) {
    let has_long = cmd_has_long_help(cmd);
    let short_text = if has_long { "Print help (see more with '--help')" } else { "Print help" };
    let long_text = if has_long { "Print help (see a summary with '-h')" } else { "Print help" };
    cmd.options.push(Arg {
        kind: Kind::Option_,
        flags: vec!["-h".to_string(), "--help".to_string()],
        val: None,
        optval: false,
        env: None,
        default: None,
        pv: vec![],
        short: short_text.to_string(),
        long: vec![long_text.to_string()],
        required: false,
        is_help: true,
        is_version: false,
    });
    let _ = &long_text;
    cmd.options.push(Arg {
        kind: Kind::Option_,
        flags: vec!["-V".to_string(), "--version".to_string()],
        val: None,
        optval: false,
        env: None,
        default: None,
        pv: vec![],
        short: "Print version".to_string(),
        long: vec!["Print version".to_string()],
        required: false,
        is_help: false,
        is_version: true,
    });
}

pub fn render_help(cmd: &Cmd, path: &str, prog: &str, long: bool, term_w: usize) -> String {
    let mut cmd = cmd.clone();
    if !cmd.options.iter().any(|a| a.is_help) {
        add_help_args(&mut cmd);
    }
    let mut out: Vec<String> = vec![];
    out.push(cmd.about.clone());
    out.push(String::new());
    let mut usage = format!(
        "Usage: {}{}",
        prog,
        if path.is_empty() { String::new() } else { format!(" {}", path) }
    );
