                                used.push(o);
                            }
                        }
                        i += 1;
                    }
                    None => {
                        let cands: Vec<String> = cmd
                            .options
                            .iter()
                            .map(|o| o.name().to_string())
                            .chain(
                                cmd.subs
                                    .iter()
                                    .flat_map(|s| s.aliases.iter().cloned())
                                    .chain(cmd.subs.iter().map(|s| s.name.clone()))
                                    .map(|s| format!("--{}", s)),
                            )
                            .collect();
                        let sugg = self.did_you_mean(&a, &cands);
                        let s = sugg
                            .first()
                            .and_then(|s| cmd.options.iter().find(|o| o.name() == s.as_str()));
                        return Err(self.unexpected_arg(cmd, path, &a, &used, s));
                    }
                }
                continue;
            }
            if a.starts_with('-') && a.len() > 1 {
                let chars: Vec<char> = a[1..].chars().collect();
                let mut k = 0;
                let mut consumed_next = false;
                let mut cluster_err: Option<String> = None;
                while k < chars.len() {
                    let c = chars[k];
                    let short = format!("-{}", c);
                    let found = cmd.options.iter().find(|o| o.flags.iter().any(|f| f == &short));
                    match found {
                        Some(o) if o.is_help => return Err(help_requested(path)),
                        Some(o) if o.is_version => return Err(version_requested()),
                        Some(o) if o.takes_value() => {
                            let rest: String = chars[k + 1..].iter().collect();
                            let v = if !rest.is_empty() {
                                rest.strip_prefix('=').unwrap_or(&rest).to_string()
                            } else if i + 1 < args.len() {
