            if pos_index < cmd.positionals.len() {
                m.positionals.push(a);
                pos_index += 1;
                i += 1;
            } else {
                let cands: Vec<String> = cmd.options.iter().map(|o| o.name().to_string()).collect();
                let sugg = self.did_you_mean(&a, &cands);
                let s = sugg
                    .first()
                    .and_then(|s| cmd.options.iter().find(|o| o.name() == s.as_str()));
                return Err(self.unexpected_arg(cmd, path, &a, &used, s));
            }
        }
        Ok(m)
    }

    fn missing_value(&self, o: &Arg) -> String {
        let mut parts = vec![format!(
            "error: a value is required for '{}' but none was supplied",
            o.usage_display()
        )];
        if o.pv_possible_values_line() {
            parts.push(format!(
                "  [possible values: {}]",
                o.pv.iter().map(|p| p.name.clone()).collect::<Vec<_>>().join(", ")
            ));
        }
        parts.push(String::new());
        parts.push(self.try_help());
        err_msg(&parts)
    }

    fn multiple_times(&self, cmd: &Cmd, path: &str, o: &Arg) -> String {
        let parts = vec![
            format!(
                "error: the argument '{}' cannot be used multiple times",
                o.usage_display()
            ),
            String::new(),
            self.usage_full(cmd, path),
            String::new(),
            self.try_help(),
        ];
        err_msg(&parts)
    }

    fn unexpected_value(&self, cmd: &Cmd, path: &str, o: &Arg, v: &str) -> String {
        let mut used = vec![o];
        let _ = &mut used;
        let parts = vec![
            format!(
                "error: unexpected value '{}' for '{}' found; no more were expected",
                v,
                o.name()
            ),
            String::new(),
            self.usage_smart(cmd, path, &[o]),
            String::new(),
            self.try_help(),
        ];
        err_msg(&parts)
    }

    fn check_value(&self, o: &Arg, v: &str) -> Result<(), String> {
        if o.name() == "--input" {
            if !v.contains('=') {
                return Err(err_msg(&[
                    format!(
                        "error: invalid value '{}' for '{}': input must be a key and a value separated by an equal sign",
                        v,
                        o.usage_display()
                    ),
                    String::new(),
                    self.try_help(),
                ]));
            }
        }
        if !o.pv.is_empty() {
            if !o.pv.iter().any(|p| p.name == v) {
                let mut parts = vec![
                    format!("error: invalid value '{}' for '{}'", v, o.usage_display()),
                    format!(
                        "  [possible values: {}]",
                        o.pv.iter().map(|p| p.name.clone()).collect::<Vec<_>>().join(", ")
                    ),
                ];
                let cands: Vec<String> = o.pv.iter().map(|p| p.name.clone()).collect();
                let sugg = self.did_you_mean(v, &cands);
                if !sugg.is_empty() {
                    parts.push(String::new());
                    if sugg.len() == 1 {
                        parts.push(format!("  tip: a similar value exists: '{}'", sugg[0]));
                    } else {
                        parts.push(format!(
                            "  tip: some similar values exist: {}",
                            sugg.iter().map(|s| format!("'{}'", s)).collect::<Vec<_>>().join(", ")
                        ));
                    }
                }
                parts.push(String::new());
                parts.push(self.try_help());
                return Err(err_msg(&parts));
            }
            return Ok(());
        }
        match o.name() {
            "--ppi" => {
                if v.parse::<f64>().is_err() {
                    return Err(invalid_value_num(v, o, "invalid float literal", &self.prog, self.try_help()));
                }
            }
            "--jobs" => {
                if v.parse::<usize>().is_err() {
                    let msg = match v.parse::<usize>() {
                        Err(_) => {
                            if v.chars().all(|c| c.is_ascii_digit()) {
                                "number too large to fit in target type"
                            } else {
                                "invalid digit found in string"
                            }
                        }
                        Ok(_) => "",
                    };
                    return Err(invalid_value_num(v, o, msg, &self.prog, self.try_help()));
                }
            }
            "--creation-timestamp" => {
                if v.parse::<i64>().is_err() {
                    let msg = if v.chars().all(|c| c.is_ascii_digit()) {
                        "number too large to fit in target type"
                    } else {
                        "invalid digit found in string"
                    };
                    return Err(invalid_value_num(
                        v,
                        o,
                        &format!("timestamp must be decimal integer ({})", msg),
                        &self.prog,
                        self.try_help(),
                    ));
                }
            }
            _ => {}
        }
        Ok(())
    }
}

fn invalid_value_num(v: &str, o: &Arg, msg: &str, _prog: &str, try_help: String) -> String {
    err_msg(&[
        format!("error: invalid value '{}' for '{}': {}", v, o.usage_display(), msg),
        String::new(),
        try_help,
    ])
}

fn help_requested(path: &str) -> String {
    format!("\u{0}help {}", path)
}

fn version_requested() -> String {
    "\u{0}version".to_string()
}

// ---------------------------------------------------------------------------
// Suggestions (Jaro similarity, as used by clap)
// ---------------------------------------------------------------------------

pub fn jaro(a: &str, b: &str) -> f64 {
    let s1: Vec<char> = a.chars().collect();
    let s2: Vec<char> = b.chars().collect();
    if s1.is_empty() || s2.is_empty() {
        return 0.0;
    }
    let mut window = (s1.len().max(s2.len())) / 2;
    if window > 0 {
        window -= 1;
    }
    let mut s1m = vec![false; s1.len()];
    let mut s2m = vec![false; s2.len()];
    let mut matches = 0usize;
    for (i, c) in s1.iter().enumerate() {
        let lo = i.saturating_sub(window);
        let hi = (i + window + 1).min(s2.len());
        for j in lo..hi {
            if !s2m[j] && s2[j] == *c {
                s1m[i] = true;
                s2m[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut t = 0usize;
    let mut k = 0usize;
    for i in 0..s1.len() {
        if s1m[i] {
            while !s2m[k] {
                k += 1;
            }
            if s1[i] != s2[k] {
                t += 1;
            }
            k += 1;
        }
    }
    t /= 2;
    let m = matches as f64;
    (m / s1.len() as f64 + m / s2.len() as f64 + (m - t as f64) / m) / 3.0
}

impl Arg {
    pub fn is_multiple(&self) -> bool {
        matches!(self.name(), "--input" | "--font-path" | "--features" | "--pdf-standard")
    }
}
