// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

#[derive(Debug, Default)]
pub struct Matches {
    pub vals: Vec<(String, String)>,
    pub positionals: Vec<String>,
}

impl Matches {
    pub fn get(&self, name: &str) -> Option<&str> {
        self.vals
            .iter()
            .rev()
            .find(|(n, _)| n == name)
            .map(|(_, v)| v.as_str())
    }
    pub fn get_all(&self, name: &str) -> Vec<String> {
        self.vals
            .iter()
            .filter(|(n, _)| n == name)
            .map(|(_, v)| v.clone())
            .collect()
    }
    pub fn has(&self, name: &str) -> bool {
        self.vals.iter().any(|(n, _)| n == name)
    }
}

pub struct Cli {
    pub prog: String,
    pub specs: Vec<(String, Cmd)>,
}

fn err_msg(parts: &[String]) -> String {
    let mut s = String::new();
    for p in parts {
        s.push_str(p);
        s.push('\n');
    }
    s
}

impl Cli {
    pub fn find(&self, name: &str) -> Option<(usize, &Cmd)> {
        self.specs
            .iter()
            .position(|(n, _)| n == name)
            .map(|i| (i, &self.specs[i].1))
    }

    pub fn usage_full(&self, cmd: &Cmd, path: &str) -> String {
        let mut u = format!("Usage: {}{}", self.prog, if path.is_empty() { String::new() } else { format!(" {}", path) });
        if cmd.options.iter().any(|a| !a.is_help && !a.is_version) {
            u.push_str(" [OPTIONS]");
        }
        for p in &cmd.positionals {
            u.push(' ');
            u.push_str(&p.usage_display());
        }
        if !cmd.subs.is_empty() {
            u.push_str(" <COMMAND>");
        }
        u
    }

    pub fn usage_smart(&self, cmd: &Cmd, path: &str, used: &[&Arg]) -> String {
        let mut u = format!("Usage: {}{}", self.prog, if path.is_empty() { String::new() } else { format!(" {}", path) });
        for a in used {
            u.push(' ');
            u.push_str(&a.usage_display());
        }
        for p in &cmd.positionals {
            u.push(' ');
            u.push_str(&p.usage_display());
        }
        if !cmd.subs.is_empty() {
            u.push_str(" <COMMAND>");
        }
        u
    }

    pub fn try_help(&self) -> String {
        "For more information, try '--help'.\n".to_string()
    }

    fn unexpected_arg(&self, cmd: &Cmd, path: &str, tok: &str, used: &[&Arg], suggestion: Option<&Arg>) -> String {
        let mut parts = vec![format!("error: unexpected argument '{}' found", tok)];
        let mut used2: Vec<&Arg> = used.to_vec();
        if let Some(s) = suggestion {
            parts.push(String::new());
            parts.push(format!("  tip: a similar argument exists: '{}'", s.name()));
            used2.push(s);
        } else if !cmd.positionals.is_empty() {
            parts.push(String::new());
            parts.push(format!("  tip: to pass '{}' as a value, use '-- {}'", tok, tok));
        }
        parts.push(String::new());
        let usage = if used2.is_empty() {
            self.usage_full(cmd, path)
        } else {
            self.usage_smart(cmd, path, &used2)
        };
        parts.push(usage);
        parts.push(String::new());
        parts.push(self.try_help());
        err_msg(&parts)
    }

    pub fn did_you_mean(&self, v: &str, candidates: &[String]) -> Vec<String> {
        let mut c: Vec<(f64, String)> = candidates
            .iter()
            .map(|p| (jaro(v, p), p.clone()))
            .filter(|(conf, _)| *conf > 0.7)
            .collect();
        c.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
        c.into_iter().map(|(_, p)| p).collect()
    }

    /// Parses arguments for a subcommand (or the root, when `cmd.name` is "").
    pub fn parse(&self, cmd: &Cmd, path: &str, args: &[String]) -> Result<Matches, String> {
        let mut m = Matches::default();
        let mut used: Vec<&Arg> = vec![];
        let mut after_dd = false;
        let mut i = 0;
        let mut pos_index = 0;
        while i < args.len() {
            let a = args[i].clone();
            if after_dd {
                m.positionals.push(a);
                i += 1;
                continue;
            }
            if a == "--" {
                after_dd = true;
                i += 1;
                continue;
            }
            if a.starts_with("--") && a.len() > 2 {
                let (name, inline) = match a.find('=') {
                    Some(p) => (a[2..p].to_string(), Some(a[p + 1..].to_string())),
                    None => (a[2..].to_string(), None),
                };
                let found = cmd.options.iter().find(|o| o.name() == &format!("--{}", name));
                match found {
                    Some(o) if o.is_help => return Err(help_requested(path)),
                    Some(o) if o.is_version => return Err(version_requested()),
                    Some(o) => {
                        if o.takes_value() {
                            let v = match inline {
                                Some(v) => v,
                                None => {
                                    if i + 1 < args.len() {
                                        i += 1;
                                        args[i].clone()
                                    } else {
                                        return Err(self.missing_value(o));
                                    }
                                }
                            };
                            self.check_value(o, &v)?;
                            if !o.is_multiple() && m.has(o.name()) {
                                return Err(self.multiple_times(cmd, path, o));
                            }
                            m.vals.push((o.name().to_string(), v));
                            if !used.iter().any(|u| u.name() == o.name()) {
                                used.push(o);
                            }
                        } else {
                            if let Some(v) = inline {
                                return Err(self.unexpected_value(cmd, path, o, &v));
                            }
                            if m.has(o.name()) {
                                return Err(self.multiple_times(cmd, path, o));
                            }
                            m.vals.push((o.name().to_string(), String::new()));
                            if !used.iter().any(|u| u.name() == o.name()) {
                                used.push(o);
                            }
                        }
                        i += 1;
                    }
                    None => {
                        let cands: Vec<String> = cmd
                            .options
                            .iter()
                            .map(|o| o.name().to_string())
                            .chain(
                                cmd.subs
                                    .iter()
                                    .flat_map(|s| s.aliases.iter().cloned())
