pub fn jaro(a: &str, b: &str) -> f64 {
    let s1: Vec<char> = a.chars().collect();
    let s2: Vec<char> = b.chars().collect();
    if s1.is_empty() || s2.is_empty() {
        return 0.0;
    }
    let mut window = (s1.len().max(s2.len())) / 2;
    if window > 0 {
        window -= 1;
    }
    let mut s1m = vec![false; s1.len()];
    let mut s2m = vec![false; s2.len()];
    let mut matches = 0usize;
    for (i, c) in s1.iter().enumerate() {
        let lo = i.saturating_sub(window);
        let hi = (i + window + 1).min(s2.len());
        for j in lo..hi {
            if !s2m[j] && s2[j] == *c {
                s1m[i] = true;
                s2m[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut t = 0usize;
    let mut k = 0usize;
    for i in 0..s1.len() {
        if s1m[i] {
            while !s2m[k] {
                k += 1;
            }
            if s1[i] != s2[k] {
                t += 1;
            }
            k += 1;
        }
    }
    t /= 2;
    let m = matches as f64;
    (m / s1.len() as f64 + m / s2.len() as f64 + (m - t as f64) / m) / 3.0
}

