                let (name, inline) = match a.find('=') {
                    Some(p) => (a[2..p].to_string(), Some(a[p + 1..].to_string())),
                    None => (a[2..].to_string(), None),
                };
                let o = root_cmd.options.iter().find(|o| o.name() == &format!("--{}", name));
                match o {
                    Some(o) if o.name() == "--color" => {
                        let v = match inline {
                            Some(v) => v,
                            None => {
                                if i + 1 < args.len() {
                                    i += 1;
                                    args[i].clone()
                                } else {
                                    err = Some(c.missing_value(o));
                                    break;
                                }
                            }
                        };
                        if let Err(e) = c.check_value(o, &v) {
                            err = Some(e);
                            break;
                        }
                        color = Some(v);
                    }
                    Some(o) if o.name() == "--cert" => {
                        let v = match inline {
                            Some(v) => v,
                            None => {
                                if i + 1 < args.len() {
                                    i += 1;
                                    args[i].clone()
                                } else {
                                    err = Some(c.missing_value(o));
                                    break;
                                }
                            }
                        };
                        cert = Some(v);
                    }
                    _ => {
                        let cands: Vec<String> = root_cmd
                            .options
                            .iter()
                            .map(|o| o.name().to_string())
                            .collect();
                        let sugg = c.did_you_mean(&a, &cands);
                        let s = sugg
                            .first()
                            .and_then(|s| root_cmd.options.iter().find(|o| o.name() == s.as_str()));
