            let mut k = 0;
            let mut bad = false;
            while k < chars.len() {
                let c = chars[k];
                match c {
                    'h' => {
                        let tw = cli::term_width_pub();
                        print!("{}", cli::render_help(root_cmd, "", &c.prog, false, tw));
                        std::process::exit(0);
                    }
                    'V' => {
                        println!("typst {} ({})", cli::VERSION, cli::COMMIT);
                        std::process::exit(0);
                    }
                    _ => {
                        let short = format!("-{}", c);
                        err = Some(c.unexpected_arg(root_cmd, "", &short, &[], None));
                        bad = true;
                        break;
                    }
                }
            }
            if bad {
                break;
            }
            i += 1;
            continue;
        }
        // subcommand
        sub = Some(a.clone());
        rest = args[i + 1..].to_vec();
        break;
    }
    if let Some(e) = err {
        eprint!("{}", e);
        std::process::exit(2);
    }
    let sub = match sub {
        Some(s) => s,
        None => {
            print!("{}", WELCOME);
            std::process::exit(0);
        }
    };
    let resolved = if sub == "help" {
        // `typst help [cmd]`
        if rest.is_empty() {
            let tw = cli::term_width_pub();
            print!("{}", cli::render_help(root_cmd, "", &c.prog, true, tw));
            std::process::exit(0);
        }
        let target = rest[0].clone();
        let idx = c
            .specs
            .iter()
            .position(|(n, _)| n == &target)
            .or_else(|| {
                c.specs.iter().position(|(_, cmd)| {
                    cmd.subs.iter().any(|s| s.aliases.iter().any(|a| a == &target))
                })
            });
        match idx {
            Some(0) => {
                let tw = cli::term_width_pub();
                print!("{}", cli::render_help(root_cmd, "", &c.prog, true, tw));
                std::process::exit(0);
            }
            Some(k) => {
                let (name, cmd) = &c.specs[k];
                let tw = cli::term_width_pub();
                print!("{}", cli::render_help(cmd, name, &c.prog, true, tw));
                std::process::exit(0);
            }
            None => {
                let names: Vec<String> = root_cmd
                    .subs
                    .iter()
                    .flat_map(|s| std::iter::once(s.name.clone()).chain(s.aliases.iter().cloned()))
                    .collect();
                let sugg = c.did_you_mean(&target, &names);
                let mut parts = vec![format!("error: unrecognized subcommand '{}'", target)];
                if !sugg.is_empty() {
                    parts.push(String::new());
                    if sugg.len() == 1 {
                        parts.push(format!("  tip: a similar subcommand exists: '{}'", sugg[0]));
                    } else {
                        parts.push(format!(
                            "  tip: some similar subcommands exist: {}",
                            sugg.iter().map(|s| format!("'{}'", s)).collect::<Vec<_>>().join(", ")
                        ));
                    }
                }
                parts.push(String::new());
                parts.push(c.usage_full(root_cmd, ""));
                parts.push(String::new());
                parts.push("For more information, try '--help'.\n".to_string());
                eprint!("{}", parts.join("\n"));
                std::process::exit(2);
            }
        }
    } else {
        sub
    };
    // resolve aliases
    let resolved = {
        let mut r = resolved.clone();
        for (n, cmd) in &c.specs {
            if cmd.subs.iter().any(|s| s.name == r || s.aliases.iter().any(|a| a == &r)) {
                let s = cmd.subs.iter().find(|s| s.name == r || s.aliases.iter().any(|a| a == &r)).unwrap();
                r = s.name.clone();
            }
        }
        r
    };
    let idx = c.find(&resolved).map(|(i, _)| i);
    let idx = match idx {
        Some(i) => i,
        None => {
            let names: Vec<String> = root_cmd
                .subs
                .iter()
                .flat_map(|s| std::iter::once(s.name.clone()).chain(s.aliases.iter().cloned()))
                .collect();
            let sugg = c.did_you_mean(&sub, &names);
            let mut parts = vec![format!("error: unrecognized subcommand '{}'", sub)];
            if !sugg.is_empty() {
                parts.push(String::new());
                if sugg.len() == 1 {
                    parts.push(format!("  tip: a similar subcommand exists: '{}'", sugg[0]));
                } else {
                    parts.push(format!(
                        "  tip: some similar subcommands exist: {}",
                        sugg.iter().map(|s| format!("'{}'", s)).collect::<Vec<_>>().join(", ")
                    ));
                }
            }
            parts.push(String::new());
            parts.push(c.usage_full(root_cmd, ""));
            parts.push(String::new());
            parts.push("For more information, try '--help'.\n".to_string());
            eprint!("{}", parts.join("\n"));
            std::process::exit(2);
        }
    };
    let (name, cmd) = (&c.specs[idx].0.clone(), &c.specs[idx].1);
    let m = match c.parse(cmd, name, &rest) {
        Ok(m) => m,
        Err(e) => {
            if e.starts_with('\u{0}') {
                let body = &e[1..];
                if body == "version" {
                    println!("typst {} ({})", cli::VERSION, cli::COMMIT);
                    std::process::exit(0);
                }
                let path = body.strip_prefix("help ").unwrap_or("");
                let tw = cli::term_width_pub();
                if path.is_empty() {
                    print!("{}", cli::render_help(cmd, name, &c.prog, true, tw));
                } else {
                    print!("{}", cli::render_help(cmd, path, &c.prog, true, tw));
                }
                std::process::exit(0);
            }
            eprint!("{}", e);
            std::process::exit(2);
        }
    };
    let _ = cert;
    match name.as_str() {
        "fonts" => fonts::run(&m, &c, color.as_deref()),
        "info" => crate_info(&m, color.as_deref()),
        "completions" => completions(&m),
        "eval" => eval::run(&m, &c, color.as_deref()),
        "compile" => compile::run(&m, &c, color.as_deref()),
        _ => {
            eprintln!("unimplemented: {}", name);
            std::process::exit(1);
        }
    }
}
