//! File system / font discovery world.
use std::path::PathBuf;

pub struct World {
    pub root: Option<PathBuf>,
    pub font_paths: Vec<PathBuf>,
    pub ignore_system_fonts: bool,
    pub ignore_embedded_fonts: bool,
    pub package_path: Option<PathBuf>,
    pub package_cache_path: Option<PathBuf>,
    pub creation_timestamp: Option<i64>,
    pub inputs: Vec<(String, String)>,
}

impl World {
    pub fn package_path(&self) -> PathBuf {
        match &self.package_path {
            Some(p) => p.clone(),
            None => xdg_data().join("typst").join("packages"),
        }
    }
    pub fn package_cache_path(&self) -> PathBuf {
        match &self.package_cache_path {
            Some(p) => p.clone(),
            None => xdg_cache().join("typst").join("packages"),
        }
    }
}

pub fn home() -> PathBuf {
    std::env::var("HOME").map(PathBuf::from).unwrap_or_else(|_| PathBuf::from("/"))
}

pub fn xdg_data() -> PathBuf {
    match std::env::var("XDG_DATA_HOME") {
        Ok(v) if !v.is_empty() => PathBuf::from(v),
        _ => home().join(".local").join("share"),
    }
}

pub fn xdg_cache() -> PathBuf {
    match std::env::var("XDG_CACHE_HOME") {
        Ok(v) if !v.is_empty() => PathBuf::from(v),
        _ => home().join(".cache"),
    }
}
