//! Minimal TrueType/OpenType font parsing (name tables, metrics, glyph outlines).

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Style {
    Normal,
    Italic,
    Oblique,
}

impl Style {
    pub fn name(&self) -> &'static str {
        match self {
            Style::Normal => "Normal",
            Style::Italic => "Italic",
            Style::Oblique => "Oblique",
        }
    }
}

pub struct Reader<'a> {
    pub d: &'a [u8],
    pub pos: usize,
}

impl<'a> Reader<'a> {
    pub fn new(d: &'a [u8]) -> Self {
        Reader { d, pos: 0 }
    }
    pub fn u8(&mut self) -> u8 {
        let v = self.d.get(self.pos).copied().unwrap_or(0);
        self.pos += 1;
        v
    }
    pub fn i8(&mut self) -> i8 {
        self.u8() as i8
    }
    pub fn u16(&mut self) -> u16 {
        let a = self.u8() as u16;
        let b = self.u8() as u16;
        (a << 8) | b
    }
    pub fn i16(&mut self) -> i16 {
        self.u16() as i16
    }
    pub fn u32(&mut self) -> u32 {
        let a = self.u16() as u32;
        let b = self.u16() as u32;
        (a << 16) | b
    }
    pub fn i32(&mut self) -> i32 {
        self.u32() as i32
    }
    pub fn seek(&mut self, p: usize) {
        self.pos = p;
    }
    pub fn skip(&mut self, n: usize) {
        self.pos += n;
    }
    pub fn tag(&mut self) -> [u8; 4] {
        let mut t = [0u8; 4];
        for i in 0..4 {
            t[i] = self.u8();
        }
        t
    }
}

/// A single font in a font file (index into a collection).
pub struct Sfnt {
    pub data: Vec<u8>,
    /// Offset of the table directory for this face.
    pub base: usize,
}

impl Sfnt {
    pub fn parse(data: Vec<u8>, index: usize) -> Option<Sfnt> {
        let mut r = Reader::new(&data);
        let tag = r.tag();
        let base;
        if tag == *b"ttcf" {
            r.u32();
            let n = r.u32() as usize;
            if index >= n {
                return None;
            }
            let mut off = None;
            for _ in 0..n {
                let o = r.u32() as usize;
                if index == 0 {
                    off = Some(o);
                }
            }
            base = off?;
        } else {
            base = 0;
        }
        Some(Sfnt { data, base })
    }

    pub fn table(&self, tag: &[u8; 4]) -> Option<&[u8]> {
        let mut r = Reader::new(&self.data);
        r.seek(self.base + 4);
        let n = r.u16() as usize;
        for _ in 0..n {
            let t = r.tag();
            let _checksum = r.u32();
            let off = r.u32() as usize;
            let len = r.u32() as usize;
            if &t == tag {
                let end = (off + len).min(self.data.len());
                if off <= end {
                    return Some(&self.data[off..end]);
                }
            }
        }
        None
    }

    pub fn units_per_em(&self) -> u16 {
        match self.table(b"head") {
            Some(t) => {
                let mut r = Reader::new(t);
                r.seek(18);
                r.u16()
            }
            None => 1000,
        }
    }

    pub fn mac_style(&self) -> u16 {
        match self.table(b"head") {
            Some(t) => {
                let mut r = Reader::new(t);
                r.seek(44);
                r.u16()
            }
            None => 0,
        }
    }

    pub fn family(&self) -> Option<String> {
        self.name_entry(16).or_else(|| self.name_entry(1))
    }
    pub fn subfamily(&self) -> Option<String> {
        self.name_entry(17).or_else(|| self.name_entry(2))
    }
    pub fn full_name(&self) -> Option<String> {
        self.name_entry(4)
    }

    /// Looks up a name record, preferring Windows English, then any English,
    /// then any record.
    fn name_entry(&self, id: u16) -> Option<String> {
        let t = self.table(b"name")?;
        let mut r = Reader::new(t);
        r.u16();
        let count = r.u16() as usize;
        let storage = r.u16() as usize;
        let mut best: Option<(u8, String)> = None;
        for _ in 0..count {
            let pid = r.u16();
            let eid = r.u16();
            let lid = r.u16();
            let nid = r.u16();
            let len = r.u16() as usize;
            let off = r.u16() as usize;
            if nid != id {
                continue;
            }
            let end = (storage + off + len).min(t.len());
            if storage + off > end {
                continue;
            }
            let bytes = &t[storage + off..end];
            let score: u8 = if pid == 3 && (eid == 1 || eid == 0) {
                3
            } else if pid == 0 {
                2
            } else if pid == 1 && eid == 0 {
                1
            } else {
                0
            };
            let s = if pid == 3 || pid == 0 {
                utf16be(bytes)
            } else {
                latin1(bytes)
            };
            if best.as_ref().map(|(b, _)| score > *b).unwrap_or(true) {
                best = Some((score, s));
            }
        }
        best.map(|(_, s)| s)
    }

    pub fn weight(&self) -> u16 {
        if let Some(t) = self.table(b"OS/2") {
            let mut r = Reader::new(t);
            r.u16();
            if r.pos + 2 <= t.len() {
                r.seek(4);
                let w = r.u16();
                if w > 0 {
                    return w;
                }
            }
        }
        400
    }

    pub fn width_class(&self) -> u16 {
        if let Some(t) = self.table(b"OS/2") {
            let mut r = Reader::new(t);
            if t.len() >= 88 {
                r.seek(86);
                return r.u16();
            }
        }
        5
    }

    pub fn style(&self) -> Style {
        let italic = self.mac_style() & 0b1 != 0;
        let sub = self.subfamily().unwrap_or_default();
        let oblique = sub.to_lowercase().contains("oblique");
        if italic {
            Style::Italic
        } else if oblique {
            Style::Oblique
        } else {
            Style::Normal
        }
    }

    // ---- metrics ----------------------------------------------------------

    pub fn hhea(&self) -> Option<(i16, i16, u16, i16, i16)> {
        let t = self.table(b"hhea")?;
        let mut r = Reader::new(t);
        r.skip(4);
        let asc = r.i16();
        let desc = r.i16();
        let gap = r.i16();
        let adv_max = r.i16();
        let min_ls = r.i16();
        let min_rs = r.i16();
        let _ = (adv_max, min_ls, min_rs);
        let mut r2 = Reader::new(t);
        r2.seek(34);
        let n = r2.u16();
        Some((asc, desc, n, gap, 0))
    }

    /// Maps a codepoint to a glyph id.
    pub fn glyph_id(&self, c: char) -> Option<u16> {
        let t = self.table(b"cmap")?;
        let mut r = Reader::new(t);
        r.u16();
        let n = r.u16() as usize;
        let mut best: Option<(usize, usize, usize)> = None;
        for i in 0..n {
            let pid = r.u16() as usize;
            let eid = r.u16() as usize;
            let off = r.u32() as usize;
            let score = match (pid, eid) {
                (3, 10) => 4,
                (0, 4) | (0, 6) => 3,
                (3, 1) => 2,
                (0, 3) => 1,
                _ => 0,
            };
            if best.map(|(s, _, _)| score > s).unwrap_or(true) {
                best = Some((score, i, off));
            }
        }
        let (_, _, off) = best?;
        let mut sub = Reader::new(t);
        sub.seek(off);
        let fmt = sub.u16();
        match fmt {
            0 => {
                sub.u16();
                sub.u16();
                let lang = sub.u16();
                let _ = lang;
                let idx = c as usize;
                if idx < 256 {
                    sub.seek(off + 6 + idx);
                    let g = sub.u8() as u16;
                    if g != 0 {
                        return Some(g);
                    }
                }
                None
            }
            4 => {
                sub.seek(off + 6);
                let seg_x2 = sub.u16() as usize;
                let segs = seg_x2 / 2;
                let mut ends = vec![];
                for _ in 0..segs {
                    ends.push(sub.u16());
                }
                let _pad = sub.u16();
                let mut starts = vec![];
                for _ in 0..segs {
                    starts.push(sub.u16());
                }
                let mut deltas = vec![];
                for _ in 0..segs {
                    deltas.push(sub.i16());
                }
                let mut range_offs = vec![];
                for _ in 0..segs {
                    range_offs.push(sub.u16());
                }
                let code = c as u32;
                for i in (0..segs).rev() {
                    if (starts[i] as u32) <= code && code <= ends[i] as u32 {
                        if range_offs[i] == 0 {
                            let g = (code as i64 + deltas[i] as i64) as u16;
                            return if g == 0 { None } else { Some(g) };
                        }
                        let addr = off + 14 + i * 2 + range_offs[i] as usize + (code as usize - starts[i] as usize) * 2;
                        if addr + 1 >= t.len() {
                            return None;
                        }
                        let mut r2 = Reader::new(t);
                        r2.seek(addr);
                        let g = r2.u16();
                        if g == 0 {
                            return None;
                        }
                        let g = (g as i64 + deltas[i] as i64) as u16;
                        return if g == 0 { None } else { Some(g) };
                    }
                }
                None
            }
            12 => {
                sub.seek(off + 6 + 4);
                let n = sub.u32() as usize;
                for _ in 0..n {
                    let start = sub.u32();
                    let end = sub.u32();
                    let start_gid = sub.u32();
                    let code = c as u32;
                    if code >= start && code <= end {
                        let g = start_gid + (code - start);
                        return if g == 0 { None } else { Some(g as u16) };
                    }
                }
                None
            }
            _ => None,
        }
    }

    /// Advance width of a glyph in font units.
    pub fn advance(&self, gid: u16) -> i32 {
        let (_, _, n, _, _) = match self.hhea() {
            Some(h) => h,
            None => return 0,
        };
        let t = match self.table(b"hmtx") {
            Some(t) => t,
            None => return 0,
        };
        let idx = if (gid as usize) < n as usize {
            gid as usize
        } else {
            n as usize - 1
        };
        let mut r = Reader::new(t);
        r.seek(idx * 4);
        r.u16() as i32
    }

    /// Kerning adjustment in font units for a glyph pair.
    pub fn kern(&self, left: u16, right: u16) -> i32 {
        let t = match self.table(b"kern") {
            Some(t) => t,
            None => return 0,
        };
        let mut r = Reader::new(t);
        r.u16();
        let n = r.u16() as usize;
        for _ in 0..n {
            let ver = r.u16();
            let len = r.u32() as usize;
            let cov = r.u16();
            let start = r.pos;
            if cov & 1 == 0 {
                r.seek(start + len - 6);
                continue;
            }
            let n_pairs = r.u16() as usize;
            let fmt = r.u16();
            if fmt != 0 {
                r.seek(start + len - 6);
                continue;
            }
            for _ in 0..n_pairs {
                let l = r.u16();
                let rr = r.u16();
                let v = r.i16();
                if l == left && rr == right {
                    return v as i32;
                }
            }
            r.seek(start + len - 6);
        }
        0
    }

    /// Glyph outline as quadratic/cubic path segments in font units.
    pub fn outline(&self, gid: u16) -> Option<Outline> {
        let loca = self.table(b"loca")?;
        let glyf = self.table(b"glyf")?;
        let mut r = Reader::new(loca);
        let n = r.u16();
        let off = if (gid as usize) >= n as usize {
            r.seek(gid as usize * 4);
            let a = r.u32() as usize;
            let b = r.u32() as usize;
            if a == b {
                return Some(Outline::default());
            }
            (a, b)
        } else {
            r.seek(gid as usize * 2);
            let a = r.u16() as usize * 2;
            let b = r.u16() as usize * 2;
            if a == b {
                return Some(Outline::default());
            }
            (a, b)
        };
        let mut r = Reader::new(glyf);
        r.seek(off.0);
        let ncont = r.i16();
        if ncont <= 0 {
            return Some(Outline::default());
        }
        let mut ends = vec![];
        for _ in 0..ncont {
            ends.push(r.u16() as usize);
        }
        let npts = ends.last().copied().unwrap_or(0) + 1;
        let ilen = r.u16() as usize;
        r.seek(off.0 + ilen);
        let mut flags = vec![];
        while flags.len() < npts {
            let f = r.u8();
            flags.push(f);
            if f & 8 != 0 {
                let rep = r.u8() as usize;
                for _ in 0..rep {
                    if flags.len() < npts {
                        flags.push(f);
                    }
                }
            }
        }
        let mut xs = vec![];
        let mut x = 0i32;
        for f in &flags {
            if f & 2 != 0 {
                let d = r.u8() as i32;
                if f & 16 != 0 {
                    x += d;
                } else {
                    x -= d;
                }
            } else if f & 16 == 0 {
                x += r.i16() as i32;
            }
            xs.push(x);
        }
