        let mut r = Reader::new(&self.data);
        r.seek(self.base + 4);
        let n = r.u16() as usize;
        for _ in 0..n {
            let t = r.tag();
            let _checksum = r.u32();
            let off = r.u32() as usize;
            let len = r.u32() as usize;
            if &t == tag {
                let end = (off + len).min(self.data.len());
                if off <= end {
                    return Some(&self.data[off..end]);
                }
            }
        }
        None
    }

