        let t = self.table(b"name")?;
        let mut r = Reader::new(t);
        r.u16();
        let count = r.u16() as usize;
        let storage = r.u16() as usize;
        let mut best: Option<(u8, String)> = None;
        for _ in 0..count {
            let pid = r.u16();
            let eid = r.u16();
            let lid = r.u16();
            let nid = r.u16();
            let len = r.u16() as usize;
            let off = r.u16() as usize;
