                3
            } else if pid == 0 {
                2
            } else if pid == 1 && eid == 0 {
                1
            } else {
                0
            };
            let s = if pid == 3 || pid == 0 {
                utf16be(bytes)
            } else {
                latin1(bytes)
            };
            if best.as_ref().map(|(b, _)| score > *b).unwrap_or(true) {
                best = Some((score, s));
            }
        }
        best.map(|(_, s)| s)
    }

