        if let Some(t) = self.table(b"OS/2") {
            let mut r = Reader::new(t);
            r.u16();
            if r.pos + 2 <= t.len() {
                r.seek(4);
                let w = r.u16();
                if w > 0 {
                    return w;
                }
            }
        }
        400
    }

    pub fn width_class(&self) -> u16 {
        if let Some(t) = self.table(b"OS/2") {
            let mut r = Reader::new(t);
            if t.len() >= 88 {
                r.seek(86);
                return r.u16();
            }
        }
        5
    }

