        let mut r = Reader::new(t);
        r.u16();
        let n = r.u16() as usize;
        let mut best: Option<(usize, usize, usize)> = None;
        for i in 0..n {
            let pid = r.u16() as usize;
            let eid = r.u16() as usize;
            let off = r.u32() as usize;
            let score = match (pid, eid) {
                (3, 10) => 4,
                (0, 4) | (0, 6) => 3,
                (3, 1) => 2,
                (0, 3) => 1,
                _ => 0,
            };
            if best.map(|(s, _, _)| score > s).unwrap_or(true) {
                best = Some((score, i, off));
            }
        }
        let (_, _, off) = best?;
