            }
            4 => {
                sub.seek(off + 6);
                let seg_x2 = sub.u16() as usize;
                let segs = seg_x2 / 2;
                let mut ends = vec![];
                for _ in 0..segs {
                    ends.push(sub.u16());
                }
                let _pad = sub.u16();
                let mut starts = vec![];
                for _ in 0..segs {
                    starts.push(sub.u16());
                }
                let mut deltas = vec![];
                for _ in 0..segs {
                    deltas.push(sub.i16());
                }
                let mut range_offs = vec![];
                for _ in 0..segs {
                    range_offs.push(sub.u16());
                }
                let code = c as u32;
                for i in (0..segs).rev() {
                    if (starts[i] as u32) <= code && code <= ends[i] as u32 {
                        if range_offs[i] == 0 {
                            let g = (code as i64 + deltas[i] as i64) as u16;
                            return if g == 0 { None } else { Some(g) };
                        }
                        let addr = off + 14 + i * 2 + range_offs[i] as usize + (code as usize - starts[i] as usize) * 2;
                        if addr + 1 >= t.len() {
                            return None;
                        }
                        let mut r2 = Reader::new(t);
                        r2.seek(addr);
                        let g = r2.u16();
                        if g == 0 {
                            return None;
                        }
                        let g = (g as i64 + deltas[i] as i64) as u16;
                        return if g == 0 { None } else { Some(g) };
                    }
                }
                None
            }
            12 => {
                sub.seek(off + 6 + 4);
                let n = sub.u32() as usize;
                for _ in 0..n {
                    let start = sub.u32();
                    let end = sub.u32();
                    let start_gid = sub.u32();
                    let code = c as u32;
                    if code >= start && code <= end {
                        let g = start_gid + (code - start);
                        return if g == 0 { None } else { Some(g as u16) };
                    }
                }
                None
            }
            _ => None,
        }
    }

    /// Advance width of a glyph in font units.
    pub fn advance(&self, gid: u16) -> i32 {
        let (_, _, n, _, _) = match self.hhea() {
            Some(h) => h,
            None => return 0,
        };
        let t = match self.table(b"hmtx") {
            Some(t) => t,
            None => return 0,
        };
        let idx = if (gid as usize) < n as usize {
            gid as usize
        } else {
            n as usize - 1
        };
        let mut r = Reader::new(t);
        r.seek(idx * 4);
        r.u16() as i32
    }

    /// Kerning adjustment in font units for a glyph pair.
    pub fn kern(&self, left: u16, right: u16) -> i32 {
        let t = match self.table(b"kern") {
            Some(t) => t,
            None => return 0,
        };
        let mut r = Reader::new(t);
        r.u16();
        let n = r.u16() as usize;
        for _ in 0..n {
            let ver = r.u16();
            let len = r.u32() as usize;
            let cov = r.u16();
            let start = r.pos;
            if cov & 1 == 0 {
                r.seek(start + len - 6);
                continue;
            }
            let n_pairs = r.u16() as usize;
            let fmt = r.u16();
            if fmt != 0 {
                r.seek(start + len - 6);
                continue;
            }
            for _ in 0..n_pairs {
                let l = r.u16();
                let rr = r.u16();
                let v = r.i16();
                if l == left && rr == right {
                    return v as i32;
                }
            }
            r.seek(start + len - 6);
        }
        0
    }

    /// Glyph outline as quadratic/cubic path segments in font units.
    pub fn outline(&self, gid: u16) -> Option<Outline> {
        let loca = self.table(b"loca")?;
        let glyf = self.table(b"glyf")?;
