            r.seek(gid as usize * 4);
            let a = r.u32() as usize;
            let b = r.u32() as usize;
            if a == b {
                return Some(Outline::default());
            }
            (a, b)
        } else {
            r.seek(gid as usize * 2);
            let a = r.u16() as usize * 2;
            let b = r.u16() as usize * 2;
            if a == b {
                return Some(Outline::default());
            }
            (a, b)
        };
