        r.seek(off.0);
        let ncont = r.i16();
        if ncont <= 0 {
            return Some(Outline::default());
        }
        let mut ends = vec![];
        for _ in 0..ncont {
            ends.push(r.u16() as usize);
        }
        let npts = ends.last().copied().unwrap_or(0) + 1;
        let ilen = r.u16() as usize;
        r.seek(off.0 + ilen);
        let mut flags = vec![];
