            let f = r.u8();
            flags.push(f);
            if f & 8 != 0 {
                let rep = r.u8() as usize;
                for _ in 0..rep {
                    if flags.len() < npts {
                        flags.push(f);
                    }
                }
            }
        }
        let mut xs = vec![];
        let mut x = 0i32;
        for f in &flags {
            if f & 2 != 0 {
                let d = r.u8() as i32;
                if f & 16 != 0 {
                    x += d;
                } else {
                    x -= d;
                }
            } else if f & 16 == 0 {
                x += r.i16() as i32;
            }
            xs.push(x);
        }
        let mut ys = vec![];
        let mut y = 0i32;
        for f in &flags {
            if f & 4 != 0 {
                let d = r.u8() as i32;
                if f & 32 != 0 {
                    y += d;
                } else {
                    y -= d;
                }
            } else if f & 32 == 0 {
                y += r.i16() as i32;
            }
