        if let Some(t) = self.table(b"OS/2") {
            let mut r = Reader::new(t);
            r.u16();
            if r.pos + 2 <= t.len() {
                r.seek(4);
                let w = r.u16();
                if w > 0 {
                    return w;
                }
            }
        }
        400
    }

    pub fn width_class(&self) -> u16 {
        if let Some(t) = self.table(b"OS/2") {
            let mut r = Reader::new(t);
            if t.len() >= 88 {
                r.seek(86);
                return r.u16();
            }
        }
        5
    }

    pub fn style(&self) -> Style {
        let italic = self.mac_style() & 0b1 != 0;
        let sub = self.subfamily().unwrap_or_default();
        let oblique = sub.to_lowercase().contains("oblique");
        if italic {
            Style::Italic
        } else if oblique {
            Style::Oblique
        } else {
            Style::Normal
        }
    }

    // ---- metrics ----------------------------------------------------------

    pub fn hhea(&self) -> Option<(i16, i16, u16, i16, i16)> {
        let t = self.table(b"hhea")?;
        let mut r = Reader::new(t);
        r.skip(4);
        let asc = r.i16();
        let desc = r.i16();
        let gap = r.i16();
        let adv_max = r.i16();
        let min_ls = r.i16();
        let min_rs = r.i16();
        let _ = (adv_max, min_ls, min_rs);
        let mut r2 = Reader::new(t);
        r2.seek(34);
        let n = r2.u16();
        Some((asc, desc, n, gap, 0))
    }

    /// Maps a codepoint to a glyph id.
    pub fn glyph_id(&self, c: char) -> Option<u16> {
        let t = self.table(b"cmap")?;
        let mut r = Reader::new(t);
        r.u16();
        let n = r.u16() as usize;
        let mut best: Option<(usize, usize, usize)> = None;
        for i in 0..n {
            let pid = r.u16() as usize;
            let eid = r.u16() as usize;
            let off = r.u32() as usize;
            let score = match (pid, eid) {
                (3, 10) => 4,
                (0, 4) | (0, 6) => 3,
                (3, 1) => 2,
                (0, 3) => 1,
                _ => 0,
            };
            if best.map(|(s, _, _)| score > s).unwrap_or(true) {
                best = Some((score, i, off));
            }
        }
        let (_, _, off) = best?;
        let mut sub = Reader::new(t);
        sub.seek(off);
        let fmt = sub.u16();
        match fmt {
            0 => {
                sub.u16();
                sub.u16();
                let lang = sub.u16();
                let _ = lang;
                let idx = c as usize;
                if idx < 256 {
                    sub.seek(off + 6 + idx);
                    let g = sub.u8() as u16;
                    if g != 0 {
                        return Some(g);
                    }
                }
                None
            }
            4 => {
                sub.seek(off + 6);
                let seg_x2 = sub.u16() as usize;
                let segs = seg_x2 / 2;
                let mut ends = vec![];
                for _ in 0..segs {
                    ends.push(sub.u16());
                }
                let _pad = sub.u16();
                let mut starts = vec![];
                for _ in 0..segs {
                    starts.push(sub.u16());
                }
                let mut deltas = vec![];
                for _ in 0..segs {
                    deltas.push(sub.i16());
                }
                let mut range_offs = vec![];
                for _ in 0..segs {
                    range_offs.push(sub.u16());
                }
                let code = c as u32;
                for i in (0..segs).rev() {
                    if (starts[i] as u32) <= code && code <= ends[i] as u32 {
                        if range_offs[i] == 0 {
                            let g = (code as i64 + deltas[i] as i64) as u16;
                            return if g == 0 { None } else { Some(g) };
                        }
                        let addr = off + 14 + i * 2 + range_offs[i] as usize + (code as usize - starts[i] as usize) * 2;
                        if addr + 1 >= t.len() {
                            return None;
                        }
                        let mut r2 = Reader::new(t);
                        r2.seek(addr);
                        let g = r2.u16();
                        if g == 0 {
                            return None;
                        }
                        let g = (g as i64 + deltas[i] as i64) as u16;
                        return if g == 0 { None } else { Some(g) };
                    }
                }
                None
            }
            12 => {
                sub.seek(off + 6 + 4);
                let n = sub.u32() as usize;
                for _ in 0..n {
                    let start = sub.u32();
                    let end = sub.u32();
                    let start_gid = sub.u32();
                    let code = c as u32;
                    if code >= start && code <= end {
                        let g = start_gid + (code - start);
                        return if g == 0 { None } else { Some(g as u16) };
                    }
                }
                None
            }
            _ => None,
        }
    }

    /// Advance width of a glyph in font units.
    pub fn advance(&self, gid: u16) -> i32 {
        let (_, _, n, _, _) = match self.hhea() {
            Some(h) => h,
            None => return 0,
        };
        let t = match self.table(b"hmtx") {
            Some(t) => t,
            None => return 0,
        };
        let idx = if (gid as usize) < n as usize {
            gid as usize
        } else {
            n as usize - 1
        };
        let mut r = Reader::new(t);
        r.seek(idx * 4);
        r.u16() as i32
    }

    /// Kerning adjustment in font units for a glyph pair.
    pub fn kern(&self, left: u16, right: u16) -> i32 {
        let t = match self.table(b"kern") {
            Some(t) => t,
            None => return 0,
        };
        let mut r = Reader::new(t);
        r.u16();
        let n = r.u16() as usize;
        for _ in 0..n {
            let ver = r.u16();
            let len = r.u32() as usize;
            let cov = r.u16();
            let start = r.pos;
            if cov & 1 == 0 {
                r.seek(start + len - 6);
                continue;
            }
            let n_pairs = r.u16() as usize;
            let fmt = r.u16();
            if fmt != 0 {
                r.seek(start + len - 6);
                continue;
            }
            for _ in 0..n_pairs {
                let l = r.u16();
                let rr = r.u16();
                let v = r.i16();
                if l == left && rr == right {
                    return v as i32;
                }
            }
            r.seek(start + len - 6);
        }
        0
    }

    /// Glyph outline as quadratic/cubic path segments in font units.
    pub fn outline(&self, gid: u16) -> Option<Outline> {
        let loca = self.table(b"loca")?;
        let glyf = self.table(b"glyf")?;
        let mut r = Reader::new(loca);
        let n = r.u16();
        let off = if (gid as usize) >= n as usize {
            r.seek(gid as usize * 4);
            let a = r.u32() as usize;
            let b = r.u32() as usize;
            if a == b {
                return Some(Outline::default());
            }
            (a, b)
        } else {
            r.seek(gid as usize * 2);
            let a = r.u16() as usize * 2;
            let b = r.u16() as usize * 2;
            if a == b {
                return Some(Outline::default());
            }
            (a, b)
        };
        let mut r = Reader::new(glyf);
        r.seek(off.0);
        let ncont = r.i16();
        if ncont <= 0 {
            return Some(Outline::default());
        }
        let mut ends = vec![];
        for _ in 0..ncont {
            ends.push(r.u16() as usize);
        }
        let npts = ends.last().copied().unwrap_or(0) + 1;
        let ilen = r.u16() as usize;
        r.seek(off.0 + ilen);
        let mut flags = vec![];
        while flags.len() < npts {
            let f = r.u8();
            flags.push(f);
            if f & 8 != 0 {
                let rep = r.u8() as usize;
                for _ in 0..rep {
                    if flags.len() < npts {
                        flags.push(f);
                    }
                }
            }
        }
        let mut xs = vec![];
        let mut x = 0i32;
        for f in &flags {
            if f & 2 != 0 {
                let d = r.u8() as i32;
                if f & 16 != 0 {
                    x += d;
                } else {
                    x -= d;
                }
            } else if f & 16 == 0 {
                x += r.i16() as i32;
            }
            xs.push(x);
        }
        let mut ys = vec![];
        let mut y = 0i32;
        for f in &flags {
            if f & 4 != 0 {
                let d = r.u8() as i32;
                if f & 32 != 0 {
                    y += d;
                } else {
                    y -= d;
                }
            } else if f & 32 == 0 {
                y += r.i16() as i32;
            }
            ys.push(y);
        }
        let on_curve: Vec<bool> = flags.iter().map(|f| f & 1 != 0).collect();
        let mut contours = vec![];
        let mut start = 0usize;
        for e in ends {
            let mut pts = vec![];
            for i in start..=e {
                pts.push(Point {
                    x: xs[i],
                    y: ys[i],
                    on: on_curve[i],
                });
            }
            contours.push(pts);
            start = e + 1;
        }
        Some(Outline { contours })
    }
}

#[derive(Clone, Copy, Debug)]
pub struct Point {
    pub x: i32,
    pub y: i32,
    pub on: bool,
}

#[derive(Clone, Debug, Default)]
pub struct Outline {
    pub contours: Vec<Vec<Point>>,
}

fn utf16be(b: &[u8]) -> String {
    let mut out = String::new();
    let mut i = 0;
    while i + 1 < b.len() {
        let u = ((b[i] as u16) << 8) | b[i + 1] as u16;
        i += 2;
        if (0xD800..0xDC00).contains(&u) && i + 1 < b.len() {
            let u2 = ((b[i] as u16) << 8) | b[i + 1] as u16;
            i += 2;
            let c = 0x10000 + ((u as u32 - 0xD800) << 10) + (u2 as u32 - 0xDC00);
            if let Some(ch) = char::from_u32(c) {
                out.push(ch);
            }
        } else if let Some(ch) = char::from_u32(u as u32) {
            out.push(ch);
        }
    }
    out
}

fn latin1(b: &[u8]) -> String {
    b.iter().map(|&c| c as char).collect()
}
