//! Font discovery and the `typst fonts` command.
use crate::cli::{Cli, Matches};
use std::path::{Path, PathBuf};

pub struct Face {
    pub family: String,
    pub style: crate::font::Style,
    pub weight: u16,
    pub stretch: u16,
    pub path: String,
}

