        mk("Libertinus Serif", it, 600),
        mk("New Computer Modern", n, 400),
        mk("New Computer Modern", n, 700),
        mk("New Computer Modern", it, 400),
        mk("New Computer Modern", it, 700),
        mk("New Computer Modern Math", n, 700),
        mk("New Computer Modern Math", n, 450),
        mk("New Computer Modern Math", n, 400),
    ]
}

fn is_font_file(p: &Path) -> bool {
    match p.extension().and_then(|e| e.to_str()) {
        Some(e) => matches!(
            e.to_lowercase().as_str(),
            "ttf" | "otf" | "ttc" | "otc" | "dfont"
        ),
        None => false,
    }
}

fn read_face(p: &Path, idx: usize) -> Option<crate::font::Sfnt> {
    let data = std::fs::read(p).ok()?;
    crate::font::Sfnt::parse(data, idx)
}

fn scan_dir(dir: &Path, out: &mut Vec<Face>, depth: usize) {
    if depth > 10 {
        return;
    }
    let entries = match std::fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };
    for e in entries.flatten() {
        let p = e.path();
        let meta = match std::fs::metadata(&p) {
            Ok(m) => m,
            Err(_) => continue,
        };
        if meta.is_dir() {
            scan_dir(&p, out, depth + 1);
            continue;
        }
        if !is_font_file(&p) {
            continue;
        }
        let mut idx = 0;
        loop {
            let f = match read_face(&p, idx) {
                Some(f) => f,
                None => break,
            };
            let fam = f.family().unwrap_or_else(|| {
                p.file_stem()
                    .and_then(|s| s.to_str())
                    .unwrap_or("Unknown")
                    .to_string()
            });
            out.push(Face {
                family: fam,
                style: f.style(),
                weight: f.weight(),
                stretch: stretch_of(f.width_class()),
                path: p.to_string_lossy().to_string(),
            });
            idx += 1;
            if idx > 8 {
                break;
            }
        }
    }
}

fn stretch_of(class: u16) -> u16 {
    match class {
        1 => 500,
        2 => 625,
        3 => 750,
        4 => 875,
        5 => 1000,
        6 => 1125,
        7 => 1250,
        8 => 1500,
        9 => 2000,
        _ => 1000,
    }
}

/// Expands `~` at the start of a path.
pub fn expand_tilde(p: &str) -> PathBuf {
    if let Some(rest) = p.strip_prefix("~/") {
        return crate::world::home().join(rest);
    }
    if p == "~" {
        return crate::world::home();
    }
    PathBuf::from(p)
}

/// Reads `<dir>` entries from a fontconfig file.
fn fontconfig_dirs(path: &Path) -> Vec<PathBuf> {
    let data = match std::fs::read_to_string(path) {
        Ok(d) => d,
        Err(_) => return vec![],
    };
    let mut dirs = vec![];
    let mut rest = data.as_str();
    while let Some(i) = rest.find("<dir") {
        let after = &rest[i..];
        let open = match after.find('>') {
            Some(o) => o,
            None => break,
        };
        let attrs = &after[4..open];
        let value_start = open + 1;
        let close = match rest[value_start..].find("</dir>") {
            Some(c) => value_start + c,
            None => break,
        };
        let value = &rest[value_start..close];
        let xdg = attrs.contains("prefix=\"xdg\"");
        let cwd = attrs.contains("prefix=\"cwd\"");
        rest = &rest[close + 6..];
        if value.starts_with('~') {
            dirs.push(expand_tilde(value));
        } else if xdg {
            dirs.push(crate::world::xdg_data().join(value));
        } else if cwd {
            dirs.push(std::env::current_dir().unwrap_or_default().join(value));
        } else {
            dirs.push(PathBuf::from(value));
        }
    }
    dirs
}

/// The system font directories.
pub fn system_dirs() -> Vec<PathBuf> {
    let conf = match std::env::var("FONTCONFIG_FILE") {
        Ok(v) if !v.is_empty() => PathBuf::from(v),
        _ => match std::env::var("FONTCONFIG_PATH") {
            Ok(v) if !v.is_empty() => PathBuf::from(v).join("fonts.conf"),
            _ => PathBuf::from("/etc/fonts/fonts.conf"),
        },
    };
    let dirs = fontconfig_dirs(&conf);
    if dirs.is_empty() {
        vec![
            PathBuf::from("/usr/share/fonts"),
            PathBuf::from("/usr/local/share/fonts"),
            crate::world::xdg_data().join("fonts"),
            crate::world::home().join(".fonts"),
        ]
    } else {
        dirs
    }
}

pub fn split_paths(s: &str) -> Vec<PathBuf> {
    s.split(if cfg!(windows) { ';' } else { ':' })
        .filter(|s| !s.is_empty())
        .map(expand_tilde)
        .collect()
}

pub struct FontBook {
    pub faces: Vec<Face>,
}

impl FontBook {
    pub fn families(&self) -> Vec<String> {
        let mut names: Vec<String> = self.faces.iter().map(|f| f.family.clone()).collect();
        names.sort();
        names.dedup();
        names
    }
}

pub fn discover(
    custom: &[PathBuf],
    ignore_system: bool,
    ignore_embedded: bool,
) -> FontBook {
    let mut faces: Vec<Face> = vec![];
    if !ignore_system {
        for d in system_dirs() {
            scan_dir(&d, &mut faces, 0);
        }
    }
    for d in custom {
        scan_dir(d, &mut faces, 0);
    }
    if !ignore_embedded {
        faces.extend(embedded());
    }
    FontBook { faces }
}

pub fn run(m: &Matches, _c: &Cli, _color: Option<&str>) {
    let mut custom: Vec<PathBuf> = m
        .get_all("font-path")
        .iter()
        .flat_map(|s| split_paths(s))
        .collect();
    if let Some(env) = std::env::var("TYPST_FONT_PATHS").ok().filter(|s| !s.is_empty()) {
        for p in split_paths(&env) {
            if !custom.contains(&p) {
                custom.push(p);
            }
        }
    }
    let ignore_system = m.has("ignore-system-fonts")
        || truthy(&std::env::var("TYPST_IGNORE_SYSTEM_FONTS").unwrap_or_default());
    let ignore_embedded = m.has("ignore-embedded-fonts")
        || truthy(&std::env::var("TYPST_IGNORE_EMBEDDED_FONTS").unwrap_or_default());
    let book = discover(&custom, ignore_system, ignore_embedded);
    if m.has("variants") {
        for fam in book.families() {
            println!("{}", fam);
            for f in book.faces.iter().filter(|f| f.family == fam) {
                println!(
                    "- Style: {}, Weight: {}, Stretch: FontStretch({}), Path: {}",
                    f.style.name(),
                    f.weight,
                    f.stretch,
                    f.path
                );
            }
        }
    } else {
        for fam in book.families() {
            println!("{}", fam);
        }
    }
    std::process::exit(0);
}

pub fn truthy(s: &str) -> bool {
    matches!(s.to_lowercase().as_str(), "1" | "true" | "yes" | "on")
}
