# check mac_style for DejaVu Bold fonts via python
import struct
for f in ['DejaVuSans-Bold','DejaVuSans','DejaVuSerif-Bold','DejaVuSerif']:
    d=open('/usr/share/fonts/truetype/dejavu/%s.ttf'%f,'rb').read()
    n=struct.unpack('>H',d[4:6])[0]
    for i in range(n):
        off=12+16*i
        tag=d[off:off+4].decode('latin1')
        if tag=='head':
            o=struct.unpack('>I',d[off+8:off+12])[0]
            print(f,'macStyle',struct.unpack('>H',d[o+44:o+46])[0])
PYEOF"}

