//! The `typst info` command.
use crate::cli::{Cli, Matches};
use std::path::PathBuf;

pub const ENV_VARS: &[&str] = &[
    "TYPST_CERT",
    "TYPST_FEATURES",
    "TYPST_FONT_PATHS",
    "TYPST_IGNORE_SYSTEM_FONTS",
    "TYPST_IGNORE_EMBEDDED_FONTS",
    "TYPST_PACKAGE_CACHE_PATH",
    "TYPST_PACKAGE_PATH",
    "TYPST_ROOT",
    "TYPST_UPDATE_BACKUP_PATH",
    "SOURCE_DATE_EPOCH",
    "XDG_CACHE_HOME",
    "XDG_DATA_HOME",
    "FONTCONFIG_FILE",
    "OPENSSL_CONF",
    "NO_COLOR",
    "NO_PROXY",
    "HTTP_PROXY",
    "HTTPS_PROXY",
    "ALL_PROXY",
];

pub struct Info {
    pub features: Vec<String>,
    pub font_paths: Vec<String>,
    pub system_fonts: bool,
    pub embedded_fonts: bool,
    pub package_path: PathBuf,
    pub package_cache_path: PathBuf,
}

pub fn gather(m: &Matches) -> Info {
    let feats = std::env::var("TYPST_FEATURES").unwrap_or_default();
    let features: Vec<String> = feats
        .split(',')
        .filter(|s| !s.is_empty())
        .map(|s| s.to_string())
        .collect();
    let mut font_paths: Vec<String> = vec![];
    for s in m.get_all("--font-path") {
        for p in crate::fonts::split_paths(s) {
            font_paths.push(p.to_string_lossy().to_string());
        }
    }
    if let Some(e) = std::env::var("TYPST_FONT_PATHS").ok().filter(|s| !s.is_empty()) {
        for p in crate::fonts::split_paths(&e) {
            if !font_paths.contains(&p.to_string_lossy().to_string()) {
                font_paths.push(p.to_string_lossy().to_string());
            }
        }
    }
    let system = !(m.has("--ignore-system-fonts")
        || crate::fonts::truthy(&std::env::var("TYPST_IGNORE_SYSTEM_FONTS").unwrap_or_default()));
    let embedded = !(m.has("--ignore-embedded-fonts")
        || crate::fonts::truthy(&std::env::var("TYPST_IGNORE_EMBEDDED_FONTS").unwrap_or_default()));
    let package_path = m
        .get("--package-path")
        .map(PathBuf::from)
        .or_else(|| std::env::var("TYPST_PACKAGE_PATH").ok().filter(|s| !s.is_empty()).map(PathBuf::from))
        .unwrap_or_else(|| crate::world::xdg_data().join("typst").join("packages"));
    let package_cache_path = m
        .get("--package-cache-path")
        .map(PathBuf::from)
        .or_else(|| std::env::var("TYPST_PACKAGE_CACHE_PATH").ok().filter(|s| !s.is_empty()).map(PathBuf::from))
        .unwrap_or_else(|| crate::world::xdg_cache().join("typst").join("packages"));
    Info {
        features,
        font_paths,
        system_fonts: system,
        embedded_fonts: embedded,
        package_path,
        package_cache_path,
    }
}

fn has_feature(i: &Info, name: &str) -> bool {
    i.features.iter().any(|f| f == name)
}

fn pkg(p: &PathBuf) -> String {
    p.to_string_lossy().to_string()
}

pub fn run(m: &Matches, _c: &Cli, _color: Option<&str>) {
    let i = gather(m);
    let format = m.get("--format").unwrap_or("");
    match format {
        "json" => {
            let mut s = String::new();
            let pretty = m.has("--pretty");
            write_json(&i, &mut s, pretty, 0);
            println!("{}", s);
        }
        "yaml" => {
            let mut s = String::new();
            write_yaml(&i, &mut s, 0);
            print!("{}", s);
        }
        _ => human(&i),
    }
    std::process::exit(0);
}

fn human(i: &Info) {
    println!("Version {} ({}, linux on x86_64)", crate::cli::VERSION, crate::cli::COMMIT);
    println!();
    println!("Build settings");
    println!("  self-update off (Update Typst via `typst update`)");
    println!("  http-server on  (Serve HTML via `typst watch`)");
    println!();
    println!("Features");
    println!(
        "  {:<11} {:<3} (Experimental HTML support)",
        "html",
        if has_feature(i, "html") { "on" } else { "off" }
    );
    println!(
        "  {:<11} {:<3} (Experimental accessibility additions)",
        "a11y-extras",
        if has_feature(i, "a11y-extras") { "on" } else { "off" }
    );
    println!();
    println!("Fonts");
    if i.font_paths.is_empty() {
        println!("  Custom font paths <none>");
    } else {
        println!("  Custom font paths");
        for p in &i.font_paths {
            println!("    - {}", p);
        }
    }
    println!(
        "  {:<14} {}",
        "System fonts",
        if i.system_fonts { "on" } else { "off" }
    );
    println!(
        "  {:<14} {}",
        "Embedded fonts",
        if i.embedded_fonts { "on" } else { "off" }
    );
    println!();
    println!("Packages");
    println!("  {:<18} {}", "Package path", pkg(&i.package_path));
    println!("  {:<18} {}", "Package cache path", pkg(&i.package_cache_path));
    println!();
    println!("Environment variables");
    for v in ENV_VARS {
        let val = std::env::var(v).ok();
        println!("  {:<27} {}", v, val.unwrap_or_else(|| "<unset>".to_string()));
    }
}

fn jstr(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn ind(n: usize) -> String {
    "  ".repeat(n)
}

fn write_json(i: &Info, out: &mut String, pretty: bool, level: usize) {
    let p = |k: &str, v: &str, first: bool, level: usize| {
        if pretty {
            out.push_str(&format!(
                "{}{}{}: {},\n",
                if first { "" } else { "" },
                ind(level),
                k,
                v
            ));
        } else {
            out.push_str(&format!("{}{}:{},", if first { "" } else { "" }, k, v));
        }
    };
    let _ = p;
    let sep = if pretty { "\n" } else { "" };
    let kv = |out: &mut String, k: &str, v: &str| {
        if pretty {
            out.push_str(&format!("{}{}: {},\n", ind(level + 1), jstr(k), v));
        } else {
            out.push_str(&format!("{}:{},", jstr(k), v));
        }
    };
    out.push('{');
    kv(out, "version", &jstr(crate::cli::VERSION));
    out.push_str(&sep.replace("", ""));
    if pretty {
        out.push_str(&ind(level + 1));
    }
    out.push_str("\"build\":{");
    kv(out, "commit", &jstr(crate::cli::COMMIT_FULL));
    if pretty {
        out.push_str(&ind(level + 1));
    }
    out.push_str("\"platform\":{");
    kv(out, "os", &jstr("linux"));
    if pretty {
        out.push_str(&ind(level + 1));
    }
    out.push_str("\"arch\":");
    out.push_str(&jstr("x86_64"));
    out.pop();
    if pretty {
        out.push('}');
        out.push(',');
        out.push('\n');
        out.push_str(&ind(level + 1));
    } else {
        out.push_str("},");
    }
    out.push_str("\"settings\":{");
    kv(out, "self-update", "false");
    if pretty {
        out.push_str(&ind(level + 1));
    }
    out.push_str("\"http-server\":true");
    out.pop();
    out.push('}');
    out.pop();
    out.push('}');
    out.push(',');
    if pretty {
        out.push('\n');
        out.push_str(&ind(level + 1));
    }
    out.push_str("\"features\":{");
    kv(out, "html", if has_feature(i, "html") { "true" } else { "false" });
    if pretty {
        out.push_str(&ind(level + 1));
    }
    out.push_str("\"a11y-extras\":");
    out.push_str(if has_feature(i, "a11y-extras") { "true" } else { "false" });
    out.pop();
    out.push('}');
    out.push(',');
    if pretty {
        out.push('\n');
        out.push_str(&ind(level + 1));
    }
    out.push_str("\"fonts\":{");
    if pretty {
        out.push_str(&ind(level + 2));
    }
    out.push_str("\"paths\":[");
    for (n, p) in i.font_paths.iter().enumerate() {
        if n > 0 {
            out.push(',');
        }
        if pretty {
            out.push_str("\n");
            out.push_str(&ind(level + 3));
        }
        out.push_str(&jstr(p));
    }
    if pretty && !i.font_paths.is_empty() {
        out.push('\n');
        out.push_str(&ind(level + 2));
    }
    out.push(']');
    out.push(',');
    if pretty {
        out.push_str(&ind(level + 2));
    }
    out.push_str("\"system\":");
    out.push_str(if i.system_fonts { "true" } else { "false" });
    out.push(',');
    if pretty {
        out.push_str(&ind(level + 2));
    }
    out.push_str("\"embedded\":");
    out.push_str(if i.embedded_fonts { "true" } else { "false" });
    if pretty {
        out.push('\n');
        out.push_str(&ind(level + 1));
    }
    out.push('}');
    out.push(',');
    if pretty {
        out.push('\n');
        out.push_str(&ind(level + 1));
    }
    out.push_str("\"packages\":{");
    kv(out, "package-path", &jstr(&pkg(&i.package_path)));
    if pretty {
        out.push_str(&ind(level + 1));
    }
    out.push_str("\"package-cache-path\":");
    out.push_str(&jstr(&pkg(&i.package_cache_path)));
    out.pop();
    if pretty {
        out.push('}');
        out.push(',');
        out.push('\n');
        out.push_str(&ind(level + 1));
    } else {
        out.push_str("},");
    }
    out.push_str("\"env\":{");
    for (n, v) in ENV_VARS.iter().enumerate() {
        if n > 0 {
            out.push(',');
        }
        if pretty {
            out.push('\n');
            out.push_str(&ind(level + 2));
        }
        out.push_str(&format!("{}:", jstr(v)));
        match std::env::var(v) {
            Ok(val) => out.push_str(&jstr(&val)),
            Err(_) => out.push_str("null"),
        }
    }
    if pretty {
        out.push('\n');
        out.push_str(&ind(level + 1));
    }
    out.push('}');
    if pretty {
        out.push('\n');
        out.push_str(&ind(level));
    }
    out.push('}');
}

fn write_yaml(i: &Info, out: &mut String, level: usize) {
    let p = ind(level);
    out.push_str(&format!("{}version: {}\n", p, crate::cli::VERSION));
    out.push_str(&format!("{}build:\n", p));
    out.push_str(&format!("{}  commit: {}\n", p, crate::cli::COMMIT_FULL));
    out.push_str(&format!("{}  platform:\n", p));
    out.push_str(&format!("{}    os: linux\n", p));
    out.push_str(&format!("{}    arch: x86_64\n", p));
    out.push_str(&format!("{}  settings:\n", p));
    out.push_str(&format!("{}    self-update: false\n", p));
    out.push_str(&format!("{}    http-server: true\n", p));
    out.push_str(&format!("{}features:\n", p));
    out.push_str(&format!("{}  html: {}\n", p, has_feature(i, "html")));
    out.push_str(&format!(
        "{}  a11y-extras: {}\n",
        p,
        has_feature(i, "a11y-extras")
    ));
    out.push_str(&format!("{}fonts:\n", p));
    out.push_str(&format!("{}  paths:\n", p));
    if i.font_paths.is_empty() {
        out.push_str(&format!("{}    []\n", p));
    } else {
        for f in &i.font_paths {
            out.push_str(&format!("{}    - {}\n", p, f));
        }
    }
    out.push_str(&format!("{}  system: {}\n", p, i.system_fonts));
    out.push_str(&format!("{}  embedded: {}\n", p, i.embedded_fonts));
    out.push_str(&format!("{}packages:\n", p));
    out.push_str(&format!("{}  package-path: {}\n", p, pkg(&i.package_path)));
    out.push_str(&format!(
        "{}  package-cache-path: {}\n",
        p,
        pkg(&i.package_cache_path)
    ));
    out.push_str(&format!("{}env:\n", p));
    for v in ENV_VARS {
        match std::env::var(v) {
            Ok(val) => out.push_str(&format!("{}  {}: {}\n", p, v, val)),
            Err(_) => out.push_str(&format!("{}  {}: null\n", p, v)),
        }
    }
    out.push('\n');
}
