//! Typst values, content elements and their serialization.

#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    None,
    Bool(bool),
    Int(i64),
    Float(f64),
    Length(f64),
    Angle(f64),
    Ratio(f64),
    Fraction(f64),
    Str(String),
    Label(String),
    Bytes(Vec<u8>),
    Symbol(String),
    Dict(Dict),
    Array(ArrayV),
    Content(Content),
    Func(Func),
    Color(Color),
    Datetime(Datetime),
    Duration(f64),
    Type(&'static str),
    Alignment(&'static str),
    Direction(&'static str),
    Arguments(Vec<Argument>),
    Counter(Counter),
    State(State),
    Plugin(String),
}

#[derive(Clone, Debug, PartialEq)]
pub struct Argument {
    pub name: Option<String>,
    pub value: Box<Value>,
    pub span: usize,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Counter {
    pub key: String,
    pub repr: String,
}

#[derive(Clone, Debug, PartialEq)]
pub struct State {
    pub key: String,
    pub init: Box<Value>,
    pub repr: String,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Datetime {
    Date(i32, u32, u32),
    Time(u32, u32, u32, u32),
    Datetime(i32, u32, u32, u32, u32, u32),
}

/// Where a value came from, used to reproduce `repr` output.
#[derive(Clone, Debug, PartialEq)]
pub enum Repr {
    /// The literal source text (e.g. `[1, 2]`).
    Source(String),
    /// A canonical representation.
    Canonical,
}

#[derive(Clone, Debug, PartialEq)]
pub struct ArrayV {
    pub items: Vec<Value>,
    /// Source text of each item, when the array was written as a literal.
    pub item_sources: Option<Vec<String>>,
    pub repr: Repr,
}

#[derive(Clone, Debug, PartialEq, Default)]
pub struct Dict {
    pub items: Vec<(String, Value)>,
}

impl Dict {
    pub fn get(&self, k: &str) -> Option<&Value> {
        self.items.iter().find(|(n, _)| n == k).map(|(_, v)| v)
    }
    pub fn contains(&self, k: &str) -> bool {
        self.items.iter().any(|(n, _)| n == k)
    }
    pub fn len(&self) -> usize {
        self.items.len()
    }
    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }
    pub fn keys(&self) -> Vec<String> {
        self.items.iter().map(|(k, _)| k.clone()).collect()
    }
    pub fn values(&self) -> Vec<Value> {
        self.items.iter().map(|(_, v)| v.clone()).collect()
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct Func {
    pub name: Option<String>,
    pub kind: FuncKind,
    pub repr: String,
}

#[derive(Clone, Debug, PartialEq)]
pub enum FuncKind {
    Native(&'static str),
    Closure(Vec<String>, Option<usize>, Option<usize>, Vec<Value>, Box<Node>),
}

// Placeholder node type, filled in by the parser.
#[derive(Clone, Debug, PartialEq)]
pub struct Node;

#[derive(Clone, Debug, PartialEq)]
pub enum Color {
    Luma { components: Vec<f64>, repr: String, alpha: f64 },
    Rgb { components: Vec<f64>, repr: String, alpha: f64 },
    Cmyk { components: Vec<f64>, repr: String, alpha: f64 },
    Oklab { components: Vec<f64>, repr: String, alpha: f64 },
    Oklch { components: Vec<f64>, repr: String, alpha: f64 },
    Color { components: Vec<f64>, repr: String, alpha: f64 },
    Gradient,
}

impl Value {
    pub fn type_name(&self) -> &'static str {
        match self {
            Value::None => "none",
            Value::Bool(_) => "boolean",
            Value::Int(_) => "integer",
            Value::Float(_) => "float",
            Value::Length(_) => "length",
            Value::Angle(_) => "angle",
            Value::Ratio(_) => "ratio",
            Value::Fraction(_) => "fraction",
            Value::Str(_) => "string",
            Value::Label(_) => "label",
            Value::Bytes(_) => "bytes",
            Value::Symbol(_) => "symbol",
            Value::Dict(_) => "dictionary",
            Value::Array(_) => "array",
            Value::Content(_) => "content",
            Value::Func(_) => "function",
            Value::Color(_) => "color",
            Value::Datetime(_) => "datetime",
            Value::Duration(_) => "duration",
            Value::Type(_) => "type",
            Value::Alignment(_) => "alignment",
            Value::Direction(_) => "direction",
            Value::Arguments(_) => "arguments",
