            Value::Arguments(_) => "(..)".to_string(),
            Value::Counter(c) => c.repr.clone(),
            Value::State(s) => s.repr.clone(),
            Value::Plugin(p) => format!("plugin({})", p),
        }
    }
}

pub fn fmt_float(f: f64) -> String {
    if f.is_nan() {
        return "NaN".to_string();
    }
    if f.is_infinite() {
        return if f > 0.0 { "inf".to_string() } else { "-inf".to_string() };
    }
    let s = format!("{}", f);
    if s.contains('e') {
        return s;
    }
    s
}

fn format_length(v: f64) -> String {
    // Typst stores lengths in points; display in pt.
    format!("{}pt", crate::util::fmt_float(v))
}

fn format_angle(v: f64) -> String {
    format!("{}deg", crate::util::fmt_float(v))
}

pub fn format_str_repr(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

// ---------------------------------------------------------------------------
// Content
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, PartialEq)]
pub enum Elem {
    Text(String),
    Space,
    Linebreak,
    Smartquote { double: bool },
    Strong { body: Box<Content> },
    Emph { body: Box<Content> },
    Raw { text: String, block: bool, lang: Option<String> },
    Math { body: Box<Content> },
    MathFrac { num: Box<Content>, denom: Box<Content> },
    Symbol(String),
    Ref { target: String, supplement: Option<Box<Content>> },
    Label(String),
    Item { body: Box<Content> },
    Term { term: Box<Content>, description: Box<Content> },
    Parbreak,
    Sequence(Vec<Content>),
    Styled { body: Box<Content>, styles: Vec<Style> },
    Other { func: String, fields: Vec<(String, JVal)> },
}

#[derive(Clone, Debug, PartialEq)]
pub enum Style {
    TextSize(f64),
    TextFill(Color),
    TextFont(String),
    Bold(bool),
    Italic(bool),
    Other(String, JVal),
}

#[derive(Clone, Debug, PartialEq)]
pub enum JVal {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Arr(Vec<JVal>),
    Obj(Vec<(String, JVal)>),
}

#[derive(Clone, Debug, PartialEq, Default)]
pub struct Content {
    pub elems: Vec<Elem>,
}

impl Content {
    pub fn new() -> Content {
        Content { elems: vec![] }
    }
    pub fn text(s: &str) -> Content {
        Content { elems: vec![Elem::Text(s.to_string())] }
    }
    pub fn is_empty(&self) -> bool {
        self.elems.is_empty()
    }
    pub fn push(&mut self, e: Elem) {
        self.elems.push(e);
    }
    /// Appends another content, merging adjacent text elements.
    pub fn join(&mut self, other: Content) {
        for e in other.elems {
            self.push(e);
        }
    }
    /// Builds a sequence from children, flattening nested sequences and
    /// merging adjacent texts (as Typst's sequence builder does).
    pub fn sequence(children: Vec<Content>) -> Content {
        let mut out: Vec<Elem> = vec![];
        for c in children {
            for e in c.elems {
                match e {
                    Elem::Sequence(inner) => {
                        for e2 in inner {
                            push_merged(&mut out, e2);
                        }
                    }
                    e => push_merged(&mut out, e),
                }
            }
        }
        Content { elems: out }
    }
}

fn push_merged(out: &mut Vec<Elem>, e: Elem) {
    if let Elem::Text(t) = &e {
        if let Some(Elem::Text(prev)) = out.last_mut() {
            prev.push_str(t);
            return;
        }
    }
    out.push(e);
}

// ---------------------------------------------------------------------------
// JSON serialization of values
// ---------------------------------------------------------------------------

pub fn jstr(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}
