//! Typst markup and code parsing.

use crate::value::{Content, Elem};

pub struct Chars {
    pub v: Vec<char>,
    pub i: usize,
}

impl Chars {
    pub fn new(s: &str) -> Chars {
        Chars { v: s.chars().collect(), i: 0 }
    }
    pub fn peek(&self) -> Option<char> {
        self.v.get(self.i).copied()
    }
    pub fn peek_at(&self, n: usize) -> Option<char> {
        self.v.get(self.i + n).copied()
    }
    pub fn bump(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.i += 1;
        }
        c
    }
    pub fn at_end(&self) -> bool {
        self.i >= self.v.len()
    }
    pub fn rest(&self) -> String {
        self.v[self.i.min(self.v.len())..].iter().collect()
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct MarkupErr {
    pub msg: String,
}

/// Parses a string as Typst markup, the way the eval value conversion does.
/// Returns the resulting content, or an error.
pub fn parse_markup(src: &str, eval: &mut dyn MarkupEval) -> Result<Content, MarkupErr> {
    let mut c = Chars::new(src);
    let content = parse_markup_inner(&mut c, &[], eval)?;
    Ok(content)
}

pub trait MarkupEval {
    /// Evaluates a piece of code that appeared in markup (`#...`) and converts
    /// its value to content.
    fn eval_code(&mut self, src: &str) -> Result<Content, String>;
    /// Evaluates a reference target (`@name`).
    fn eval_ref(&mut self, target: &str) -> Result<Content, String>;
}

fn is_special(c: char) -> bool {
    matches!(
        c,
        '\\' | '"' | '\'' | '*' | '_' | '`' | '$' | '#' | '~' | '<' | '@' | '[' | ']' | ':'
    )
}

fn parse_markup_inner(
    c: &mut Chars,
    stops: &[char],
    eval: &mut dyn MarkupEval,
) -> Result<Content, MarkupErr> {
    let mut out: Vec<Elem> = vec![];
    let mut run = String::new();
    let mut push_run = |run: &mut String, out: &mut Vec<Elem>| {
        if !run.is_empty() {
            out.push(Elem::Text(std::mem::take(run)));
        }
    };
    while let Some(ch) = c.peek() {
        if stops.contains(&ch) && (ch == ']' || ch == '*' || ch == '_' || ch == '$' || ch == '`') {
            break;
        }
        match ch {
            ' ' | '\t' => {
                // whitespace run
                let mut n = 0;
                while matches!(c.peek(), Some(' ') | Some('\t')) {
                    c.bump();
                    n += 1;
                }
                let next = c.peek();
                if n == 1 && run.chars().count() > 0 && next.map(|x| x.is_alphanumeric()).unwrap_or(false) {
                    run.push(' ');
                } else {
                    push_run(&mut run, &mut out);
                    out.push(Elem::Space);
                }
            }
            '\n' => {
                c.bump();
                push_run(&mut run, &mut out);
                // A linebreak: if followed by another newline it is a parbreak.
                if c.peek() == Some('\n') {
                    c.bump();
                    out.push(Elem::Parbreak);
                } else {
                    out.push(Elem::Linebreak);
                }
            }
            '\\' => {
                c.bump();
                let e = match c.bump() {
                    Some(e) => e,
                    None => return Err(MarkupErr { msg: "unclosed delimiter".to_string() }),
                };
                push_run(&mut run, &mut out);
                match e {
                    'u' => {
                        // unicode escape
                        if c.bump() != Some('{') {
                            return Err(MarkupErr { msg: "unclosed delimiter".to_string() });
                        }
                        let mut hex = String::new();
                        while let Some(h) = c.peek() {
                            if h == '}' {
                                break;
                            }
                            hex.push(h);
                            c.bump();
                        }
                        c.bump();
                        let cp = u32::from_str_radix(&hex, 16).unwrap_or(0);
                        match char::from_u32(cp) {
                            Some(ch) => out.push(Elem::Text(ch.to_string())),
                            None => return Err(MarkupErr { msg: "invalid unicode escape".to_string() }),
                        }
                    }
                    'n' => out.push(Elem::Linebreak),
                    '\\' | '"' | '*' | '_' | '`' | '$' | '#' | '~' | '<' | '@' | '[' | ']' | ':' => {
                        out.push(Elem::Symbol(e.to_string()))
                    }
                    ' ' => out.push(Elem::Text(" ".to_string())),
                    other => out.push(Elem::Symbol(other.to_string())),
                }
            }
            '"' | '\'' => {
                c.bump();
                push_run(&mut run, &mut out);
                out.push(Elem::Smartquote { double: ch == '"' });
            }
            '*' | '_' => {
                c.bump();
                push_run(&mut run, &mut out);
                let body = parse_markup_inner(c, &[ch], eval)?;
                if c.bump() != Some(ch) {
                    return Err(MarkupErr { msg: "unclosed delimiter".to_string() });
                }
                let inner = Content { elems: body.elems };
                if ch == '*' {
                    out.push(Elem::Strong { body: Box::new(inner) });
                } else {
                    out.push(Elem::Emph { body: Box::new(inner) });
                }
            }
            '`' => {
                c.bump();
                push_run(&mut run, &mut out);
                let mut backticks = 1;
                while c.peek() == Some('`') {
                    c.bump();
                    backticks += 1;
                }
                let mut text = String::new();
                loop {
                    if c.at_end() {
                        return Err(MarkupErr { msg: "unclosed delimiter".to_string() });
                    }
                    let ch2 = c.bump().unwrap();
                    if ch2 == '`' {
                        let mut n = 1;
                        while c.peek() == Some('`') && n < backticks {
                            c.bump();
                            n += 1;
                        }
                        if n == backticks {
                            break;
                        }
                        text.push_str(&"`".repeat(n));
                    } else {
                        text.push(ch2);
                    }
                }
                let trimmed = text.trim_matches('\n');
                let block = backticks >= 3 || text.contains('\n');
                out.push(Elem::Raw {
                    text: trimmed.to_string(),
                    block,
                    lang: None,
                });
            }
            '$' => {
                c.bump();
                push_run(&mut run, &mut out);
                let body = parse_math(c, eval)?;
                if c.bump() != Some('$') {
                    return Err(MarkupErr { msg: "unclosed delimiter".to_string() });
                }
                out.push(Elem::Math { body: Box::new(Content { elems: body }) });
            }
            '#' => {
                c.bump();
                push_run(&mut run, &mut out);
                // code expression
                let src = read_code(c);
                if src.trim().is_empty() {
                    return Err(MarkupErr { msg: "unclosed delimiter".to_string() });
                }
                match eval.eval_code(&src) {
                    Ok(content) => out.extend(content.elems),
                    Err(m) => return Err(MarkupErr { msg: m }),
                }
            }
            '~' => {
                c.bump();
                push_run(&mut run, &mut out);
                out.push(Elem::Symbol("\u{a0}".to_string()));
            }
            '<' => {
                c.bump();
                push_run(&mut run, &mut out);
                let mut name = String::new();
                loop {
                    match c.bump() {
                        Some('>') => break,
                        Some(ch2) => name.push(ch2),
                        None => return Err(MarkupErr { msg: "unclosed label".to_string() }),
                    }
                }
                out.push(Elem::Label(name));
            }
            '@' => {
                c.bump();
                push_run(&mut run, &mut out);
                let mut name = String::new();
                while let Some(ch2) = c.peek() {
                    if ch2.is_alphanumeric() || ch2 == '-' || ch2 == '_' || ch2 == '.' || ch2 == ':' {
                        name.push(ch2);
                        c.bump();
                    } else {
                        break;
                    }
                }
                if name.is_empty() {
                    run.push('@');
                } else {
                    match eval.eval_ref(&name) {
                        Ok(content) => out.extend(content.elems),
                        Err(m) => return Err(MarkupErr { msg: m }),
                    }
                }
            }
            '[' => {
                c.bump();
                push_run(&mut run, &mut out);
                let inner = parse_markup_inner(c, &[']'], eval)?;
                if c.bump() != Some(']') {
                    return Err(MarkupErr { msg: "unclosed delimiter".to_string() });
                }
                out.push(Elem::Text("[".to_string()));
                out.extend(inner.elems);
                out.push(Elem::Text("]".to_string()));
            }
            ']' => {
                if stops.contains(&']') {
                    break;
                }
                c.bump();
                push_run(&mut run, &mut out);
                return Err(MarkupErr { msg: "unexpected closing bracket".to_string() });
            }
            ':' => {
                c.bump();
                push_run(&mut run, &mut out);
                out.push(Elem::Text(":".to_string()));
            }
            '-' => {
                // symbol sequences
                if c.peek_at(1) == Some('-') {
                    c.bump();
                    c.bump();
                    if c.peek() == Some('-') {
                        c.bump();
                        push_run(&mut run, &mut out);
                        out.push(Elem::Symbol("\u{2014}".to_string()));
                    } else {
                        push_run(&mut run, &mut out);
                        out.push(Elem::Symbol("\u{2013}".to_string()));
                    }
                } else if c.peek_at(1).map(|x| x.is_ascii_digit()).unwrap_or(false)
                    && (run.is_empty()
                        || run.chars().last().map(|x| !x.is_alphanumeric()).unwrap_or(true))
                {
                    c.bump();
                    push_run(&mut run, &mut out);
                    out.push(Elem::Symbol("\u{2212}".to_string()));
                } else if run.is_empty() && c.peek_at(1) == Some(' ') && stops.is_empty() {
                    // list item
                    c.bump();
                    c.bump();
                    push_run(&mut run, &mut out);
                    let body = parse_markup_inner(c, stops, eval)?;
                    out.push(Elem::Item { body: Box::new(Content { elems: body.elems }) });
                    break;
                } else {
                    run.push(ch);
                    c.bump();
                }
            }
            _ => {
                run.push(ch);
                c.bump();
            }
        }
    }
    push_run(&mut run, &mut out);
    Ok(Content { elems: out })
}

fn parse_math(c: &mut Chars, _eval: &mut dyn MarkupEval) -> Result<Vec<Elem>, MarkupErr> {
    let mut out = vec![];
    let mut run = String::new();
    while let Some(ch) = c.peek() {
        if ch == '$' {
            break;
        }
        c.bump();
        if ch.is_alphanumeric() {
            run.push(ch);
        } else {
            if !run.is_empty() {
                out.push(Elem::Text(std::mem::take(&mut run)));
            }
            match ch {
                ' ' => out.push(Elem::Space),
                '\\' => {
                    let e = match c.bump() {
                        Some(e) => e,
                        None => return Err(MarkupErr { msg: "unclosed delimiter".to_string() }),
                    };
                    out.push(Elem::Symbol(e.to_string()));
                }
                _ => out.push(Elem::Symbol(ch.to_string())),
            }
        }
    }
    if !run.is_empty() {
        out.push(Elem::Text(run));
    }
    Ok(out)
}

/// Reads a code expression following `#` in markup.
fn read_code(c: &mut Chars) -> String {
    let mut out = String::new();
    // Handle identifier / call / block / etc.
    match c.peek() {
        Some('[') => {
            // markup block
            let mut depth = 0;
            while let Some(ch) = c.bump() {
                out.push(ch);
                match ch {
                    '[' => depth += 1,
                    ']' => {
                        depth -= 1;
                        if depth == 0 {
                            break;
                        }
                    }
                    _ => {}
                }
            }
        }
        Some('(') => {
            let mut depth = 0;
            while let Some(ch) = c.bump() {
                out.push(ch);
                match ch {
                    '(' => depth += 1,
                    ')' => {
                        depth -= 1;
                        if depth == 0 {
                            break;
                        }
                    }
                    _ => {}
                }
            }
        }
        Some('{') => {
            let mut depth = 0;
            while let Some(ch) = c.bump() {
                out.push(ch);
                match ch {
                    '{' => depth += 1,
                    '}' => {
                        depth -= 1;
                        if depth == 0 {
                            break;
                        }
                    }
                    _ => {}
                }
            }
        }
        _ => {
            while let Some(ch) = c.peek() {
                if ch.is_alphanumeric() || ch == '_' || ch == '-' || ch == '.' || ch == '@' {
                    out.push(ch);
                    c.bump();
                } else {
                    break;
                }
            }
        }
    }
    out
}
