//! Typst code parsing.

#[derive(Debug, Clone, PartialEq)]
pub enum Tok {
    Ident(String),
    Number(String),
    Str { parts: Vec<SPart>, raw: bool },
    Label(String),
    Sym(String),
    Punct(String),
    Eof,
}

#[derive(Debug, Clone, PartialEq)]
pub enum SPart {
    Text(String),
    Expr(String),
}

pub struct Lexer {
    pub c: crate::syntax::Chars,
}

impl Lexer {
    pub fn new(s: &str) -> Lexer {
        Lexer { c: crate::syntax::Chars::new(s) }
    }
}

pub fn lex(s: &str) -> Vec<Tok> {
    let mut l = Lexer::new(s);
    let mut out = vec![];
    loop {
        l.skip_ws();
        let t = l.next_tok();
        let eof = matches!(t, Tok::Eof);
        out.push(t);
        if eof {
            break;
        }
    }
    out
}

impl Lexer {
    fn skip_ws(&mut self) {
        while matches!(self.c.peek(), Some(' ') | Some('\t') | Some('\n') | Some('\r')) {
            self.c.bump();
        }
        // comments
        if self.c.peek() == Some('/') && self.c.peek_at(1) == Some('/') {
            while let Some(ch) = self.c.bump() {
                if ch == '\n' {
                    break;
                }
            }
            self.skip_ws();
        }
    }

    fn next_tok(&mut self) -> Tok {
        let ch = match self.c.peek() {
            Some(c) => c,
            None => return Tok::Eof,
        };
        if ch.is_alphabetic() || ch == '_' || ch == '\u{03b1}' {
            let mut s = String::new();
            while let Some(c) = self.c.peek() {
                if c.is_alphanumeric() || c == '_' || c == '-' {
                    // hyphens are part of identifiers only if followed by alnum
                    if c == '-' {
                        match self.c.peek_at(1) {
                            Some(n) if n.is_alphanumeric() || n == '_' => {}
                            _ => break,
                        }
                    }
                    s.push(c);
                    self.c.bump();
                } else {
                    break;
                }
            }
            return Tok::Ident(s);
        }
        if ch.is_ascii_digit() {
            let mut s = String::new();
            while let Some(c) = self.c.peek() {
                if c.is_ascii_digit() {
                    s.push(c);
                    self.c.bump();
                } else {
                    break;
                }
            }
            if self.c.peek() == Some('.') && self.c.peek_at(1).map(|c| c.is_ascii_digit()).unwrap_or(false) {
                s.push('.');
                self.c.bump();
                while let Some(c) = self.c.peek() {
                    if c.is_ascii_digit() {
                        s.push(c);
                        self.c.bump();
                    } else {
                        break;
                    }
                }
            }
            // exponent
            if matches!(self.c.peek(), Some('e') | Some('E')) {
                let save = self.c.i;
                let mut exp = String::from("e");
                self.c.bump();
                if matches!(self.c.peek(), Some('+') | Some('-')) {
                    exp.push(self.c.peek().unwrap());
                    self.c.bump();
                }
                if self.c.peek().map(|c| c.is_ascii_digit()).unwrap_or(false) {
                    while let Some(c) = self.c.peek() {
                        if c.is_ascii_digit() {
                            exp.push(c);
                            self.c.bump();
                        } else {
                            break;
                        }
                    }
                    s.push_str(&exp);
                } else {
                    self.c.i = save;
                }
            }
            return Tok::Number(s);
        }
        if ch == '.' && self.c.peek_at(1).map(|c| c.is_ascii_digit()).unwrap_or(false) {
            let mut s = String::from(".");
            self.c.bump();
            while let Some(c) = self.c.peek() {
                if c.is_ascii_digit() {
                    s.push(c);
                    self.c.bump();
                } else {
                    break;
            }
            }
            return Tok::Number(s);
        }
        if ch == '"' {
            return self.lex_string(false);
        }
        if ch == '\'' {
            return self.lex_string(true);
        }
        // symbols
        let two = format!("{}{}", ch, self.c.peek_at(1).unwrap_or(' '));
        for sym in ["=>", "==", "!=", "<=", ">=", "..", "..="] {
            if two.starts_with(sym) {
                self.c.bump();
                self.c.bump();
                return Tok::Sym(sym.to_string());
            }
        }
        self.c.bump();
        if "()[]{}<>".contains(ch) || ".,;:".contains(ch) {
            return Tok::Punct(ch.to_string());
        }
        Tok::Sym(ch.to_string())
    }

    fn lex_string(&mut self, single: bool) -> Tok {
        let quote = if single { '\'' } else { '"' };
        self.c.bump();
        let mut parts = vec![];
        let mut cur = String::new();
        loop {
            match self.c.bump() {
                None => break,
                Some('\\') => {
                    let e = match self.c.bump() {
                        Some(e) => e,
                        None => break,
                    };
                    match e {
                        'n' => cur.push('\n'),
                        'r' => cur.push('\r'),
                        't' => cur.push('\t'),
                        'u' => {
                            if self.c.bump() == Some('{') {
                                let mut hex = String::new();
                                while let Some(h) = self.c.peek() {
                                    if h == '}' {
                                        break;
                                    }
                                    hex.push(h);
                                    self.c.bump();
                                }
                                self.c.bump();
