                    let mut code = String::new();
                    while let Some(ch) = self.c.bump() {
                        code.push(ch);
                        match ch {
                            '(' => depth += 1,
                            ')' => {
                                depth -= 1;
                                if depth == 0 {
                                    break;
                                }
                            }
                            _ => {}
                        }
                    }
                    parts.push(SPart::Expr(code));
                }
                Some(c) if c == quote => break,
                Some(c) => cur.push(c),
            }
        }
        if parts.is_empty() {
            Tok::Str { parts: vec![SPart::Text(cur)], raw: single }
        } else {
            if !cur.is_empty() {
                parts.push(SPart::Text(cur));
            }
            Tok::Str { parts, raw: single }
        }
    }
}
