}

#[derive(Debug, Clone, PartialEq)]
pub enum UnOp {
    Neg,
    Pos,
    Not,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Param {
    Pos(String),
    Named(String, Box<Expr>),
    Sink(String),
    Rest(String),
}

