    Block(Vec<Spanned>, bool),
    Let { name: String, value: Box<Expr>, body: Option<Box<Expr>> },
    If { cond: Box<Expr>, then: Box<Expr>, els: Option<Box<Expr>> },
    For { pat: Vec<String>, iter: Box<Expr>, body: Box<Expr> },
    While { cond: Box<Expr>, body: Box<Expr> },
    Context(Box<Expr>),
    Spread(Box<Expr>),
    Markup(String),
    Raw { text: String, block: bool, lang: Option<String> },
    Math(String),
    Set { name: String, args: Vec<ArgExpr>, body: Option<Box<Expr>> },
    Show { transform: Option<Box<Expr>>, body: Box<Expr> },
    Break,
    Continue,
    Error(String),
}

#[derive(Debug, Clone, PartialEq)]
pub struct Spanned {
    pub expr: Box<Expr>,
    pub source: String,
}

pub struct Parser {
    pub toks: Vec<Tok>,
    pub i: usize,
    pub src: Vec<char>,
    pub start: usize,
}

impl Parser {
    pub fn new(src: &str) -> Parser {
        let toks = lex(src);
        let chars: Vec<char> = src.chars().collect();
        Parser { toks, i: 0, src: chars, start: 0 }
    }

    pub fn peek(&self) -> &Tok {
        self.toks.get(self.i).unwrap_or(&Tok::Eof)
    }
    pub fn peek2(&self) -> &Tok {
        self.toks.get(self.i + 1).unwrap_or(&Tok::Eof)
    }
    pub fn bump(&mut self) -> Tok {
        let t = self.peek().clone();
        if !matches!(t, Tok::Eof) {
            self.i += 1;
        }
        t
    }
    pub fn at_punct(&self, p: &str) -> bool {
        matches!(self.peek(), Tok::Punct(x) if x == p)
    }
    pub fn eat_punct(&mut self, p: &str) -> bool {
        if self.at_punct(p) {
            self.bump();
            true
        } else {
            false
        }
    }
    pub fn at_sym(&self, s: &str) -> bool {
        matches!(self.peek(), Tok::Sym(x) if x == s)
    }

    /// Parses a whole code block body (a sequence of expressions).
    pub fn parse_block_items(&mut self) -> Result<Vec<Spanned>, String> {
        let mut items = vec![];
        while !matches!(self.peek(), Tok::Eof | Tok::Punct(_)) {
            let e = self.parse_expr(true)?;
            items.push(e);
        }
        Ok(items)
    }

    pub fn parse_expr(&mut self, allow_set: bool) -> Result<Spanned, String> {
        let start_tok = self.i;
        let e = self.parse_or(allow_set)?;
        let source = self.source_of(start_tok, self.i);
        Ok(Spanned { expr: Box::new(e), source })
    }

    pub fn source_of(&self, from: usize, to: usize) -> String {
        // Reconstruct source text between token boundaries approximately: we
        // don't track exact spans, so use the token text.
        let mut s = String::new();
        for t in &self.toks[from..to.min(self.toks.len())] {
            let txt = match t {
                Tok::Ident(s) => s.clone(),
                Tok::Number(s) => s.clone(),
                Tok::Str { parts, raw } => {
                    let q = if *raw { '\'' } else { '"' };
                    let mut out = String::new();
                    out.push(q);
                    for p in parts {
                        match p {
                            SPart::Text(t) => out.push_str(t),
                            SPart::Expr(e) => out.push_str(&format!("#({})", e)),
                        }
                    }
                    out.push(q);
                    out
                }
                Tok::Label(s) => format!("<{}>", s),
                Tok::Sym(s) => s.clone(),
                Tok::Punct(s) => s.clone(),
                Tok::Eof => String::new(),
            };
            if !s.is_empty() && !txt.is_empty() {
                s.push(' ');
            }
            s.push_str(&txt);
        }
        s
    }

    fn parse_or(&mut self, allow_set: bool) -> Result<Expr, String> {
        let mut left = self.parse_and(allow_set)?;
        loop {
            if self.at_sym("or") {
                self.bump();
                let right = self.parse_and(allow_set)?;
                left = Expr::Binary(BinOp::Or, Box::new(left), Box::new(right));
            } else {
                break;
            }
        }
        Ok(left)
    }

    fn parse_and(&mut self, allow_set: bool) -> Result<Expr, String> {
        let mut left = self.parse_cmp(allow_set)?;
        loop {
            if self.at_sym("and") {
                self.bump();
                let right = self.parse_cmp(allow_set)?;
                left = Expr::Binary(BinOp::And, Box::new(left), Box::new(right));
            } else {
                break;
            }
        }
        Ok(left)
    }

    fn parse_cmp(&mut self, allow_set: bool) -> Result<Expr, String> {
        let mut left = self.parse_add(allow_set)?;
        loop {
            let op = match self.peek() {
                Tok::Sym(s) if matches!(s.as_str(), "==" | "!=" | "<" | "<=" | ">" | ">=") => {
                    match s.as_str() {
                        "==" => BinOp::Eq,
                        "!=" => BinOp::Ne,
                        "<" => BinOp::Lt,
                        "<=" => BinOp::Le,
                        ">" => BinOp::Gt,
                        _ => BinOp::Ge,
                    }
                }
                Tok::Ident(s) if s == "in" => BinOp::In,
                Tok::Sym(s) if s == "not" => {
                    if matches!(self.peek2(), Tok::Ident(s2) if s2 == "in") {
                        BinOp::NotIn
                    } else {
                        break;
                    }
                }
                _ => break,
            };
            self.bump();
            if matches!(op, BinOp::NotIn) {
                self.bump();
            }
            let right = self.parse_add(allow_set)?;
            left = Expr::Binary(op, Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_add(&mut self, allow_set: bool) -> Result<Expr, String> {
        let mut left = self.parse_mul(allow_set)?;
        loop {
            let op = match self.peek() {
                Tok::Sym(s) if s == "+" => BinOp::Add,
                Tok::Sym(s) if s == "-" => BinOp::Sub,
                Tok::Sym(s) if s == "+=" => BinOp::AddAssign,
                Tok::Sym(s) if s == "-=" => BinOp::SubAssign,
                _ => break,
            };
            self.bump();
            let right = self.parse_mul(allow_set)?;
            left = Expr::Binary(op, Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_mul(&mut self, allow_set: bool) -> Result<Expr, String> {
        let mut left = self.parse_unary(allow_set)?;
        loop {
            let op = match self.peek() {
                Tok::Sym(s) if s == "*" => BinOp::Mul,
                Tok::Sym(s) if s == "/" => BinOp::Div,
                Tok::Sym(s) if s == "*=" => BinOp::MulAssign,
                Tok::Sym(s) if s == "/=" => BinOp::DivAssign,
                _ => break,
            };
            self.bump();
            let right = self.parse_unary(allow_set)?;
            left = Expr::Binary(op, Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_unary(&mut self, allow_set: bool) -> Result<Expr, String> {
        match self.peek() {
            Tok::Sym(s) if s == "-" => {
                self.bump();
                let e = self.parse_unary(allow_set)?;
                Ok(Expr::Unary(UnOp::Neg, Box::new(e)))
            }
            Tok::Sym(s) if s == "+" => {
                self.bump();
                let e = self.parse_unary(allow_set)?;
                Ok(Expr::Unary(UnOp::Pos, Box::new(e)))
            }
            Tok::Sym(s) if s == "!" => {
                self.bump();
                let e = self.parse_unary(allow_set)?;
                Ok(Expr::Unary(UnOp::Not, Box::new(e)))
            }
            Tok::Sym(s) if s == ".." => {
                self.bump();
                let e = self.parse_unary(allow_set)?;
                Ok(Expr::Spread(Box::new(e)))
            }
            _ => self.parse_postfix(allow_set),
        }
    }

    fn parse_postfix(&mut self, allow_set: bool) -> Result<Expr, String> {
        let mut e = self.parse_primary(allow_set)?;
        loop {
            match self.peek() {
                Tok::Punct(p) if p == "." => {
                    self.bump();
                    let name = match self.bump() {
                        Tok::Ident(n) => n,
                        Tok::Number(n) => n,
                        _ => return Err("expected identifier".to_string()),
                    };
                    e = Expr::Field(Box::new(e), name);
                }
                Tok::Punct(p) if p == "(" => {
                    let args = self.parse_args()?;
                    e = Expr::Call(Box::new(e), args);
                }
                Tok::Punct(p) if p == "[" => {
                    // markup literal in code
                    let src = self.read_balanced('[');
                    e = Expr::Markup(src);
                }
                Tok::Sym(s) if s == "=>" => {
                    // closure with a single parameter
                    let name = match &e {
                        Expr::Ident(n) => n.clone(),
                        _ => return Err("expected expression".to_string()),
                    };
                    self.bump();
                    let body = self.parse_expr(false)?;
                    let repr = format!("({}) => ..", name);
                    e = Expr::Closure {
                        params: vec![Param::Pos(name)],
                        body: body.expr,
                        repr,
                    };
                }
                _ => break,
            }
        }
        Ok(e)
    }

    fn read_balanced(&mut self, open: char) -> String {
        let close = if open == '[' { ']' } else { open };
        let mut depth = 0;
        let mut out = String::new();
        while let Some(ch) = self.src.get(self.start).copied() {
            if ch == open {
                depth += 1;
            } else if ch == close {
                depth -= 1;
            }
            self.start += 1;
            out.push(ch);
            if depth == 0 && ch == close {
                break;
            }
            if out.len() > 100000 {
                break;
            }
        }
        out
    }

    fn parse_args(&mut self) -> Result<Vec<ArgExpr>, String> {
        self.eat_punct("(");
        let mut args = vec![];
        loop {
            if self.eat_punct(")") {
                break;
            }
            if matches!(self.peek(), Tok::Eof) {
                return Err("unclosed delimiter".to_string());
            }
            // named argument
            if let Tok::Ident(n) = self.peek().clone() {
                if matches!(self.peek2(), Tok::Punct(p) if p == ":") {
                    self.bump();
                    self.bump();
                    let v = self.parse_expr(false)?;
                    args.push(ArgExpr { name: Some(n), value: v.expr });
                    self.eat_punct(",");
                    continue;
                }
            }
            if self.at_sym("..") {
                self.bump();
                let v = self.parse_expr(false)?;
                args.push(ArgExpr { name: Some("..".to_string()), value: v.expr });
                self.eat_punct(",");
                continue;
            }
            let v = self.parse_expr(false)?;
            args.push(ArgExpr { name: None, value: v.expr });
            if !self.eat_punct(",") {
                if self.eat_punct(")") {
                    break;
                } else if matches!(self.peek(), Tok::Eof) {
                    return Err("unclosed delimiter".to_string());
                } else {
                    return Err("expected comma or closing paren".to_string());
                }
            }
        }
        Ok(args)
    }

    fn parse_primary(&mut self, allow_set: bool) -> Result<Expr, String> {
        match self.peek().clone() {
            Tok::Number(n) => {
                self.bump();
                self.parse_number(&n)
            }
            Tok::Str { parts, raw } => {
                self.bump();
                let _ = raw;
                Ok(Expr::Str { parts })
            }
            Tok::Label(l) => {
                self.bump();
                Ok(Expr::Label(l))
            }
            Tok::Ident(id) => {
                self.bump();
                match id.as_str() {
                    "true" => Ok(Expr::Bool(true)),
                    "false" => Ok(Expr::Bool(false)),
                    "none" => Ok(Expr::None),
                    "auto" => Ok(Expr::Ident("auto".to_string())),
                    "if" => self.parse_if(),
                    "for" => self.parse_for(),
                    "while" => self.parse_while(),
                    "let" => self.parse_let(),
                    "context" => {
                        let e = self.parse_expr(false)?;
                        Ok(Expr::Context(e.expr))
                    }
                    "break" => Ok(Expr::Break),
                    "continue" => Ok(Expr::Continue),
                    "set" if allow_set => {
                        let name = match self.bump() {
                            Tok::Ident(n) => n,
                            _ => return Err("expected identifier".to_string()),
                        };
                        let args = if self.at_punct("(") { self.parse_args()? } else { vec![] };
                        let body = if self.at_punct("[") {
                            let src = self.read_balanced('[');
                            Some(Box::new(Expr::Markup(src)))
                        } else if self.at_punct(";") {
                            self.bump();
                            let e = self.parse_expr(true)?;
                            Some(e.expr)
                        } else {
                            None
                        };
                        Ok(Expr::Set { name, args, body })
                    }
                    "show" if allow_set => {
                        let transform = if self.at_punct(":") {
                            self.bump();
                            let e = self.parse_expr(false)?;
                            Some(e.expr)
                        } else {
                            None
                        };
                        let body = self.parse_expr(false)?;
                        Ok(Expr::Show { transform, body: body.expr })
                    }
                    "return" => Ok(Expr::Error("return".to_string())),
                    _ => {
                        if self.at_sym("=>") {
                            self.bump();
                            let body = self.parse_expr(false)?;
                            Ok(Expr::Closure {
                                params: vec![Param::Pos(id)],
                                body: body.expr,
                                repr: format!("({}) => ..", id),
                            })
                        } else {
                            Ok(Expr::Ident(id))
                        }
                    }
                }
            }
            Tok::Sym(s) if s == ".." => {
                self.bump();
                let e = self.parse_expr(false)?;
                Ok(Expr::Spread(e.expr))
            }
            Tok::Sym(s) if s == "-" || s == "+" || s == "!" => {
                let op = if s == "-" {
                    UnOp::Neg
                } else if s == "+" {
                    UnOp::Pos
                } else {
                    UnOp::Not
                };
                self.bump();
                let e = self.parse_unary(true)?;
                Ok(Expr::Unary(op, Box::new(e)))
            }
            Tok::Punct(p) if p == "(" => {
                self.bump();
                // dict, tuple, closure, or parenthesized expression
                if self.eat_punct(")") {
                    return Ok(Expr::Array { items: vec![], is_tuple: true, source: "()".to_string() });
                }
                // closure parameters?
                if let Tok::Ident(_) = self.peek() {
                    if matches!(self.peek2(), Tok::Punct(p) if p == ")") && matches!(self.toks.get(self.i + 2), Some(Tok::Sym(s)) if s == "=>") {
                        let name = match self.bump() {
                            Tok::Ident(n) => n,
                            _ => unreachable!(),
                        };
                        self.bump();
                        self.bump();
                        let body = self.parse_expr(false)?;
                        return Ok(Expr::Closure {
                            params: vec![Param::Pos(name)],
                            body: body.expr,
                            repr: "({}) => ..".to_string(),
                        });
                    }
                }
                let first = self.parse_expr(false)?;
                if self.at_punct(":") {
                    // dict
                    self.bump();
                    let v = self.parse_expr(false)?;
                    let mut items = vec![];
                    match &*first.expr {
                        Expr::Ident(k) => items.push((k.clone(), v)),
                        Expr::Str { parts } => {
                            if let Some(SPart::Text(t)) = parts.first() {
                                items.push((t.clone(), v));
                            }
                        }
                        _ => return Err("expected string, found expression".to_string()),
                    }
                    while self.eat_punct(",") {
                        if self.eat_punct(")") {
                            break;
                        }
                        let k = match self.bump() {
                            Tok::Ident(k) => k,
                            Tok::Str { parts, .. } => match parts.first() {
                                Some(SPart::Text(t)) => t.clone(),
                                _ => return Err("expected string".to_string()),
                            },
                            _ => return Err("expected identifier".to_string()),
                        };
                        if !self.eat_punct(":") {
                            return Err("expected colon".to_string());
                        }
                        let v = self.parse_expr(false)?;
                        items.push((k, v));
                    }
                    if !self.eat_punct(")") {
                        return Err("unclosed delimiter".to_string());
                    }
                    return Ok(Expr::Dict { items, source: "(..)".to_string() });
                }
                if self.at_punct(",") || self.eat_punct(")") {
                    // tuple
                    let mut items = vec![first];
                    let mut is_tuple = true;
                    if self.at_punct(",") {
                        while self.eat_punct(",") {
                            if self.at_punct(")") {
                                break;
                            }
                            let e = self.parse_expr(false)?;
                            items.push(e);
                        }
                    } else {
                        is_tuple = false;
                    }
                    if !self.eat_punct(")") {
                        return Err("unclosed delimiter".to_string());
                    }
                    return Ok(Expr::Array { items, is_tuple, source: "(..)".to_string() });
                }
                if self.at_sym("=>") {
                    self.bump();
                    let body = self.parse_expr(false)?;
                    return Ok(Expr::Closure {
                        params: vec![],
                        body: body.expr,
                        repr: "(..) => ..".to_string(),
                    });
                }
                if !self.eat_punct(")") {
                    return Err("unclosed delimiter".to_string());
                }
                Ok(Expr::Paren(first.expr, "(..)".to_string()))
            }
            Tok::Punct(p) if p == "{" => {
                self.bump();
                let items = self.parse_block_items()?;
                if !self.eat_punct("}") {
                    return Err("unclosed delimiter".to_string());
                }
                Ok(Expr::Block(items, true))
            }
            Tok::Punct(p) if p == "[" => {
                let src = self.read_balanced('[');
                Ok(Expr::Markup(src))
            }
            Tok::Punct(p) if p == "$" => {
                let src = self.read_balanced('$');
                Ok(Expr::Math(src))
            }
            Tok::Sym(s) if s == "`" => {
                // raw
                let mut backticks = 0;
                while self.src.get(self.start).copied() == Some('`') {
                    self.start += 1;
                    backticks += 1;
                }
                self.i += 1;
                let mut text = String::new();
                loop {
                    let ch = match self.src.get(self.start).copied() {
                        Some(c) => c,
                        None => return Err("unclosed delimiter".to_string()),
                    };
                    self.start += 1;
                    if ch == '`' {
                        let mut n = 1;
                        while self.src.get(self.start).copied() == Some('`') && n < backticks {
                            self.start += 1;
                            n += 1;
                        }
                        if n == backticks {
                            break;
                        }
                        text.push_str(&"`".repeat(n));
                    } else {
                        text.push(ch);
                    }
                }
                let trimmed = text.trim_matches('\n');
                let block = backticks >= 3 || text.contains('\n');
                Ok(Expr::Raw { text: trimmed.to_string(), block, lang: None })
            }
            Tok::Punct(p) if p == "," => Err("unexpected comma".to_string()),
            Tok::Punct(p) if p == ")" => Err("unexpected closing paren".to_string()),
            Tok::Punct(p) if p == "." => Err("unexpected dot".to_string()),
            Tok::Punct(p) if p == ":" => Err("unexpected colon".to_string()),
            Tok::Sym(s) if s == "#" => {
                Err("the character `#` is not valid in code".to_string())
            }
            Tok::Sym(s) if s == "?" => {
                Err("the character `?` is not valid in code".to_string())
            }
            Tok::Sym(s) if s == ";" => Err("unexpected semicolon".to_string()),
            Tok::Eof => Err("expected expression".to_string()),
            Tok::Sym(s) => Err(format!("unexpected {}", s)),
        }
    }

    fn parse_number(&mut self, n: &str) -> Result<Expr, String> {
        // Check for a trailing unit
        let mut num = n.to_string();
        let mut unit = String::new();
        while let Some(c) = self.src.get(self.start).copied() {
            if c.is_alphabetic() || c == '%' || c == '°' {
                unit.push(c);
                self.start += 1;
            } else {
                break;
            }
        }
        let _ = &mut num;
        if unit.is_empty() {
            if n.contains('.') || n.contains('e') || n.contains('E') {
                match n.parse::<f64>() {
                    Ok(f) => Ok(Expr::Float(f)),
                    Err(_) => Err("invalid number".to_string()),
                }
            } else {
                match n.parse::<i64>() {
                    Ok(i) => Ok(Expr::Int(i)),
                    Err(_) => match n.parse::<f64>() {
                        Ok(f) => Ok(Expr::Float(f)),
                        Err(_) => Err("invalid number".to_string()),
                    },
                }
            }
        } else {
            match n.parse::<f64>() {
                Ok(_) => {
                    let src = format!("{}{}", n, unit);
                    Ok(Expr::Call(
                        Box::new(Expr::Ident("__unit".to_string())),
                        vec![
                            ArgExpr { name: None, value: Box::new(Expr::Float(n.parse::<f64>().unwrap())) },
                            ArgExpr { name: None, value: Box::new(Expr::Str { parts: vec![SPart::Text(unit)] }) },
                            ArgExpr { name: None, value: Box::new(Expr::Str { parts: vec![SPart::Text(src)] }) },
                        ],
                    ))
                }
                Err(_) => Err("invalid number".to_string()),
            }
        }
    }

    fn parse_if(&mut self) -> Result<Expr, String> {
        let cond = self.parse_expr(false)?;
        if !self.at_punct("{") {
            return Err("expected block".to_string());
        }
        let then = self.parse_primary(true)?;
        let mut els = None;
        if let Tok::Ident(s) = self.peek().clone() {
            if s == "else" {
                self.bump();
                if matches!(self.peek(), Tok::Ident(s2) if s2 == "if") {
                    self.bump();
                    let e = self.parse_if()?;
                    els = Some(Box::new(e));
                } else {
                    let e = self.parse_primary(true)?;
                    els = Some(Box::new(e));
                }
            }
        }
        Ok(Expr::If { cond: cond.expr, then: Box::new(then), els })
    }

    fn parse_for(&mut self) -> Result<Expr, String> {
        let mut pat = vec![];
        match self.bump() {
            Tok::Ident(n) => pat.push(n),
            Tok::Punct(p) if p == "(" => {
                loop {
                    match self.bump() {
                        Tok::Ident(n) => pat.push(n),
                        Tok::Punct(p) if p == "," => continue,
                        Tok::Punct(p) if p == ")" => break,
                        _ => return Err("expected identifier".to_string()),
                    }
                }
            }
            _ => return Err("expected identifier".to_string()),
        }
        match self.bump() {
            Tok::Ident(s) if s == "in" => {}
            _ => return Err("expected `in`".to_string()),
        }
        let iter = self.parse_expr(false)?;
        let body = self.parse_primary(true)?;
        Ok(Expr::For { pat, iter: iter.expr, body: Box::new(body) })
    }

    fn parse_while(&mut self) -> Result<Expr, String> {
        let cond = self.parse_expr(false)?;
        let body = self.parse_primary(true)?;
        Ok(Expr::While { cond: cond.expr, body: Box::new(body) })
    }

    fn parse_let(&mut self) -> Result<Expr, String> {
        let mut names = vec![];
        match self.bump() {
            Tok::Ident(n) => names.push(n),
            Tok::Punct(p) if p == "(" => {
                loop {
                    match self.bump() {
                        Tok::Ident(n) => names.push(n),
                        Tok::Punct(p) if p == "," => continue,
                        Tok::Punct(p) if p == ")" => break,
                        _ => return Err("expected identifier".to_string()),
                    }
                }
            }
            _ => return Err("expected identifier".to_string()),
        }
        let mut value = None;
        if self.at_sym("=") {
            self.bump();
            let v = self.parse_expr(false)?;
            value = Some(v);
        }
        let value = match value {
            Some(v) => v,
            None => return Err("expected expression".to_string()),
        };
        let mut body = None;
        if self.eat_punct(";") {
            let b = self.parse_expr(true)?;
            body = Some(b.expr);
        }
        Ok(Expr::Let { name: names.remove(0), value: value.expr, body })
    }
}
