//! Evaluation of Typst code (used by `eval`, `query` and compilation).

use crate::code::{ArgExpr, BinOp, Expr, SPart, Spanned, UnOp};
use crate::value::*;
use std::collections::HashMap;

pub struct Diag {
    pub message: String,
    pub hints: Vec<String>,
}

