#[derive(Clone, Default)]
pub struct Scope {
    vars: Vec<HashMap<String, Value>>,
}

impl Scope {
    pub fn get(&self, name: &str) -> Option<&Value> {
        for s in self.vars.iter().rev() {
            if let Some(v) = s.get(name) {
                return Some(v);
            }
        }
        None
    }
    pub fn set(&mut self, name: &str, v: Value) {
        let s = self.vars.last_mut().unwrap();
        s.insert(name.to_string(), v);
    }
    pub fn push(&mut self) {
        self.vars.push(HashMap::new());
    }
    pub fn pop(&mut self) {
        self.vars.pop();
    }
    pub fn contains(&self, name: &str) -> bool {
        self.get(name).is_some()
    }
}

pub struct Machine {
    pub scope: Scope,
    pub styles: Vec<Style>,
    pub context: bool,
    pub page_counter: i64,
    pub target_html: bool,
    pub features_html: bool,
    pub out: Vec<Value>,
}

pub fn prelude() -> Vec<(&'static str, Value)> {
    let mut v: Vec<(&'static str, Value)> = vec![];
    // colours
    let colors: Vec<(&str, &str)> = vec![
        ("red", "#ff4136"),
        ("blue", "#4b69c6"),
        ("green", "#198810"),
        ("yellow", "#9a7f18"),
        ("orange", "#d73948"),
        ("purple", "#b60157"),
        ("pink", "#ef2eb1"),
        ("brown", "#935f32"),
        ("gray", "#808080"),
        ("grey", "#808080"),
        ("silver", "#bbbbbb"),
        ("teal", "#2e7f74"),
        ("aqua", "#01c8bd"),
        ("lime", "#99d350"),
        ("fuchsia", "#e000e0"),
        ("olive", "#808000"),
        ("white", "#ffffff"),
        ("black", "#000000"),
    ];
    for (name, hex) in colors {
        v.push((
            name,
            Value::Color(Color::Rgb {
                components: hex_to_rgb(hex),
                repr: format!("rgb(\"{}\")", hex),
                alpha: 1.0,
            }),
        ));
    }
    // alignment / direction
    v.push(("auto", Value::Alignment("auto")));
    v.push(("start", Value::Alignment("start")));
    v.push(("end", Value::Alignment("end")));
    v.push(("left", Value::Alignment("left")));
    v.push(("right", Value::Alignment("right")));
    v.push(("center", Value::Alignment("center")));
    v.push(("top", Value::Alignment("top")));
    v.push(("bottom", Value::Alignment("bottom")));
    v.push(("horizon", Value::Alignment("horizon")));
    v.push(("ltr", Value::Direction("ltr")));
    v.push(("rtl", Value::Direction("rtl")));
    v.push(("ttb", Value::Direction("ttb")));
    v.push(("btt", Value::Direction("btt")));
    v
}

fn hex_to_rgb(hex: &str) -> Vec<f64> {
    let h = &hex[1..];
    let b = |i: usize| u8::from_str_radix(&h[i * 2..i * 2 + 2], 16).unwrap_or(0) as f64 / 255.0;
    vec![b(0), b(1), b(2)]
}

