    pub fn new(features_html: bool, target_html: bool) -> Machine {
        let mut scope = Scope::default();
        scope.push();
        let mut m = Machine {
            scope,
            styles: vec![],
            context: false,
            page_counter: 1,
            target_html,
            features_html,
            out: vec![],
        };
        for (k, v) in prelude() {
            m.scope.set(k, v);
        }
        m
    }

    pub fn call(&mut self, f: &Value, args: Vec<Value>, nargs: HashMap<String, Value>) -> R {
        match f {
            Value::Func(func) => match &func.kind {
                FuncKind::Native(name) => {
                    self.call_native(name, args, nargs, &func.name.clone().unwrap_or_default())
                }
                FuncKind::Closure(params, sink, rest, defaults, body) => {
                    let mut env = Scope::default();
                    env.push();
                    // fill arguments
                    let mut i = 0;
                    for p in params.iter() {
                        match p {
                            crate::code::Param::Pos(n) => {
                                let a = args.get(i).cloned().unwrap_or(Value::None);
                                i += 1;
                                env.set(n, a);
                            }
                            crate::code::Param::Named(n, d) => {
                                let v = match nargs.get(n) {
                                    Some(v) => v.clone(),
                                    None => {
                                        self.scope.set("__tmp".into(), Value::None);
                                        let _ = d;
                                        Value::None
                                    }
                                };
                                env.set(n, v);
                            }
                            crate::code::Param::Sink(n) => {
                                let a = args.get(i).cloned().unwrap_or(Value::None);
                                i += 1;
                                env.set(n, a);
                            }
                            crate::code::Param::Rest(n) => {
                                let rest_args: Vec<Value> = args[i..].to_vec();
                                i = args.len();
                                env.set(n, Value::Array(ArrayV { items: rest_args, item_sources: None, repr: Repr::Canonical }));
                            }
                        }
                    }
                    let saved = std::mem::replace(&mut self.scope, env);
                    let r = self.eval(body);
                    self.scope = saved;
                    r
                }
            },
            other => Err(Diag::new(&format!(
                "expected function, found {}",
                other.type_name()
            ))),
        }
    }
}
