// ---------------------------------------------------------------------------
// Expression evaluation
// ---------------------------------------------------------------------------

impl Machine {
    pub fn eval(&mut self, e: &Expr) -> R {
        match e {
            Expr::None => Ok(Value::None),
            Expr::Bool(b) => Ok(Value::Bool(*b)),
            Expr::Int(i) => Ok(Value::Int(*i)),
            Expr::Float(f) => Ok(Value::Float(*f)),
            Expr::Str { parts } => self.eval_str(parts),
            Expr::Label(l) => Ok(Value::Label(l.clone())),
            Expr::Ident(name) => self.eval_ident(name),
            Expr::Field(obj, name) => {
                let o = self.eval(obj)?;
                self.field(&o, name)
            }
            Expr::Array { items, is_tuple, .. } => {
                let mut vals = vec![];
                for it in items {
                    let v = self.eval(&it.expr)?;
                    if let Value::Array(a) = &v {
                        if matches!(it.expr.as_ref(), Expr::Spread(_)) {
                            vals.extend(a.items.clone());
                            continue;
                        }
                    }
                    vals.push(v);
                }
                Ok(Value::Array(ArrayV {
                    items: vals,
                    item_sources: None,
                    repr: Repr::Canonical,
                }))
            }
            Expr::Dict { items, .. } => {
                let mut d = Dict::default();
                for (k, v) in items {
                    let val = self.eval(&v.expr)?;
                    d.items.push((k.clone(), val));
                }
                Ok(Value::Dict(d))
            }
            Expr::Paren(inner, _) => self.eval(inner),
            Expr::Binary(op, a, b) => self.eval_binary(*op, a, b),
            Expr::Unary(op, a) => {
                let v = self.eval(a)?;
                match op {
                    UnOp::Neg => self.neg(v),
                    UnOp::Pos => Ok(v),
                    UnOp::Not => match v {
                        Value::Bool(b) => Ok(Value::Bool(!b)),
                        other => Err(Diag::new(&format!(
                            "expected boolean, found {}",
                            other.type_name()
                        ))),
                    },
                }
            }
            Expr::Call(f, args) => {
                let fv = self.eval(f)?;
                let (mut pos, named) = self.eval_args(args)?;
                if let Value::Array(a) = &fv {
                    // spread call is not supported
                    let _ = a;
                }
                self.call(&fv, pos, named)
            }
            Expr::Closure { params, body, repr } => Ok(Value::Func(Func {
                name: None,
                kind: FuncKind::Closure(
                    params.clone(),
                    None,
                    None,
                    vec![],
                    Box::new(crate::value::Node),
                ),
                repr: repr.clone(),
            })),
            Expr::Block(items, scoped) => {
                if *scoped {
                    self.scope.push();
                }
                let mut result = Value::None;
                for it in items {
                    result = self.eval(&it.expr)?;
                    if let Value::Content(c) = &result {
                        let _ = c;
                    }
                }
                if *scoped {
                    self.scope.pop();
                }
                Ok(result)
            }
            Expr::Let { name, value, body } => {
                let v = self.eval(value)?;
                self.scope.set(name, v);
                match body {
                    Some(b) => self.eval(b),
                    None => Ok(Value::None),
                }
            }
            Expr::If { cond, then, els } => {
                let c = self.eval(cond)?;
                match c {
                    Value::Bool(true) => self.eval(then),
                    Value::Bool(false) => match els {
                        Some(e) => self.eval(e),
                        None => Ok(Value::None),
                    },
                    other => Err(Diag::new(&format!(
                        "expected boolean, found {}",
                        other.type_name()
                    ))),
                }
            }
            Expr::For { pat, iter, body } => self.eval_for(pat, iter, body),
            Expr::While { cond, body } => {
                let mut result = Value::None;
                loop {
                    let c = self.eval(cond)?;
                    match c {
                        Value::Bool(true) => {
                            result = self.eval(body)?;
                        }
                        Value::Bool(false) => break,
                        other => {
                            return Err(Diag::new(&format!(
                                "expected boolean, found {}",
                                other.type_name()
                            )))
                        }
                    }
                }
                Ok(result)
            }
            Expr::Context(inner) => {
                let saved = self.context;
                self.context = true;
                let r = self.eval(inner);
                self.context = saved;
                r
            }
            Expr::Spread(inner) => self.eval(inner),
            Expr::Markup(src) => {
                let content = self.eval_markup(src)?;
                Ok(Value::Content(content))
            }
            Expr::Raw { text, block, lang } => Ok(Value::Content(Content {
                elems: vec![Elem::Raw {
