                kind: FuncKind::Closure(
                    params.clone(),
                    None,
                    None,
                    vec![],
                    Box::new(crate::value::Node),
                ),
                repr: repr.clone(),
            })),
            Expr::Block(items, scoped) => {
                if *scoped {
                    self.scope.push();
                }
                let mut result = Value::None;
                for it in items {
                    result = self.eval(&it.expr)?;
                    if let Value::Content(c) = &result {
                        let _ = c;
                    }
                }
                if *scoped {
                    self.scope.pop();
                }
                Ok(result)
            }
            Expr::Let { name, value, body } => {
                let v = self.eval(value)?;
                self.scope.set(name, v);
                match body {
                    Some(b) => self.eval(b),
                    None => Ok(Value::None),
                }
            }
            Expr::If { cond, then, els } => {
                let c = self.eval(cond)?;
                match c {
                    Value::Bool(true) => self.eval(then),
                    Value::Bool(false) => match els {
                        Some(e) => self.eval(e),
                        None => Ok(Value::None),
                    },
                    other => Err(Diag::new(&format!(
                        "expected boolean, found {}",
                        other.type_name()
                    ))),
                }
            }
            Expr::For { pat, iter, body } => self.eval_for(pat, iter, body),
            Expr::While { cond, body } => {
                let mut result = Value::None;
                loop {
                    let c = self.eval(cond)?;
                    match c {
                        Value::Bool(true) => {
                            result = self.eval(body)?;
                        }
                        Value::Bool(false) => break,
                        other => {
                            return Err(Diag::new(&format!(
                                "expected boolean, found {}",
                                other.type_name()
                            )))
                        }
                    }
                }
                Ok(result)
            }
            Expr::Context(inner) => {
                let saved = self.context;
                self.context = true;
                let r = self.eval(inner);
                self.context = saved;
                r
            }
            Expr::Spread(inner) => self.eval(inner),
            Expr::Markup(src) => {
                let content = self.eval_markup(src)?;
                Ok(Value::Content(content))
            }
            Expr::Raw { text, block, lang } => Ok(Value::Content(Content {
                elems: vec![Elem::Raw {
                    text: text.clone(),
                    block: *block,
                    lang: lang.clone(),
                }],
            })),
            Expr::Math(src) => {
                let body = self.eval_math(src)?;
                Ok(Value::Content(Content {
                    elems: vec![Elem::Math { body: Box::new(Content { elems: body }) }],
                }))
            }
            Expr::Set { name, args, body } => {
                let saved = self.styles.clone();
                self.apply_set(name, args)?;
                let r = match body {
                    Some(b) => self.eval(b),
                    None => Ok(Value::None),
                };
                self.styles = saved;
                r
            }
            Expr::Show { transform, body } => {
                let _ = transform;
                self.eval(body)
            }
            Expr::Break => Err(Diag::new("__break")),
            Expr::Continue => Err(Diag::new("__continue")),
            Expr::Error(m) => Err(Diag::new(m)),
        }
    }

    pub fn eval_str(&mut self, parts: &[SPart]) -> R {
        let mut s = String::new();
        for p in parts {
            match p {
                SPart::Text(t) => s.push_str(t),
                SPart::Expr(code) => {
                    let mut p = crate::code::Parser::new(code);
                    let e = match p.parse_expr(false) {
                        Ok(e) => e,
                        Err(m) => return Err(Diag::new(&m)),
                    };
                    let v = self.eval(&e.expr)?;
                    s.push_str(&self.value_to_text(&v)?);
                }
            }
        }
        Ok(Value::Str(s))
    }

    pub fn value_to_text(&mut self, v: &Value) -> Result<String, Diag> {
        match v {
            Value::Str(s) => Ok(s.clone()),
            Value::None => Ok(String::new()),
            Value::Bool(b) => Ok(b.to_string()),
            Value::Int(i) => Ok(i.to_string()),
            Value::Float(f) => Ok(crate::util::fmt_float(*f)),
            Value::Symbol(s) => Ok(s.clone()),
            Value::Label(l) => Ok(l.clone()),
            other => Err(Diag::new(&format!(
                "cannot render {} into text",
                other.type_name()
            ))),
        }
    }

    pub fn eval_ident(&mut self, name: &str) -> R {
        if let Some(v) = self.scope.get(name) {
            return Ok(v.clone());
        }
        // numeric unit suffixes handled elsewhere
        match name {
            "sys" => Ok(self.sys_module()),
            "std" => Ok(Value::Func(Func {
                name: Some("std".to_string()),
                kind: FuncKind::Native("std"),
                repr: "std".to_string(),
            })),
            "calc" => Ok(self.module("calc")),
            "str" => Ok(self.module("str")),
            "int" => Ok(self.module("int")),
            "float" => Ok(self.module("float")),
            "array" => Ok(self.module("array")),
            "dict" => Ok(self.module("dict")),
            "json" => Ok(self.module("json")),
            "yaml" => Ok(self.module("yaml")),
            "base64" => Ok(self.module("base64")),
            "duration" => Ok(self.module("duration")),
            "datetime" => Ok(self.module("datetime")),
            "sym" => Ok(self.module("sym")),
            "color" => Ok(self.module("color")),
            "counter" => Ok(self.module("counter")),
            "state" => Ok(self.module("state")),
            "math" => Ok(self.module("math")),
            "em" | "pt" | "mm" | "cm" | "in" | "deg" | "rad" | "fr" | "%" => {
                Err(Diag::new(&format!("unknown variable: {}", name)))
            }
            _ => Err(Diag::new(&format!("unknown variable: {}", name))),
        }
    }

    pub fn module(&mut self, name: &str) -> Value {
        let mut d = Dict::default();
        for f in module_funcs(name) {
            d.items.push((
                f.0.to_string(),
                Value::Func(Func {
                    name: Some(format!("{}.{}", name, f.0)),
                    kind: FuncKind::Native(f.1),
                    repr: format!("{}.{}", name, f.0),
                }),
            ));
        }
        for (k, v) in module_consts(name) {
            d.items.push((k.to_string(), v));
        }
        Value::Dict(d)
    }

    pub fn sys_module(&mut self) -> Value {
        let mut d = Dict::default();
        let inputs = prelude_inputs();
        d.items.push(("inputs".to_string(), Value::Dict(inputs)));
        d.items.push(("version".to_string(), Value::Str(crate::cli::VERSION.to_string())));
        Value::Dict(d)
    }

    pub fn eval_args(
        &mut self,
        args: &[ArgExpr],
    ) -> Result<(Vec<Value>, HashMap<String, Value>), Diag> {
        let mut pos = vec![];
        let mut named = HashMap::new();
        for a in args {
            let v = self.eval(&a.value)?;
            match &a.name {
                Some(n) if n == ".." => {
                    if let Value::Array(arr) = v {
                        for it in arr.items {
                            pos.push(it);
                        }
                    } else if let Value::Dict(d) = v {
                        for (k, val) in d.items {
                            named.insert(k, val);
                        }
                    }
                }
                Some(n) => {
                    named.insert(n.clone(), v);
                }
                None => pos.push(v),
            }
        }
        Ok((pos, named))
    }

    pub fn eval_for(&mut self, pat: &[String], iter: &Expr, body: &Expr) -> R {
        let it = self.eval(iter)?;
        let items: Vec<(Value, Value)> = match &it {
            Value::Array(a) => a
                .items
                .iter()
                .enumerate()
                .map(|(i, v)| (Value::Int(i as i64), v.clone()))
                .collect(),
            Value::Str(s) => s
                .chars()
                .enumerate()
                .map(|(i, c)| (Value::Int(i as i64), Value::Str(c.to_string())))
                .collect(),
            Value::Dict(d) => d
                .items
                .iter()
                .map(|(k, v)| (Value::Str(k.clone()), v.clone()))
                .collect(),
            other => {
                return Err(Diag::new(&format!(
                    "cannot loop over {}",
                    other.type_name()
                )))
            }
        };
        for (k, v) in items {
            self.scope.push();
            if pat.len() == 2 {
                self.scope.set(&pat[0], k);
                self.scope.set(&pat[1], v);
            } else if pat.len() == 1 {
                self.scope.set(&pat[0], v);
            }
            let r = self.eval(body);
            self.scope.pop();
            match r {
                Err(d) if d.message == "__break" => break,
                Err(d) if d.message == "__continue" => continue,
                Err(d) => return Err(d),
                Ok(v) => {
                    let _ = v;
                }
            }
        }
        Ok(Value::None)
    }
}
