pub fn prelude_inputs() -> Dict {
    let mut d = Dict::default();
    if let Some(args) = crate::args_store() {
        for (k, v) in args {
            d.items.push((k, Value::Str(v)));
        }
    }
    d
}

// ---------------------------------------------------------------------------
// Argument helpers
// ---------------------------------------------------------------------------

pub struct Args<'a> {
    pub pos: &'a [Value],
    pub named: &'a HashMap<String, Value>,
    pub used: usize,
}

impl<'a> Args<'a> {
    pub fn new(pos: &'a [Value], named: &'a HashMap<String, Value>) -> Args<'a> {
        Args { pos, named, used: 0 }
    }
    pub fn take(&mut self) -> Option<&'a Value> {
        let v = self.pos.get(self.used);
        if v.is_some() {
            self.used += 1;
        }
        v
    }
    pub fn get(&self, name: &str) -> Option<&'a Value> {
        self.named.get(name)
    }
    pub fn err(&self, fname: &str, msg: &str) -> Diag {
        let _ = fname;
        Diag::new(msg)
    }
}

pub fn type_err(found: &Value, expected: &str) -> Diag {
    Diag::new(&format!("expected {}, found {}", expected, found.type_name()))
}

pub fn to_float(v: &Value) -> Option<f64> {
    match v {
        Value::Int(i) => Some(*i as f64),
        Value::Float(f) => Some(*f),
        Value::Ratio(r) => Some(*r),
        Value::Fraction(r) => Some(*r),
        _ => None,
    }
}

pub fn to_int(v: &Value) -> Option<i64> {
    match v {
        Value::Int(i) => Some(*i),
        Value::Bool(b) => Some(*b as i64),
        _ => None,
    }
}

pub fn as_str(v: &Value) -> Option<&str> {
    match v {
        Value::Str(s) => Some(s),
        Value::Label(l) => Some(l),
        Value::Symbol(s) => Some(s),
        _ => None,
    }
}
