            }
            "even" => Ok(Value::Bool(i64_of(need(&pos, 0, "value")?)? % 2 == 0)),
            "odd" => Ok(Value::Bool(i64_of(need(&pos, 0, "value")?)? % 2 != 0)),
            "rem" | "div_euclid" | "mod_euclid" | "quotient" => {
                let a = f64_of(need(&pos, 0, "dividend")?)?;
                let b = f64_of(need(&pos, 1, "divisor")?)?;
                let both_int = matches!(pos.first(), Some(Value::Int(_)))
