                    _ => Ok(Value::Float(r)),
                }
            }
            "sqrt" => Ok(Value::Float(f64_of(need(&pos, 0, "value")?)?.sqrt())),
            "exp" => Ok(Value::Float(f64_of(need(&pos, 0, "value")?)?.exp())),
            "ln" => Ok(Value::Float(f64_of(need(&pos, 0, "value")?)?.ln())),
            "log" => {
                let v = f64_of(need(&pos, 0, "value")?)?;
                match pos.get(1) {
                    Some(b) => Ok(Value::Float(v.log(f64_of(b)?))),
                    None => Ok(Value::Float(v.log(10.0))),
                }
            }
            "sin" | "cos" | "tan" | "asin" | "acos" | "atan" | "sinh" | "cosh" | "tanh" => {
                let v = f64_of(need(&pos, 0, "value")?)?;
                let r = match key {
                    "sin" => v.sin(),
                    "cos" => v.cos(),
                    "tan" => v.tan(),
                    "asin" => v.asin(),
                    "acos" => v.acos(),
                    "atan" => v.atan(),
                    "sinh" => v.sinh(),
                    "cosh" => v.cosh(),
                    _ => v.tanh(),
                };
                Ok(Value::Float(r))
            }
            "atan2" => {
                let a = f64_of(need(&pos, 0, "y")?)?;
                let b = f64_of(need(&pos, 1, "x")?)?;
                Ok(Value::Float(a.atan2(b)))
            }
            "pow" => {
                let a = f64_of(need(&pos, 0, "base")?)?;
                let b = f64_of(need(&pos, 1, "exponent")?)?;
                if let (Some(Value::Int(x)), Some(Value::Int(y))) = (pos.first(), pos.get(1)) {
                    if *y >= 0 {
                        return Ok(Value::Int(x.pow(*y as u32)));
                    }
                }
                Ok(Value::Float(a.powf(b)))
            }
            "root" => {
                let a = f64_of(need(&pos, 0, "radicand")?)?;
                let b = f64_of(need(&pos, 1, "index")?)?;
                Ok(Value::Float(a.powf(1.0 / b)))
            }
            "gcd" | "lcm" => {
                let mut g: i64 = i64_of(need(&pos, 0, "value")?)?;
                for v in pos.iter().skip(1) {
                    let b = i64_of(v)?;
                    let mut a = g.abs();
                    let mut b = b.abs();
                    while b != 0 {
                        let t = a % b;
                        a = b;
                        b = t;
                    }
                    g = if key == "gcd" { a } else { g.abs() / a * b.abs() };
                }
                Ok(Value::Int(g))
            }
            "norm" | "clamp" | "signum" | "prob" => Err(Diag::new(&format!(
                "cannot call function `{}` in this context",
                key
            ))),
            "float_nan" => Ok(Value::Float(f64::NAN)),
            "float_inf" => Ok(Value::Float(f64::INFINITY)),
            "float_is_nan" => Ok(Value::Bool(match pos.first() {
                Some(Value::Float(f)) => f.is_nan(),
                _ => false,
            })),
            "float_is_infinite" => Ok(Value::Bool(match pos.first() {
                Some(Value::Float(f)) => f.is_infinite(),
                _ => false,
            })),
            "float_signum" | "int_signum" => {
                let v = pos.first().ok_or_else(|| Diag::new("missing argument"))?;
                match v {
                    Value::Int(i) => Ok(Value::Int(i.signum())),
                    other => Ok(Value::Float(f64_of(other)?.signum())),
                }
            }
            "int_bit_and" | "int_bit_or" | "int_bit_xor" | "int_bit_not"
            | "int_bit_lshift" | "int_bit_rshift" => {
                let a = i64_of(need(&pos, 0, "value")?)?;
                match key {
                    "int_bit_not" => Ok(Value::Int(!a)),
                    _ => {
                        let b = i64_of(need(&pos, 1, "with")?)?;
                        Ok(Value::Int(match key {
                            "int_bit_and" => a & b,
                            "int_bit_or" => a | b,
                            "int_bit_xor" => a ^ b,
                            "int_bit_lshift" => a << b,
                            _ => a >> b,
                        }))
                    }
                }
            }

            // ---- strings -----------------------------------------------------
            "str_len" => Ok(Value::Int(pos.first().and_then(as_str).map(|s| s.chars().count() as i64).unwrap_or(0))),
            "str_first" | "str_last" | "str_at" | "str_slice" | "str_clusters"
            | "str_codepoints" | "str_to_unicode" | "str_normalize" | "str_rev" => {
                let s = pos.first().and_then(as_str).unwrap_or("").to_string();
                match key {
                    "str_first" => Ok(match s.chars().next() {
                        Some(c) => Value::Str(c.to_string()),
                        None => Value::None,
                    }),
                    "str_last" => Ok(match s.chars().next_back() {
                        Some(c) => Value::Str(c.to_string()),
                        None => Value::None,
                    }),
                    "str_at" => {
                        let i = pos.get(1).and_then(to_int).unwrap_or(0);
                        Ok(match s.chars().nth(i.max(0) as usize) {
                            Some(c) => Value::Str(c.to_string()),
                            None => Value::None,
                        })
                    }
                    "str_slice" => {
                        let chars: Vec<char> = s.chars().collect();
                        let start = pos.get(1).and_then(to_int).unwrap_or(0).max(0) as usize;
                        let end = pos
                            .get(2)
                            .and_then(to_int)
                            .map(|e| e.max(0) as usize)
                            .unwrap_or(chars.len());
                        let e = end.min(chars.len());
                        let a = start.min(e);
                        Ok(Value::Str(chars[a..e].iter().collect()))
                    }
                    "str_clusters" | "str_codepoints" => Ok(Value::Array(ArrayV {
                        items: s
                            .chars()
                            .map(|c| Value::Str(c.to_string()))
                            .collect(),
                        item_sources: None,
                        repr: Repr::Canonical,
                    })),
                    "str_to_unicode" => Ok(Value::Str(
                        s.chars()
                            .map(|c| format!("U+{:04X} ", c as u32))
                            .collect::<String>()
                            .trim()
                            .to_string(),
                    )),
                    "str_rev" => Ok(Value::Str(s.chars().rev().collect())),
                    _ => Ok(Value::Str(crate::util::normalize(&s))),
                }
            }

            // ---- arrays ------------------------------------------------------
            "arr_len" => Ok(Value::Int(
                pos.first().and_then(|v| match v {
                    Value::Array(a) => Some(a.items.len() as i64),
                    _ => None,
                })
                .unwrap_or(0),
            )),
            "arr_first" | "arr_last" | "arr_at" | "arr_slice" | "arr_rev" | "arr_dedup"
            | "arr_flatten" | "arr_intersperse" | "arr_enumerate" | "arr_zip"
            | "arr_to_dict" | "arr_chunks" | "arr_windows" | "arr_split" => {
                let arr = pos.first().ok_or_else(|| Diag::new("missing argument"))?;
                let items = match arr {
                    Value::Array(a) => a.items.clone(),
                    other => return Err(type_err(other, "array")),
                };
                match key {
                    "arr_first" => Ok(items.first().cloned().unwrap_or(Value::None)),
                    "arr_last" => Ok(items.last().cloned().unwrap_or(Value::None)),
                    "arr_at" => {
                        let i = pos.get(1).and_then(to_int).unwrap_or(0);
                        Ok(items.get(i.max(0) as usize).cloned().unwrap_or(Value::None))
                    }
                    "arr_slice" => {
                        let start = pos.get(1).and_then(to_int).unwrap_or(0).max(0) as usize;
                        let end = pos
                            .get(2)
                            .and_then(to_int)
                            .map(|e| e.max(0) as usize)
                            .unwrap_or(items.len());
                        let e = end.min(items.len());
                        let a = start.min(e);
                        Ok(Value::Array(ArrayV {
                            items: items[a..e].to_vec(),
                            item_sources: None,
                            repr: Repr::Canonical,
                        }))
                    }
                    "arr_rev" => {
                        let mut it = items;
                        it.reverse();
                        Ok(Value::Array(ArrayV { items: it, item_sources: None, repr: Repr::Canonical }))
                    }
                    "arr_dedup" => {
                        let mut out: Vec<Value> = vec![];
                        for it in items {
                            if !out.iter().any(|o| o == &it) {
                                out.push(it);
                            }
                        }
                        Ok(Value::Array(ArrayV { items: out, item_sources: None, repr: Repr::Canonical }))
                    }
                    "arr_flatten" => {
                        let mut out = vec![];
                        for it in items {
                            if let Value::Array(a) = it {
                                out.extend(a.items);
                            } else {
                                out.push(it);
                            }
                        }
                        Ok(Value::Array(ArrayV { items: out, item_sources: None, repr: Repr::Canonical }))
                    }
                    "arr_enumerate" => Ok(Value::Array(ArrayV {
                        items: items
                            .into_iter()
                            .enumerate()
                            .map(|(i, v)| {
                                Value::Array(ArrayV {
                                    items: vec![Value::Int(i as i64), v],
                                    item_sources: None,
                                    repr: Repr::Canonical,
                                })
                            })
                            .collect(),
                        item_sources: None,
                        repr: Repr::Canonical,
                    })),
                    "arr_zip" => {
                        let other = match pos.get(1) {
                            Some(Value::Array(a)) => a.items.clone(),
                            _ => vec![],
                        };
                        let n = items.len().min(other.len());
                        Ok(Value::Array(ArrayV {
                            items: (0..n)
                                .map(|i| {
                                    Value::Array(ArrayV {
                                        items: vec![items[i].clone(), other[i].clone()],
                                        item_sources: None,
                                        repr: Repr::Canonical,
                                    })
                                })
                                .collect(),
                            item_sources: None,
                            repr: Repr::Canonical,
                        }))
                    }
                    "arr_to_dict" => {
                        let mut d = Dict::default();
                        for it in items {
                            if let Value::Array(a) = &it {
                                if a.items.len() == 2 {
                                    if let Some(k) = as_str(&a.items[0]) {
                                        d.items.push((k.to_string(), a.items[1].clone()));
                                        continue;
                                    }
                                }
                            }
                            return Err(Diag::new("expected (str, any) pairs"));
                        }
                        Ok(Value::Dict(d))
                    }
                    "arr_chunks" | "arr_windows" => {
                        let n = pos.get(1).and_then(to_int).unwrap_or(1).max(1) as usize;
                        let mut out = vec![];
                        if key == "arr_chunks" {
                            for ch in items.chunks(n) {
                                out.push(Value::Array(ArrayV {
                                    items: ch.to_vec(),
                                    item_sources: None,
                                    repr: Repr::Canonical,
                                }));
                            }
                        } else if items.len() >= n {
                            for w in items.windows(n) {
                                out.push(Value::Array(ArrayV {
                                    items: w.to_vec(),
                                    item_sources: None,
                                    repr: Repr::Canonical,
                                }));
                            }
                        }
                        Ok(Value::Array(ArrayV { items: out, item_sources: None, repr: Repr::Canonical }))
                    }
                    "arr_split" => {
                        let sep = pos.get(1).cloned().unwrap_or(Value::None);
                        let mut out = vec![];
                        let mut cur = vec![];
                        for it in items {
                            if it == sep {
                                out.push(Value::Array(ArrayV {
                                    items: std::mem::take(&mut cur),
                                    item_sources: None,
                                    repr: Repr::Canonical,
                                }));
                            } else {
                                cur.push(it);
                            }
                        }
                        out.push(Value::Array(ArrayV { items: cur, item_sources: None, repr: Repr::Canonical }));
                        Ok(Value::Array(ArrayV { items: out, item_sources: None, repr: Repr::Canonical }))
                    }
                    _ => Ok(Value::Array(ArrayV {
                        items,
                        item_sources: None,
                        repr: Repr::Canonical,
                    })),
                }
            }
            "arr_push" | "arr_pop" | "arr_insert" | "arr_remove" => {
                let arr = pos.first().ok_or_else(|| Diag::new("missing argument"))?;
                let mut items = match arr {
                    Value::Array(a) => a.items.clone(),
                    other => return Err(type_err(other, "array")),
                };
                match key {
                    "arr_push" => {
                        let v = need(&pos, 1, "value")?.clone();
                        items.push(v);
                        Ok(Value::None)
                    }
                    "arr_pop" => {
                        items.pop();
                        Ok(Value::None)
                    }
                    "arr_insert" => {
                        let i = pos.get(1).and_then(to_int).unwrap_or(0).max(0) as usize;
                        let v = need(&pos, 2, "value")?.clone();
                        let i = i.min(items.len());
                        items.insert(i, v);
                        Ok(Value::None)
                    }
                    _ => {
                        let i = pos.get(1).and_then(to_int).unwrap_or(0).max(0) as usize;
                        if i < items.len() {
                            items.remove(i);
                        }
                        Ok(Value::None)
                    }
                }
            }
            "arr_contains" => {
                let arr = pos.first().ok_or_else(|| Diag::new("missing argument"))?;
                let v = need(&pos, 1, "value")?;
                match arr {
                    Value::Array(a) => Ok(Value::Bool(a.items.iter().any(|x| x == v))),
                    other => Err(type_err(other, "array")),
                }
            }
            "arr_find" | "arr_position" | "arr_filter" | "arr_map" | "arr_any" | "arr_all"
            | "arr_sorted" | "arr_sum" | "arr_product" | "arr_join" | "arr_fold"
            | "arr_reduce" => {
                let arr = pos.first().ok_or_else(|| Diag::new("missing argument"))?;
                let items = match arr {
                    Value::Array(a) => a.items.clone(),
                    other => return Err(type_err(other, "array")),
                };
                match key {
                    "arr_sum" | "arr_product" => {
                        let mut acc = if key == "arr_sum" { 0.0 } else { 1.0 };
                        let mut all_int = true;
                        for it in &items {
                            match it {
                                Value::Int(i) => {
                                    if key == "arr_sum" {
                                        acc += *i as f64
                                    } else {
                                        acc *= *i as f64
                                    }
                                }
                                Value::Float(f) => {
                                    all_int = false;
                                    if key == "arr_sum" {
                                        acc += f
                                    } else {
                                        acc *= f
                                    }
                                }
                                other => {
                                    return Err(type_err(
                                        other,
                                        "numeric value",
                                    ))
                                }
                            }
                        }
                        Ok(if all_int { Value::Int(acc as i64) } else { Value::Float(acc) })
                    }
                    "arr_join" => {
                        let sep = match pos.get(1) {
                            Some(Value::Str(s)) => s.clone(),
                            _ => ", ".to_string(),
                        };
                        let last = pos.get(2).and_then(as_str).map(|s| s.to_string());
                        let mut out = String::new();
                        for (i, it) in items.iter().enumerate() {
                            if i > 0 {
                                if i + 1 == items.len() {
                                    if let Some(l) = &last {
                                        out.push_str(l);
                                        continue;
                                    }
                                }
                                out.push_str(&sep);
                            }
                            match it {
                                Value::Str(s) => out.push_str(s),
                                Value::Content(c) => out.push_str(&crate::ser::content_text(c)),
                                other => out.push_str(&other.repr()),
                            }
                        }
                        Ok(Value::Str(out))
                    }
                    "arr_sorted" => {
                        let mut it = items;
                        it.sort_by(|a, b| {
                            let av = crate::ser::sort_key(a);
                            let bv = crate::ser::sort_key(b);
                            av.partial_cmp(&bv).unwrap_or(std::cmp::Ordering::Equal)
                        });
                        Ok(Value::Array(ArrayV { items: it, item_sources: None, repr: Repr::Canonical }))
                    }
                    _ => {
                        let f = need(&pos, 1, "function")?;
                        match key {
                            "arr_map" => {
                                let mut out = vec![];
                                for it in items {
                                    out.push(self.call(f, vec![it.clone()], HashMap::new())?);
                                }
                                Ok(Value::Array(ArrayV {
                                    items: out,
                                    item_sources: None,
                                    repr: Repr::Canonical,
                                }))
                            }
                            "arr_filter" => {
                                let mut out = vec![];
                                for it in items {
                                    let r = self.call(f, vec![it.clone()], HashMap::new())?;
                                    if matches!(r, Value::Bool(true)) {
                                        out.push(it);
                                    }
                                }
                                Ok(Value::Array(ArrayV {
                                    items: out,
                                    item_sources: None,
                                    repr: Repr::Canonical,
                                }))
                            }
                            "arr_any" | "arr_all" => {
                                let mut res = key == "arr_all";
                                for it in items {
                                    let r = self.call(f, vec![it.clone()], HashMap::new())?;
                                    let b = matches!(r, Value::Bool(true));
                                    if key == "arr_any" && b {
                                        res = true;
                                        break;
                                    }
                                    if key == "arr_all" && !b {
                                        res = false;
                                        break;
                                    }
                                }
                                Ok(Value::Bool(res))
                            }
                            "arr_find" => {
                                for it in items {
                                    let r = self.call(f, vec![it.clone()], HashMap::new())?;
                                    if matches!(r, Value::Bool(true)) {
                                        return Ok(it);
                                    }
                                }
                                Ok(Value::None)
                            }
                            "arr_position" => {
                                for (i, it) in items.iter().enumerate() {
                                    let r = self.call(f, vec![it.clone()], HashMap::new())?;
                                    if matches!(r, Value::Bool(true)) {
                                        return Ok(Value::Int(i as i64));
                                    }
                                }
                                Ok(Value::None)
                            }
                            "arr_fold" => {
                                let mut acc = pos.get(2).cloned().unwrap_or(Value::None);
                                for it in items {
                                    acc = self.call(
                                        f,
                                        vec![acc, it.clone()],
                                        HashMap::new(),
                                    )?;
                                }
                                Ok(acc)
                            }
                            _ => {
                                // reduce
                                if items.is_empty() {
                                    return Ok(Value::None);
                                }
                                let mut acc = items[0].clone();
                                for it in items.iter().skip(1) {
                                    acc = self.call(f, vec![acc, it.clone()], HashMap::new())?;
                                }
                                Ok(acc)
                            }
                        }
                    }
                }
            }

            // ---- dicts -------------------------------------------------------
            "dict_len" => Ok(Value::Int(
                pos.first().and_then(|v| match v {
                    Value::Dict(d) => Some(d.len() as i64),
                    _ => None,
                })
                .unwrap_or(0),
            )),
            "dict_at" | "dict_insert" | "dict_remove" | "dict_keys" | "dict_values"
            | "dict_contains" => {
                let d = pos.first().ok_or_else(|| Diag::new("missing argument"))?;
                let mut dict = match d {
                    Value::Dict(d) => d.clone(),
                    other => return Err(type_err(other, "dictionary")),
                };
                match key {
                    "dict_len" => Ok(Value::Int(dict.len() as i64)),
                    "dict_keys" => Ok(Value::Array(ArrayV {
                        items: dict.keys().into_iter().map(Value::Str).collect(),
                        item_sources: None,
                        repr: Repr::Canonical,
                    })),
                    "dict_values" => Ok(Value::Array(ArrayV {
                        items: dict.values(),
                        item_sources: None,
                        repr: Repr::Canonical,
                    })),
                    "dict_contains" => {
                        let k = need(&pos, 1, "key")?;
                        match as_str(k) {
                            Some(k) => Ok(Value::Bool(dict.contains(k))),
                            None => Err(type_err(k, "string")),
                        }
                    }
                    "dict_at" => {
                        let k = need(&pos, 1, "key")?;
                        match as_str(k) {
                            Some(k) => Ok(dict.get(k).cloned().unwrap_or(Value::None)),
                            None => Err(type_err(k, "string")),
                        }
                    }
                    "dict_insert" => {
                        let k = need(&pos, 1, "key")?;
                        let v = need(&pos, 2, "value")?.clone();
                        match as_str(k) {
                            Some(k) => {
                                dict.items.retain(|(n, _)| n != k);
                                dict.items.push((k.to_string(), v));
                                Ok(Value::None)
                            }
                            None => Err(type_err(k, "string")),
                        }
                    }
                    _ => {
                        let k = need(&pos, 1, "key")?;
                        match as_str(k) {
                            Some(k) => {
                                let v = dict.get(k).cloned();
                                dict.items.retain(|(n, _)| n != k);
                                let _ = v;
                                Ok(Value::None)
                            }
                            None => Err(type_err(k, "string")),
                        }
                    }
                }
            }

            // ---- misc --------------------------------------------------------
            "assert" => {
                let v = pos.first().cloned().unwrap_or(Value::None);
                match v {
                    Value::Bool(true) => Ok(Value::None),
                    Value::Bool(false) => {
                        let msg = pos.get(1).and_then(as_str).unwrap_or("assertion failed");
                        Err(Diag::new(msg))
                    }
                    other => Err(type_err(other, "boolean")),
                }
            }
            "panic" => {
                let msg = pos
                    .first()
                    .and_then(as_str)
                    .unwrap_or("panicked")
                    .to_string();
                Err(Diag::new(&msg))
            }
            "eval" => {
                let src = pos.first().and_then(as_str).unwrap_or("").to_string();
                let mut p = crate::code::Parser::new(&src);
                let e = match p.parse_expr(false) {
                    Ok(e) => e,
                    Err(m) => return Err(Diag::new(&m)),
                };
                self.eval(&e.expr)
            }
            "counter_get" | "counter_at" | "counter_final" | "counter_step"
            | "counter_update" | "counter_state" | "state_get" | "state_at"
            | "state_final" | "state_update" => {
                Err(Diag::new("can only be used when context is known")
                    .hint("try wrapping this in a `context` expression")
                    .hint("the `context` expression should wrap everything that depends on this function"))
            }
            _ => Err(Diag::new(&format!("unknown function: {}", key))),
        }
    }

    fn make_color(&mut self, kind: &str, pos: &[Value], named: &HashMap<String, Value>) -> R {
        let repr = match kind {
            "luma" => {
                let c = named
                    .get("lightness")
                    .or_else(|| pos.first())
                    .and_then(to_float)
                    .unwrap_or(0.0);
                format!("luma({}%)", (c * 100.0).round() as i64)
            }
            _ => {
                if let Some(Value::Str(s)) = pos.first() {
                    format!("{}({})", kind, crate::value::format_str_repr(s))
                } else {
                    format!("{}(..)", kind)
                }
            }
        };
        let comps = vec![0.0, 0.0, 0.0];
        let c = match kind {
            "luma" => Color::Luma { components: comps, repr, alpha: 1.0 },
            "cmyk" => Color::Cmyk { components: comps, repr, alpha: 1.0 },
            "oklab" => Color::Oklab { components: comps, repr, alpha: 1.0 },
            "oklch" => Color::Oklch { components: comps, repr, alpha: 1.0 },
            _ => Color::Rgb { components: comps, repr, alpha: 1.0 },
        };
        Ok(Value::Color(c))
    }

    pub fn apply_set(&mut self, _name: &str, _args: &[crate::code::ArgExpr]) -> R {
        Ok(Value::None)
    }
}

fn num(is_int: bool, f: f64) -> Value {
    if is_int {
        Value::Int(f as i64)
    } else {
        Value::Float(f)
    }
}
