//! Serialization helpers (JSON/YAML and content <-> text).

use crate::value::*;

pub fn content_text(c: &Content) -> String {
    let mut out = String::new();
    for e in &c.elems {
        match e {
            Elem::Text(t) => out.push_str(t),
            Elem::Space => out.push(' '),
            Elem::Linebreak => out.push('\n'),
            Elem::Symbol(s) => out.push_str(s),
            Elem::Smartquote { double } => out.push(if *double { '"' } else { '\'' }),
            Elem::Sequence(inner) => out.push_str(&content_text(inner)),
            Elem::Strong { body } | Elem::Emph { body } => out.push_str(&content_text(body)),
            Elem::Item { body } => out.push_str(&content_text(body)),
            _ => {}
        }
    }
    out
}

pub fn sort_key(v: &Value) -> f64 {
    match v {
        Value::Int(i) => *i as f64,
        Value::Float(f) => *f,
        Value::Bool(b) => *b as i64 as f64,
        Value::Str(s) => s.chars().next().map(|c| c as u32 as f64).unwrap_or(0.0),
        _ => 0.0,
    }
}
