impl Machine {
    pub fn eval_binary(&mut self, op: BinOp, a: &Expr, b: &Expr) -> R {
        match op {
            BinOp::AddAssign | BinOp::SubAssign | BinOp::MulAssign | BinOp::DivAssign => {
                let name = match a {
                    Expr::Ident(n) => n.clone(),
                    _ => return Err(Diag::new("cannot assign to this expression")),
                };
                let cur = self.eval(a)?;
                let rhs = self.eval(b)?;
                let v = match op {
                    BinOp::AddAssign => self.add(cur, rhs)?,
                    BinOp::SubAssign => self.sub(cur, rhs)?,
                    BinOp::MulAssign => self.mul(cur, rhs)?,
                    _ => self.div(cur, rhs)?,
                };
                self.scope.set(&name, v);
                Ok(Value::None)
            }
            BinOp::Assign => {
                let name = match a {
                    Expr::Ident(n) => n.clone(),
                    _ => return Err(Diag::new("cannot assign to this expression")),
                };
                let rhs = self.eval(b)?;
                self.scope.set(&name, rhs);
                Ok(Value::None)
            }
            BinOp::And => {
                let x = self.eval(a)?;
                match x {
                    Value::Bool(false) => Ok(Value::Bool(false)),
                    Value::Bool(true) => {
                        let y = self.eval(b)?;
                        match y {
                            Value::Bool(b2) => Ok(Value::Bool(b2)),
                            o => Err(Diag::new(&format!(
                                "expected boolean, found {}",
                                o.type_name()
                            ))),
                        }
                    }
                    o => Err(Diag::new(&format!(
                        "expected boolean, found {}",
                        o.type_name()
                    ))),
                }
            }
            BinOp::Or => {
                let x = self.eval(a)?;
                match x {
                    Value::Bool(true) => Ok(Value::Bool(true)),
                    Value::Bool(false) => {
                        let y = self.eval(b)?;
                        match y {
                            Value::Bool(b2) => Ok(Value::Bool(b2)),
                            o => Err(Diag::new(&format!(
                                "expected boolean, found {}",
                                o.type_name()
                            ))),
                        }
                    }
                    o => Err(Diag::new(&format!(
                        "expected boolean, found {}",
                        o.type_name()
                    ))),
                }
            }
            _ => {
                let x = self.eval(a)?;
                let y = self.eval(b)?;
                match op {
                    BinOp::Add => self.add(x, y),
                    BinOp::Sub => self.sub(x, y),
                    BinOp::Mul => self.mul(x, y),
                    BinOp::Div => self.div(x, y),
                    BinOp::Eq => Ok(Value::Bool(crate::ser::value_eq(&x, &y))),
                    BinOp::Ne => Ok(Value::Bool(!crate::ser::value_eq(&x, &y))),
                    BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge => {
                        let c = crate::ser::cmp(&x, &y, op)?;
                        Ok(Value::Bool(c))
                    }
                    BinOp::In | BinOp::NotIn => {
                        let has = match (&y, &x) {
                            (Value::Array(arr), v) => arr.items.iter().any(|i| crate::ser::value_eq(i, v)),
                            (Value::Str(s), Value::Str(sub)) => s.contains(sub.as_str()),
                            (Value::Dict(d), Value::Str(k)) => d.contains(k),
                            _ => false,
                        };
                        Ok(Value::Bool(if matches!(op, BinOp::In) { has } else { !has }))
                    }
                    _ => unreachable!(),
                }
            }
        }
    }

    pub fn add(&mut self, x: Value, y: Value) -> R {
        if let Some(v) = num_add(&x, &y) {
            return Ok(v);
        }
        match (&x, &y) {
            (Value::Str(a), Value::Str(b)) => Ok(Value::Str(format!("{}{}", a, b))),
            (Value::Str(a), other) => Ok(Value::Str(format!(
                "{}{}",
                a,
                crate::ser::content_text(&self.value_as_content(other)?)
            ))),
            (Value::Array(a), Value::Array(b)) => {
                let mut items = a.items.clone();
                items.extend(b.items.clone());
                Ok(Value::Array(ArrayV {
                    items,
                    item_sources: None,
                    repr: Repr::Canonical,
                }))
            }
            (Value::Dict(a), Value::Dict(b)) => {
                let mut items = a.items.clone();
                for (k, v) in &b.items {
                    items.retain(|(n, _)| n != k);
                    items.push((k.clone(), v.clone()));
                }
                Ok(Value::Dict(Dict { items }))
            }
            (Value::Content(a), other) | (other, Value::Content(a))
                if matches!(other, Value::Content(_) | Value::Str(_)) =>
            {
                let b = self.value_as_content(other)?;
                let mut elems = a.elems.clone();
                elems.extend(b.elems);
                Ok(Value::Content(Content { elems }))
            }
            _ => Err(Diag::new(&format!(
                "cannot add {} and {}",
                x.type_name(),
                y.type_name()
            ))),
        }
    }

    pub fn value_as_content(&mut self, v: &Value) -> Result<Content, Diag> {
        match v {
            Value::Content(c) => Ok(c.clone()),
            Value::Str(s) => Ok(Content::text(s)),
            other => {
                let _ = other;
                Err(Diag::new("cannot convert value to content"))
            }
        }
    }

    pub fn sub(&mut self, x: Value, y: Value) -> R {
        match (&x, &y) {
            (Value::Int(a), Value::Int(b)) => Ok(Value::Int(a.wrapping_sub(*b))),
            (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a - b)),
            (Value::Int(a), Value::Float(b)) => Ok(Value::Float(*a as f64 - b)),
            (Value::Float(a), Value::Int(b)) => Ok(Value::Float(a - *b as f64)),
            (Value::Length(a), Value::Length(b)) => Ok(Value::Length(a - b)),
            (Value::Length(a), Value::Int(b)) => Ok(Value::Length(a - *b as f64)),
            (Value::Int(a), Value::Length(b)) => Ok(Value::Length(*a as f64 - b)),
            (Value::Length(a), Value::Float(b)) => Ok(Value::Length(a - b)),
            (Value::Float(a), Value::Length(b)) => Ok(Value::Length(a - b)),
            (Value::Angle(a), Value::Angle(b)) => Ok(Value::Angle(a - b)),
            (Value::Ratio(a), Value::Ratio(b)) => Ok(Value::Ratio(a - b)),
            (Value::Fraction(a), Value::Fraction(b)) => Ok(Value::Fraction(a - b)),
            (Value::Duration(a), Value::Duration(b)) => Ok(Value::Duration(a - b)),
            (Value::Ratio(a), Value::Length(b)) => Ok(Value::Length(b * a)),
            (Value::Array(a), Value::Array(b)) => {
                let mut items = a.items.clone();
                for r in &b.items {
                    items.retain(|i| !crate::ser::value_eq(i, r));
                }
                Ok(Value::Array(ArrayV {
                    items,
                    item_sources: None,
                    repr: Repr::Canonical,
                }))
            }
            _ => Err(Diag::new(&format!(
                "cannot subtract {} from {}",
                y.type_name(),
                x.type_name()
            ))),
        }
    }

    pub fn mul(&mut self, x: Value, y: Value) -> R {
        if let Some(v) = num_mul(&x, &y) {
            return Ok(v);
        }
        match (&x, &y) {
            (Value::Array(a), Value::Int(n)) | (Value::Int(n), Value::Array(a)) => {
                let mut items = vec![];
                for _ in 0..(*n).max(0) {
                    items.extend(a.items.clone());
                }
                Ok(Value::Array(ArrayV {
                    items,
                    item_sources: None,
                    repr: Repr::Canonical,
                }))
            }
            (Value::Content(c), Value::Int(n)) | (Value::Int(n), Value::Content(c)) => {
                let mut elems = vec![];
                for _ in 0..(*n).max(0) {
                    elems.extend(c.elems.clone());
                }
                Ok(Value::Content(Content { elems }))
            }
            (Value::Str(s), Value::Int(n)) | (Value::Int(n), Value::Str(s)) => {
                Ok(Value::Str(s.repeat((*n).max(0) as usize)))
            }
            (Value::Ratio(a), Value::Ratio(b)) => Ok(Value::Ratio(a * b)),
            _ => Err(Diag::new(&format!(
                "cannot multiply {} and {}",
                x.type_name(),
                y.type_name()
            ))),
        }
    }

    pub fn div(&mut self, x: Value, y: Value) -> R {
        match (&x, &y) {
            (Value::Int(a), Value::Int(b)) => {
                if *b == 0 {
                    Ok(Value::Float(f64::INFINITY))
                } else {
                    Ok(Value::Float(*a as f64 / *b as f64))
                }
            }
            (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a / b)),
            (Value::Int(a), Value::Float(b)) => Ok(Value::Float(*a as f64 / b)),
            (Value::Float(a), Value::Int(b)) => Ok(Value::Float(a / *b as f64)),
            (Value::Length(a), Value::Length(b)) => Ok(Value::Float(a / b)),
            (Value::Length(a), Value::Int(b)) => Ok(Value::Length(a / *b as f64)),
            (Value::Length(a), Value::Float(b)) => Ok(Value::Length(a / b)),
            (Value::Int(a), Value::Length(b)) => Ok(Value::Length(*a as f64 / b)),
            (Value::Float(a), Value::Length(b)) => Ok(Value::Length(a / b)),
            (Value::Angle(a), Value::Angle(b)) => Ok(Value::Float(a / b)),
            (Value::Ratio(a), Value::Ratio(b)) => Ok(Value::Float(a / b)),
            (Value::Ratio(a), Value::Length(b)) => Ok(Value::Length(b / a)),
            (Value::Length(a), Value::Ratio(b)) => Ok(Value::Length(a / b)),
            (Value::Duration(a), Value::Duration(b)) => Ok(Value::Float(a / b)),
            (Value::Int(a), Value::Ratio(b)) => Ok(Value::Ratio(*a as f64 / b)),
            (Value::Int(a), Value::Fraction(b)) => Ok(Value::Fraction(*a as f64 / b)),
            _ => Err(Diag::new(&format!(
                "cannot divide {} by {}",
                x.type_name(),
                y.type_name()
            ))),
        }
    }

    pub fn neg(&mut self, v: Value) -> R {
        match v {
            Value::Int(i) => Ok(Value::Int(-i)),
            Value::Float(f) => Ok(Value::Float(-f)),
            Value::Length(l) => Ok(Value::Length(-l)),
            Value::Angle(a) => Ok(Value::Angle(-a)),
            Value::Ratio(r) => Ok(Value::Ratio(-r)),
            Value::Fraction(f) => Ok(Value::Fraction(-f)),
            Value::Duration(d) => Ok(Value::Duration(-d)),
            other => Err(Diag::new(&format!(
                "cannot negate {}",
                other.type_name()
            ))),
        }
    }

    /// Field access on a value (also handles method calls).
    pub fn field(&mut self, obj: &Value, name: &str) -> R {
