        (Value::Float(x), Value::Int(y)) => Some(Value::Float(x * *y as f64)),
        (Value::Length(x), Value::Int(y)) => Some(Value::Length(x * *y as f64)),
        (Value::Int(x), Value::Length(y)) => Some(Value::Length(*x as f64 * y)),
        (Value::Length(x), Value::Float(y)) => Some(Value::Length(x * y)),
        (Value::Float(x), Value::Length(y)) => Some(Value::Length(x * y)),
        (Value::Angle(x), Value::Int(y)) => Some(Value::Angle(x * *y as f64)),
        (Value::Ratio(x), Value::Int(y)) => Some(Value::Ratio(x * *y as f64)),
