    /// Parses and evaluates markup source, producing content.
    pub fn eval_markup(&mut self, src: &str) -> Result<Content, Diag> {
        let inner = src
            .chars()
            .next()
            .map(|c| c == '[')
            .unwrap_or(false);
        let text = if inner {
            let chars: Vec<char> = src.chars().collect();
            let mut s: String = chars[1..].iter().collect();
            if s.ends_with(']') {
                s.pop();
            }
            s
        } else {
            src.to_string()
        };
        struct ME<'m>(&'m mut Machine);
        impl crate::syntax::MarkupEval for ME<'_> {
            fn eval_code(&mut self, src: &str) -> Result<Content, String> {
                let mut p = crate::code::Parser::new(src);
                let e = p.parse_expr(false).map_err(|m| m)?;
                match self.0.eval(&e.expr) {
                    Ok(Value::Content(c)) => Ok(c),
                    Ok(v) => Ok(Content::text(&self.0.value_to_text(&v).map_err(|m| m.message)?)),
                    Err(d) => Err(d.message),
                }
            }
            fn eval_ref(&mut self, target: &str) -> Result<Content, String> {
                Ok(Content {
                    elems: vec![Elem::Ref { target: format!("<{}>", target), supplement: None }],
                })
            }
        }
        match crate::syntax::parse_markup(&text, &mut ME(self)) {
            Ok(c) => Ok(c),
            Err(e) => Err(Diag::new(&e.msg)),
        }
    }

    pub fn eval_math(&mut self, src: &str) -> Result<Vec<Elem>, Diag> {
        let chars: Vec<char> = src.chars().collect();
        let body: String = if chars.first() == Some(&'$') && chars.last() == Some(&'$') && chars.len() >= 2 {
            chars[1..chars.len() - 1].iter().collect()
        } else {
            src.to_string()
        };
        let mut c = crate::syntax::Chars::new(&body);
        let mut out = vec![];
        let mut run = String::new();
        while let Some(ch) = c.peek() {
            c.bump();
            if ch.is_alphabetic() || ch.is_ascii_digit() {
                run.push(ch);
            } else {
                if !run.is_empty() {
                    out.push(Elem::Text(std::mem::take(&mut run)));
                }
                match ch {
                    ' ' => out.push(Elem::Space),
                    '\\' => {
                        let e = match c.bump() {
                            Some(e) => e,
                            None => return Err(Diag::new("unclosed delimiter")),
                        };
                        out.push(Elem::Symbol(e.to_string()));
                    }
                    _ => out.push(Elem::Symbol(ch.to_string())),
                }
            }
        }
        if !run.is_empty() {
            out.push(Elem::Text(run));
        }
        Ok(out)
    }
}
