pub fn value_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::None, Value::None) => true,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Float(x), Value::Float(y)) => x == y,
        (Value::Int(x), Value::Float(y)) => (*x as f64) == *y,
        (Value::Float(x), Value::Int(y)) => *x == (*y as f64),
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Label(x), Value::Label(y)) => x == y,
        (Value::Symbol(x), Value::Symbol(y)) => x == y,
        (Value::Array(x), Value::Array(y)) => {
            x.items.len() == y.items.len()
                && x.items.iter().zip(y.items.iter()).all(|(a, b)| value_eq(a, b))
        }
        (Value::Dict(x), Value::Dict(y)) => {
            x.items.len() == y.items.len()
                && x.items.iter().all(|(k, v)| {
                    y.get(k).map(|o| value_eq(v, o)).unwrap_or(false)
                })
        }
        (Value::Content(x), Value::Content(y)) => x == y,
        (Value::Type(x), Value::Type(y)) => x == y,
        (Value::Alignment(x), Value::Alignment(y)) => x == y,
        (Value::Direction(x), Value::Direction(y)) => x == y,
        (Value::Length(x), Value::Length(y)) => x == y,
        (Value::Angle(x), Value::Angle(y)) => x == y,
        (Value::Ratio(x), Value::Ratio(y)) => x == y,
        (Value::Fraction(x), Value::Fraction(y)) => x == y,
        (Value::Datetime(x), Value::Datetime(y)) => x == y,
        _ => false,
    }
}

pub fn cmp(a: &Value, b: &Value, op: crate::code::BinOp) -> Result<bool, crate::eval::Diag> {
    use crate::code::BinOp;
    let ord = match (a, b) {
        (Value::Int(x), Value::Int(y)) => x.partial_cmp(y),
        (Value::Float(x), Value::Float(y)) => x.partial_cmp(y),
        (Value::Int(x), Value::Float(y)) => (*x as f64).partial_cmp(y),
        (Value::Float(x), Value::Int(y)) => x.partial_cmp(&(*y as f64)),
        (Value::Str(x), Value::Str(y)) => Some(x.cmp(y)),
        (Value::Length(x), Value::Length(y)) => x.partial_cmp(y),
        (Value::Angle(x), Value::Angle(y)) => x.partial_cmp(y),
        (Value::Ratio(x), Value::Ratio(y)) => x.partial_cmp(y),
        (Value::Fraction(x), Value::Fraction(y)) => x.partial_cmp(y),
        _ => {
            return Err(crate::eval::Diag::new(&format!(
                "cannot compare {} and {}",
                a.type_name(),
                b.type_name()
            )))
        }
    };
    let ord = match ord {
        Some(o) => o,
        None => return Ok(false),
    };
    Ok(match op {
        BinOp::Lt => ord == std::cmp::Ordering::Less,
        BinOp::Le => ord != std::cmp::Ordering::Greater,
        BinOp::Gt => ord == std::cmp::Ordering::Greater,
        _ => ord != std::cmp::Ordering::Less,
    })
}
