/// Converts a value to a JSON string the way `typst eval` does.
pub fn to_json(v: &Value, pretty: bool) -> String {
    let mut out = String::new();
    j_value(v, &mut out, pretty, 0);
    out
}

fn indent(n: usize) -> String {
    "  ".repeat(n)
}

pub fn j_value(v: &Value, out: &mut String, pretty: bool, level: usize) {
    match v {
        Value::None => out.push_str("null"),
        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Value::Int(i) => out.push_str(&i.to_string()),
        Value::Float(f) => out.push_str(&crate::util::fmt_float(*f)),
        Value::Ratio(r) => out.push_str(&crate::util::fmt_float(*r)),
        Value::Fraction(r) => out.push_str(&crate::util::fmt_float(*r)),
        Value::Str(s) => out.push_str(&jstr(s)),
        Value::Symbol(s) => out.push_str(&jstr(s)),
        Value::Label(l) => out.push_str(&jstr(&v.repr())),
        Value::Bytes(b) => out.push_str(&jstr(&v.repr())),
        Value::Length(_) | Value::Angle(_) | Value::Datetime(_) | Value::Duration(_)
        | Value::Counter(_) | Value::State(_) | Value::Color(_) | Value::Func(_)
        | Value::Type(_) | Value::Alignment(_) | Value::Direction(_)
        | Value::Arguments(_) | Value::Plugin(_) => {
            out.push_str(&jstr(&v.repr()))
        }
        Value::Array(a) => {
            if a.items.is_empty() {
                out.push_str("[]");
                return;
            }
            out.push('[');
            for (i, it) in a.items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                if pretty {
                    out.push('\n');
                    out.push_str(&indent(level + 1));
                }
                j_value(it, out, pretty, level + 1);
            }
            if pretty {
                out.push('\n');
                out.push_str(&indent(level));
            }
            out.push(']');
        }
        Value::Dict(d) => {
            if d.items.is_empty() {
                out.push_str("{}");
                return;
            }
            out.push('{');
            for (i, (k, val)) in d.items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                if pretty {
                    out.push('\n');
                    out.push_str(&indent(level + 1));
                }
                out.push_str(&jstr(k));
                out.push(':');
                if pretty {
                    out.push(' ');
                }
                j_value(val, out, pretty, level + 1);
            }
            if pretty {
                out.push('\n');
                out.push_str(&indent(level));
            }
            out.push('}');
        }
        Value::Content(c) => content_json(c, out, pretty, level),
    }
}

fn push_field(out: &mut String, pretty: bool, level: usize, first: bool, k: &str, v: &dyn Fn(&mut String, bool, usize)) {
    if !first {
        out.push(',');
    }
    if pretty {
        out.push('\n');
        out.push_str(&indent(level + 1));
    }
    out.push_str(&jstr(k));
    out.push(':');
    if pretty {
        out.push(' ');
    }
    v(out, pretty, level + 1);
}

pub fn content_json(c: &Content, out: &mut String, pretty: bool, level: usize) {
    out.push('{');
    push_field(
        out,
        pretty,
        level,
        true,
        "func",
        &|o: &mut String, _p: bool, _l: usize| {
            let _ = (o, _p, _l);
        },
    );
    let _ = push_field;
    // Write fields manually for clarity
    let mut fields: Vec<(&str, JVal2)> = vec![];
    match &c.elems[..] {
        [] => {}
        [Elem::Text(t)] => {
            fields.push(("func", JVal2::S("text")));
            fields.push(("text", JVal2::S(t)));
        }
        [Elem::Space] => {
            fields.push(("func", JVal2::S("space")));
        }
        _ => {
            // sequence
            fields.push(("func", JVal2::S("sequence")));
            let children: Vec<Value> = c
                .elems
                .iter()
                .map(|e| Value::Content(Content { elems: vec![e.clone()] }))
                .collect();
            fields.push(("children", JVal2::Arr(children)));
        }
    }
    for (i, (k, val)) in fields.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        if pretty {
            out.push('\n');
            out.push_str(&indent(level + 1));
        }
        out.push_str(&jstr(k));
        out.push(':');
        if pretty {
            out.push(' ');
        }
        match val {
            JVal2::S(s) => out.push_str(&jstr(s)),
            JVal2::Arr(items) => {
                if items.is_empty() {
                    out.push_str("[]");
                } else {
                    out.push('[');
                    for (n, it) in items.iter().enumerate() {
                        if n > 0 {
                            out.push(',');
                        }
                        if pretty {
                            out.push('\n');
                            out.push_str(&indent(level + 2));
                        }
                        j_value(it, out, pretty, level + 2);
                    }
                    if pretty {
                        out.push('\n');
                        out.push_str(&indent(level + 1));
                    }
                    out.push(']');
                }
            }
        }
    }
    if pretty {
        out.push('\n');
        out.push_str(&indent(level));
    }
    out.push('}');
}

enum JVal2 {
    S(&'static str),
    Arr(Vec<Value>),
}

/// YAML serialization.
pub fn to_yaml(v: &Value) -> String {
    let mut out = String::new();
    y_value(v, &mut out, 0);
    out
}

fn y_value(v: &Value, out: &mut String, level: usize) {
    let pad = indent(level);
    match v {
        Value::None => out.push_str(&format!("{}\n", pad)),
        Value::Bool(b) => out.push_str(&format!("{}{}\n", pad, b)),
        Value::Int(i) => out.push_str(&format!("{}{}\n", pad, i)),
        Value::Float(f) => out.push_str(&format!("{}{}\n", pad, crate::util::fmt_float(*f))),
        Value::Str(s) => out.push_str(&format!("{}{}\n", pad, y_str(s))),
        Value::Symbol(s) => out.push_str(&format!("{}{}\n", pad, y_str(s))),
        Value::Label(_) | Value::Bytes(_) => out.push_str(&format!("{}{}\n", pad, v.repr())),
        Value::Array(a) => {
            if a.items.is_empty() {
                out.push_str(&format!("{}[]\n", pad));
                return;
            }
            for it in &a.items {
                match it {
                    Value::Dict(_) | Value::Array(_) => {
                        out.push_str(&format!("{}-\n", pad));
                        y_value(it, out, level + 2);
                    }
                    _ => {
                        out.push_str(&format!("{}- ", pad));
                        y_value(it, out, 0);
                    }
                }
            }
        }
        Value::Dict(d) => {
            if d.items.is_empty() {
                out.push_str(&format!("{}{{}}\n", pad));
                return;
            }
            for (k, val) in &d.items {
                match val {
                    Value::Dict(inner) if !inner.items.is_empty() => {
                        out.push_str(&format!("{}{}:\n", pad, k));
                        y_value(val, out, level + 1);
                    }
                    Value::Array(inner) if !inner.items.is_empty() => {
                        out.push_str(&format!("{}{}:\n", pad, k));
                        y_value(val, out, level + 1);
                    }
                    _ => {
                        out.push_str(&format!("{}{}: ", pad, k));
                        y_value(val, out, 0);
                    }
                }
            }
        }
        Value::Content(_) => out.push_str(&format!("{}{}\n", pad, v.repr())),
        _ => out.push_str(&format!("{}{}\n", pad, v.repr())),
    }
}

fn y_str(s: &str) -> String {
    let needs = s.is_empty()
        || s.chars().next().map(|c| "-?:,[]{}#&*!|>'\"%@`".contains(c)).unwrap_or(false)
        || s.contains(": ") || s.contains(" #") || s.contains('\n');
    if needs {
        jstr(s)
    } else {
        s.to_string()
    }
}
