pub fn j_value(v: &Value, out: &mut String, pretty: bool, level: usize) {
    match v {
        Value::None => out.push_str("null"),
        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Value::Int(i) => out.push_str(&i.to_string()),
        Value::Float(f) => out.push_str(&crate::util::fmt_float(*f)),
        Value::Ratio(r) => out.push_str(&crate::util::fmt_float(*r)),
        Value::Fraction(r) => out.push_str(&crate::util::fmt_float(*r)),
        Value::Str(s) => out.push_str(&jstr(s)),
        Value::Symbol(s) => out.push_str(&jstr(s)),
        Value::Label(l) => out.push_str(&jstr(&v.repr())),
        Value::Bytes(b) => out.push_str(&jstr(&v.repr())),
        Value::Length(_) | Value::Angle(_) | Value::Datetime(_) | Value::Duration(_)
        | Value::Counter(_) | Value::State(_) | Value::Color(_) | Value::Func(_)
        | Value::Type(_) | Value::Alignment(_) | Value::Direction(_)
        | Value::Arguments(_) | Value::Plugin(_) => {
            out.push_str(&jstr(&v.repr()))
        }
        Value::Array(a) => {
            if a.items.is_empty() {
                out.push_str("[]");
                return;
            }
            out.push('[');
            for (i, it) in a.items.iter().enumerate() {
                if i > 0 {
