// ---------------------------------------------------------------------------
// The `eval` command
// ---------------------------------------------------------------------------

pub fn run(m: &crate::cli::Matches, _c: &crate::cli::Cli, color: Option<&str>) {
    let pretty = m.has("--pretty");
    let format = m.get("--format").unwrap_or("json").to_string();
    // Evaluate the file given with --in first (its errors are reported).
    if let Some(f) = m.get("--in") {
        let (text, path) = match crate::cli::read_input(f) {
            Ok(t) => t,
            Err(e) => {
                eprint!("{}", e);
                std::process::exit(1);
            }
        };
        let mut machine = Machine::new(false, false);
        if let Err(d) = eval_file(&text, &path, &mut machine, color) {
            eprint!("{}", d);
            std::process::exit(1);
        }
    }
    let expr = m.positionals.first().cloned().unwrap_or_default();
    let mut machine = Machine::new(false, false);
    let mut p = crate::code::Parser::new(&expr);
    let e = match p.parse_expr(false) {
        Ok(e) => e,
        Err(msg) => {
            report_error(&msg, "", color);
            std::process::exit(1);
        }
    };
    let v = match machine.eval(&e.expr) {
        Ok(v) => v,
        Err(d) => {
            report_diag(&d, color);
            std::process::exit(1);
        }
    };
    let out = match format.as_str() {
        "yaml" => crate::ser::to_yaml(&v),
        _ => crate::ser::to_json(&v, pretty),
    };
    println!("{}", out);
}

pub fn report_error(msg: &str, _hint: &str, _color: Option<&str>) {
    let mut s = format!("error: {}\n\n", msg);
    s.push_str("For more information, try '--help'.\n");
    let _ = &mut s;
    eprint!("{}", s);
}

pub fn report_diag(d: &Diag, _color: Option<&str>) {
    let mut s = format!("error: {}\n", d.message);
    for h in &d.hints {
        s.push_str(&format!(" = hint: {}\n", h));
    }
    s.push('\n');
    eprint!("{}", s);
}

/// Evaluates a whole source file, reporting the first error.
pub fn eval_file(
    text: &str,
    path: &str,
    machine: &mut Machine,
    color: Option<&str>,
) -> Result<(), String> {
    let mut p = crate::code::Parser::new(text);
    let items = match p.parse_block_items() {
        Ok(i) => i,
        Err(msg) => {
            let loc = crate::diag::locate(&msg, path);
            let _ = loc;
            let mut s = format!("error: {}\n\n", msg);
            s.push_str("For more information, try '--help'.\n");
            return Err(s);
        }
    };
    for it in &items {
        if let Err(d) = machine.eval(&it.expr) {
            return Err(format!(
                "error: {}\n = hint: {}\n\n",
                d.message,
                d.hints.first().cloned().unwrap_or_default()
            ));
        }
    }
    Ok(())
}
