//! Diagnostic formatting.

pub struct Diag {
    pub severity: &'static str,
    pub message: String,
    pub hints: Vec<String>,
    /// (source, path, start byte offset, end byte offset)
    pub spans: Vec<(String, String, usize, usize)>,
}

impl Diag {
    pub fn error(message: &str) -> Diag {
        Diag {
            severity: "error",
            message: message.to_string(),
            hints: vec![],
            spans: vec![],
        }
    }
    pub fn hint(mut self, h: &str) -> Diag {
        self.hints.push(h.to_string());
        self
    }
    pub fn span(mut self, src: &str, path: &str, start: usize, end: usize) -> Diag {
        self.spans.push((src.to_string(), path.to_string(), start, end));
        self
    }
}

fn line_col(src: &str, off: usize) -> (usize, usize) {
    let mut line = 1;
    let mut col = 1;
    for (i, c) in src.char_indices() {
        if i >= off {
            break;
        }
        if c == '\n' {
            line += 1;
            col = 1;
        } else {
            col += 1;
        }
    }
    (line, col)
}

fn line_text(src: &str, line: usize) -> String {
    src.lines().nth(line - 1).unwrap_or("").to_string()
}

pub fn render(d: &Diag, color: bool) -> String {
    let mut out = String::new();
    let err = if color {
        "\x1b[0m\x1b[1m\x1b[38;5;9merror\x1b[0m\x1b[1m".to_string()
    } else {
        "error".to_string()
    };
    let msg_end = if color { "\x1b[0m" } else { "" };
    out.push_str(&format!("{}: {}{}\n", err, d.message, msg_end));
    for (src, path, start, end) in &d.spans {
        let (line, col) = line_col(src, *start);
        let (eline, ecol) = line_col(src, *end.max(start));
        let text = line_text(src, line);
        let gutter = format!("{:width$} ", line, width = line.to_string().len());
        let pad = " ".repeat(gutter.len() - 1);
        let cyan = if color { "\x1b[0m\x1b[34m" } else { "" };
        let reset = if color { "\x1b[0m" } else { "" };
        let red = if color { "\x1b[0m\x1b[31m" } else { "" };
        out.push_str(&format!("  {}┌─{} {}:{}:{}\n", cyan, reset, path, line, col));
        out.push_str(&format!("  {}│{}\n", cyan, reset));
        out.push_str(&format!("{}{}{}{} {}\n", cyan, gutter, reset, cyan, format!("│ {}", text).trim_start_matches(' ')));
        let n = if eline == line { ecol.saturating_sub(col) } else { 1 };
        let carets = "^".repeat(n.max(1));
        out.push_str(&format!("  {}│{} {}{}{}{}{}\n", cyan, reset, " ".repeat(col - 1), red, carets, reset, ""));
    }
    for h in &d.hints {
        out.push_str(&format!(" = hint: {}\n", h));
    }
    out.push('\n');
    out
}

pub fn render_short(d: &Diag) -> String {
    let mut out = String::new();
    match d.spans.first() {
        Some((_, path, start, _)) => {
            let src = &d.spans[0].0;
            let (line, col) = line_col(src, *start);
            out.push_str(&format!("{}:{}:{}: error: {}\n", path, line, col, d.message));
        }
        None => out.push_str(&format!("error: {}\n", d.message)),
    }
    out
}

pub fn locate(_msg: &str, _path: &str) -> Option<(usize, usize)> {
    None
}
