/// Reads an input file (or stdin for `-`), returning the text and the display
/// path used in diagnostics.
pub fn read_input(path: &str) -> Result<(String, String), String> {
    if path == "-" {
        use std::io::Read;
        let mut s = String::new();
        std::io::stdin().read_to_string(&mut s).map_err(|e| e.to_string())?;
        return Ok((s, "<stdin>".to_string()));
    }
    match std::fs::read_to_string(path) {
        Ok(t) => Ok((t, relative_path(path))),
        Err(_) => Err(format!(
            "error: input file not found (searched at {})\n",
            path
        )),
    }
}

/// Makes a path relative to the current directory when possible.
pub fn relative_path(p: &str) -> String {
    let cwd = std::env::current_dir().unwrap_or_default();
    let path = std::path::Path::new(p);
    if path.is_absolute() {
        if let Ok(rel) = path.strip_prefix(&cwd) {
            let s = rel.to_string_lossy().to_string();
            if s.is_empty() {
                return p.to_string();
            }
            return s;
        }
        // Try to find a common ancestor for nicer output
        let abs: Vec<_> = path.components().collect();
        let cwd_c: Vec<_> = cwd.components().collect();
        let mut common = 0;
        while common < abs.len() && common < cwd_c.len() && abs[common] == cwd_c[common] {
            common += 1;
        }
        let ups = cwd_c.len() - common;
        let mut s = String::new();
        for _ in 0..ups {
            s.push_str("../");
        }
        for c in &abs[common..] {
            s.push_str(&c.as_os_str().to_string_lossy());
            s.push('/');
        }
        if s.ends_with('/') {
            s.pop();
        }
        return s;
    }
    p.to_string()
}
