new = r'''pub fn content_json(c: &Content, out: &mut String, pretty: bool, level: usize) {
    if c.elems.len() != 1 {
        // sequence
        let children: Vec<Value> = c
            .elems
            .iter()
            .map(|e| Value::Content(Content { elems: vec![e.clone()] }))
            .collect();
        obj_start(out, pretty, level);
        field(out, pretty, level, true, "func", &|o: &mut String| {
            o.push_str(&jstr("sequence"))
        });
        field(out, pretty, level, false, "children", &|o: &mut String| {
            arr_json(&children, o, pretty, level + 1)
        });
        obj_end(out, pretty, level);
        return;
    }
    elem_json(&c.elems[0], out, pretty, level);
}

fn obj_start(out: &mut String, pretty: bool, _level: usize) {
    out.push('{');
}

fn obj_end(out: &mut String, pretty: bool, level: usize) {
    if pretty {
        out.push('\n');
        out.push_str(&indent(level));
    }
    out.push('}');
}

fn field(out: &mut String, pretty: bool, level: usize, first: bool, k: &str, f: &dyn Fn(&mut String)) {
    if !first {
        out.push(',');
    }
    if pretty {
        out.push('\n');
        out.push_str(&indent(level + 1));
    }
    out.push_str(&jstr(k));
    out.push(':');
    if pretty {
        out.push(' ');
    }
    f(out);
}

fn arr_json(items: &[Value], out: &mut String, pretty: bool, level: usize) {
    if items.is_empty() {
        out.push_str("[]");
        return;
    }
    out.push('[');
    for (i, it) in items.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        if pretty {
            out.push('\n');
            out.push_str(&indent(level + 1));
        }
        j_value(it, out, pretty, level + 1);
    }
    if pretty {
        out.push('\n');
        out.push_str(&indent(level));
    }
    out.push(']');
}

pub fn elem_json(e: &Elem, out: &mut String, pretty: bool, level: usize) {
    match e {
        Elem::Text(t) => {
            let t = t.clone();
            obj_start(out, pretty, level);
            field(out, pretty, level, true, "func", &|o| o.push_str(&jstr("text")));
            field(out, pretty, level, false, "text", &|o| o.push_str(&jstr(&t)));
            obj_end(out, pretty, level);
        }
        Elem::Space => {
            obj_start(out, pretty, level);
            field(out, pretty, level, true, "func", &|o| o.push_str(&jstr("space")));
            obj_end(out, pretty, level);
        }
