pub fn jval_json(v: &JVal, out: &mut String, pretty: bool, level: usize) {
    match v {
        JVal::Null => out.push_str("null"),
        JVal::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        JVal::Int(i) => out.push_str(&i.to_string()),
        JVal::Float(f) => out.push_str(&crate::util::fmt_float(*f)),
        JVal::Str(s) => out.push_str(&jstr(s)),
        JVal::Arr(items) => {
            let vals: Vec<Value> = items
                .iter()
                .map(|x| Value::Content(Content { elems: vec![] }))
                .collect();
            let _ = vals;
            out.push('[');
            for (i, it) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                if pretty {
                    out.push('\n');
                    out.push_str(&indent(level + 1));
                }
                match it {
                    JVal::Str(s) => out.push_str(&jstr(s)),
                    JVal::Int(i) => out.push_str(&i.to_string()),
                    JVal::Float(f) => out.push_str(&crate::util::fmt_float(*f)),
                    JVal::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
                    JVal::Null => out.push_str("null"),
                    _ => out.push_str(&jstr("..")),
                }
            }
            out.push(']');
        }
        JVal::Obj(items) => {
            out.push('{');
            for (i, (k, val)) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                if pretty {
                    out.push('\n');
                    out.push_str(&indent(level + 1));
                }
                out.push_str(&jstr(k));
                out.push(':');
                if pretty {
                    out.push(' ');
                }
                jval_json(val, out, pretty, level + 1);
            }
            out.push('}');
        }
    }
}

