new = r'''    fn make_color(&mut self, kind: &str, pos: &[Value], named: &HashMap<String, Value>) -> R {
        let alpha = named
            .get("alpha")
            .or_else(|| {
                if kind == "luma" || kind == "rgb" || kind == "cmyk" {
                    pos.get(if kind == "luma" { 1 } else if kind == "rgb" { 3 } else { 4 }).cloned()
                } else {
                    None
                }
            });
        let alpha_v = match &alpha {
            Some(Value::Ratio(r)) => Some(*r),
            Some(Value::Int(i)) => Some(*i as f64 / 255.0),
            Some(other) => return Err(type_err(other, "ratio")),
            None => None,
        };
        let (repr, comps) = match kind {
            "luma" => {
                let v = match pos.first() {
                    Some(Value::Ratio(r)) => *r,
                    Some(other) => match to_float(other) {
                        Some(f) => f / 255.0,
                        None => return Err(type_err(other, "integer, float, or ratio")),
                    },
                    None => return Err(Diag::new("missing argument: lightness")),
                };
                let mut s = format!("luma({}%", crate::util::fmt2(v * 100.0));
                if let Some(a) = alpha_v {
                    s.push_str(&format!(", {}%", crate::util::fmt2(a * 100.0)));
                }
                s.push(')');
                (s, vec![v])
            }
            "rgb" => {
                let comps = match pos.first() {
                    Some(Value::Str(s)) => {
                        let hex = s.trim_start_matches('#');
                        if hex.len() != 6 && hex.len() != 8 {
                            return Err(Diag::new("string must be a valid hex color"));
                        }
                        let b = |i: usize| {
                            u8::from_str_radix(&hex[i * 2..i * 2 + 2], 16)
                                .map(|x| x as f64 / 255.0)
                                .unwrap_or(0.0)
                        };
                        vec![b(0), b(1), b(2), if hex.len() == 8 { b(3) } else { 1.0 }]
                    }
                    Some(other) => {
                        let mut c = vec![];
                        for v in pos.iter() {
                            match v {
                                Value::Int(i) => {
                                    if !(0..=255).contains(i) {
                                        return Err(Diag::new("number must be between 0 and 255"));
                                    }
                                    c.push(*i as f64 / 255.0);
                                }
                                Value::Ratio(r) => c.push(*r),
                                other => {
                                    return Err(Diag::new(&format!(
                                        "expected integer or ratio, found {}",
                                        other.type_name()
                                    )))
                                }
                            }
                        }
                        if c.len() < 3 || c.len() > 4 {
                            return Err(Diag::new("too many arguments"));
                        }
                        c
                    }
                    None => return Err(Diag::new("missing argument: red")),
                };
                let mut hex = String::from("#");
                for c in comps.iter().take(3) {
                    hex.push_str(&format!("{:02x}", (c * 255.0).round() as i64));
                }
                let a = alpha_v.or_else(|| comps.get(3).copied());
                if let Some(a) = a {
                    if a < 1.0 {
                        hex.push_str(&format!("{:02x}", (a * 255.0).round() as i64));
                    }
                }
                (format!("rgb(\"{}\")", hex), comps)
            }
            "cmyk" => {
                let mut c = vec![];
                for v in pos.iter() {
                    match v {
                        Value::Ratio(r) => c.push(*r),
                        other => return Err(type_err(other, "ratio")),
                    }
                }
                while c.len() < 4 {
                    c.push(0.0);
                }
                let parts: Vec<String> = c
                    .iter()
                    .map(|x| format!("{}%", crate::util::fmt2(x * 100.0)))
                    .collect();
                (format!("cmyk({})", parts.join(", ")), c)
            }
            "oklab" | "oklch" => {
                let mut c = vec![];
                for v in pos.iter() {
                    match v {
                        Value::Ratio(r) => c.push(format!("{}%", crate::util::fmt2(r * 100.0))),
                        Value::Float(f) => c.push(crate::util::fmt2(*f)),
                        Value::Int(i) => c.push(crate::util::fmt2(*i as f64)),
                        Value::Angle(a) => c.push(crate::util::fmt2(*a) + "deg"),
                        other => return Err(type_err(other, "ratio")),
                    }
                }
                while c.len() < 3 {
                    c.push(crate::util::fmt2(0.0));
                }
                (format!("{}({})", kind, c.join(", ")), vec![])
            }
            _ => return Err(Diag::new("unsupported color space")),
        };
        let c = match kind {
            "luma" => Color::Luma { components: comps, repr, alpha: alpha_v.unwrap_or(1.0) },
            "cmyk" => Color::Cmyk { components: comps, repr, alpha: alpha_v.unwrap_or(1.0) },
            "oklab" => Color::Oklab { components: comps, repr, alpha: alpha_v.unwrap_or(1.0) },
            "oklch" => Color::Oklch { components: comps, repr, alpha: alpha_v.unwrap_or(1.0) },
            _ => Color::Rgb { components: comps, repr, alpha: alpha_v.unwrap_or(1.0) },
        };
        Ok(Value::Color(c))
    }

'''
