pub fn fmt_float(f: f64) -> String {
    if f.is_nan() {
        return "NaN".to_string();
    }
    if f.is_infinite() {
        return "float.inf".to_string();
    }
    let neg = f < 0.0 || (f == 0.0 && f.is_sign_negative());
    let a = f.abs();
    let s = format!("{}", a);
    // determine exponent
    let (digits, point) = match s.find('.') {
        Some(p) => (s[..p].chars().chain(s[p + 1..].chars()).collect::<Vec<char>>(), p as i64),
        None => (s.chars().collect::<Vec<char>>(), s.len() as i64),
    };
    let first = digits.iter().position(|c| *c != '0');
    let (mant, exp) = match first {
        Some(k) => {
            let d: String = digits[k..].iter().collect();
            let e = point - k as i64;
            (d.trim_end_matches('0').to_string(), e)
        }
        None => ("0".to_string(), 1),
    };
    let body = if exp >= 16 || exp <= -6 {
        let mut m = String::new();
        m.push_str(&mant[..1]);
        if mant.len() > 1 {
            m.push('.');
            m.push_str(&mant[1..]);
        }
        format!("{}e{}", m, exp - 1)
    } else if exp <= 0 {
        let mut s2 = String::from("0.");
        for _ in 0..(-exp) {
            s2.push('0');
        }
        s2.push_str(&mant);
        s2
    } else if (mant.len() as i64) <= exp {
        let mut s2 = mant.clone();
        for _ in 0..(exp - mant.len() as i64) {
            s2.push('0');
        }
        s2.push_str(".0");
        s2
    } else {
        format!("{}.{}", &mant[..exp as usize], &mant[exp as usize..])
    };
    if neg {
        format!("-{}", body)
    } else {
        body
    }
}

