pub fn weekday(y: i32, m: u32, d: u32) -> u32 {
    let a = (14 - m as i64) / 12;
    let y2 = y as i64 + 4800 - a;
    let m2 = m as i64 + 12 * a - 3;
    let jdn = d as i64 + (153 * m2 + 2) / 5 + 365 * y2 + y2 / 4 - y2 / 100 + y2 / 400 - 32045;
    ((jdn + 1) % 7) as u32
}

pub fn ordinal(y: i32, m: u32, d: u32) -> u32 {
    let mut days = d as i64;
    for mm in 1..m as i64 {
        days += match mm {
            1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
            4 | 6 | 9 | 11 => 30,
            2 => {
                if (y % 4 == 0 && y % 100 != 0) || y % 400 == 0 {
                    29
                } else {
                    28
                }
            }
            _ => 0,
        };
    }
    days as u32
}
