//! The `typst compile` command: markup -> layout -> PDF/SVG/PNG.

use crate::cli::{Cli, Matches};
use crate::eval::Machine;
use crate::value::{Content, Elem};

pub struct PageCfg {
    pub width: f64,
    pub height: f64,
    pub margin: [f64; 4],
}

impl Default for PageCfg {
    fn default() -> Self {
        // A4 with 2.5cm margins
        PageCfg { width: 595.275590551, height: 841.88976378, margin: [70.866141732; 4] }
    }
}

pub fn run(m: &Matches, _c: &Cli, color: Option<&str>) {
    let input = m.positionals.first().cloned().unwrap_or_default();
    let output = m.positionals.get(1).cloned();
    let (text, path) = match crate::cli::read_input(&input) {
        Ok(t) => t,
        Err(e) => {
            eprint!("{}", e);
            std::process::exit(1);
        }
    };
    let features_html = m
        .get_all("--features")
        .iter()
        .any(|f| f.split(',').any(|p| p == "html"))
        || crate::fonts::truthy(&std::env::var("TYPST_FEATURES").unwrap_or_default());
    let target_html = m.get("--target") == Some("html");
    if target_html && !features_html {
        eprint!("error: html export is only available when `--features html` is passed\n");
        eprint!(" = hint: html export is under active development and incomplete\n");
        eprint!(" = hint: see https://github.com/typst/typst/issues/5512 for more information\n\n");
        std::process::exit(1);
    }
    if m.has("--pages") && !m.has("--no-pdf-tags") {
        eprint!("warning: using --pages implies --no-pdf-tags\n");
        eprint!(" = hint: the resulting PDF will be inaccessible\n");
        eprint!(" = hint: add --no-pdf-tags to silence this warning\n\n");
    }
    let mut machine = Machine::new(features_html, target_html);
    let content = match crate::eval::eval_markup_file(&text, &path, &mut machine, color) {
        Ok(c) => c,
        Err(e) => {
            eprint!("{}", e);
            std::process::exit(1);
        }
    };
    let page = machine.page.clone();
    let format = m
        .get("--format")
        .map(|s| s.to_string())
        .or_else(|| output.as_ref().and_then(|o| infer_format(o)))
        .unwrap_or_else(|| "pdf".to_string());
    match crate::render_doc(&content, &page, &format, &machine) {
        Ok(bytes) => {
            match output.as_deref() {
                None | Some("-") => {
                    use std::io::Write;
                    std::io::stdout().write_all(&bytes).ok();
                }
                Some(o) => {
                    let named = crate::cli::expand_output(o, 1, 1);
                    std::fs::write(&named, &bytes).ok();
                }
            }
            std::process::exit(0);
        }
        Err(e) => {
            eprint!("{}", e);
            std::process::exit(1);
        }
    }
}

fn infer_format(path: &str) -> Option<String> {
    let ext = std::path::Path::new(path)
        .extension()
        .and_then(|e| e.to_str())
        .map(|e| e.to_lowercase())?;
    match ext.as_str() {
        "pdf" => Some("pdf".to_string()),
        "png" => Some("png".to_string()),
        "svg" => Some("svg".to_string()),
        "html" => Some("html".to_string()),
        _ => None,
    }
}

/// Converts the content of a document into pages of text lines.
pub struct Doc {
    pub pages: Vec<Vec<crate::render::Line>>,
    pub font_size: f64,
    pub leading: f64,
}

pub fn layout(content: &Content, page: &PageCfg, shaper: &crate::render::Shaper) -> Doc {
    let max_width = page.width - page.margin[0] - page.margin[2];
    let max_height = page.height - page.margin[1] - page.margin[3];
    let font_size = 11.0;
    let leading = font_size * 1.2;
    let mut pages: Vec<Vec<crate::render::Line>> = vec![];
    let mut cur_page: Vec<crate::render::Line> = vec![];
    let mut y = 0.0;
    for para in paragraphs(content) {
        if para.is_empty() {
            // paragraph break
            if !cur_page.is_empty() {
                y += leading;
            }
            continue;
        }
        let lines = crate::render::wrap(&para, shaper, max_width);
        for l in lines {
            if y + leading > max_height && !cur_page.is_empty() {
                pages.push(std::mem::take(&mut cur_page));
                y = 0.0;
            }
            y += leading;
            cur_page.push(l);
        }
    }
    pages.push(cur_page);
    Doc { pages, font_size, leading }
}

/// Splits content into paragraphs (strings), separated by parbreaks.
pub fn paragraphs(content: &Content) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    let mut cur = String::new();
    collect(content, &mut cur, &mut out);
    if !cur.is_empty() {
        out.push(cur);
    }
    out
}

fn collect(c: &Content, cur: &mut String, out: &mut Vec<String>) {
    for e in &c.elems {
        match e {
            Elem::Text(t) => cur.push_str(t),
            Elem::Space => cur.push(' '),
            Elem::Linebreak => cur.push(' '),
            Elem::Parbreak => {
                let t = cur.trim().to_string();
                if !t.is_empty() {
                    out.push(t);
                }
                cur.clear();
            }
            Elem::Strong { body } | Elem::Emph { body } | Elem::Item { body } => {
                collect(body, cur, out)
            }
            Elem::Sequence(inner) => collect(inner, cur, out),
            Elem::Symbol(s) => cur.push_str(s),
            Elem::Smartquote { double } => cur.push(if *double { '"' } else { '\'' }),
            Elem::Raw { text, .. } => cur.push_str(text),
            Elem::Math { body } => {
                cur.push_str(&crate::ser::content_text(body));
            }
            _ => {}
        }
    }
}
