            "<<\n  /Type /Font\n  /Subtype /CIDFontType2\n  /BaseFont /{}-Identity-H\n  /CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >>\n  /FontDescriptor {} 0 R\n  /W [3 [{}]]\n  /DW 1000\n>>",
            f.name,
            base + 2,
            (f.upem as f64 * 0.5) as i64
        ));
        body.push(format!(
            "<<\n  /Type /FontDescriptor\n  /FontName /{}-Identity-H\n  /Flags {}\n  /FontBBox [{} {} {} {}]\n  /ItalicAngle {}\n  /Ascent {}\n  /Descent {}\n  /CapHeight {}\n  /StemV {}\n  /FontFile2 {} 0 R\n>>",
            f.name,
            f.flags,
            f.bbox[0] as i64, f.bbox[1] as i64, f.bbox[2] as i64, f.bbox[3] as i64,
            f.italic_angle,
            f.ascent as i64,
            f.descent as i64,
            f.cap_height as i64,
            40,
            base + 3
        ));
        body.push(format!(
            "<<\n  /Length {}\n  /Length1 {}\n>>\nstream\n{}\nendstream",
            f.data.len(),
            f.data.len(),
            "<<binary>>"
        ));
    }
    // pages
    let mut page_nums = vec![];
    for (i, p) in doc.iter().enumerate() {
        let page_num = next;
        next += 1;
        page_nums.push(page_num);
        body.push(format!(
            "<<\n  /Type /Page\n  /Parent 1 0 R\n  /MediaBox [0 0 {} {}]\n  /Contents {} 0 R\n  /Group << /Type /Group /S /Transparency /CS /DeviceRGB >>\n  /Resources << /ColorSpace << /srgb << /ColorSpace /DeviceRGB >> >> /Font << >> >>\n>>",
            p.width, p.height, page_num + 1
        ));
        let stream = p.ops.clone();
        body.push(format!(
            "<<\n  /Length {}\n>>\nstream\n{}\nendstream",
            stream.len(),
            stream
        ));
    }
    let _ = (num, offsets, objs, out);
    // assemble
    let mut data: Vec<u8> = vec![];
    data.extend_from_slice(b"%PDF-1.7\n%\xe2\xe3\xcf\xd3\n\n");
    let mut xref: Vec<(usize, String)> = vec![];
    let mut pos = data.len();
    let mut emit = |data: &mut Vec<u8>, num: usize, obj: &str, pos: &mut usize, xref: &mut Vec<(usize, String)>| {
        xref.push((*pos, format!("{} 0 obj\n{}\nendobj\n", num, obj)));
        let bytes = format!("{} 0 obj\n{}\nendobj\n", num, obj);
        data.extend_from_slice(bytes.as_bytes());
        *pos += bytes.len();
    };
    // 1: pages
    let kids: Vec<String> = page_nums.iter().map(|n| format!("{} 0 R", n)).collect();
    emit(&mut data, 1, &format!("<<\n  /Type /Pages\n  /Count {}\n  /Kids [{}]\n>>", doc.len(), kids.join(" ")), &mut pos, &mut xref);
    // fonts
    for (i, f) in fonts.iter().enumerate() {
        let base = 2 + i * 4;
        emit(&mut data, base, &format!("<<\n  /Type /Font\n  /Subtype /Type0\n  /BaseFont /{}-Identity-H\n  /Encoding /Identity-H\n  /DescendantFonts [{} 0 R]\n>>", f.name, base + 1), &mut pos, &mut xref);
        emit(&mut data, base + 1, &format!("<<\n  /Type /Font\n  /Subtype /CIDFontType2\n  /BaseFont /{}-Identity-H\n  /CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >>\n  /FontDescriptor {} 0 R\n  /DW {}\n>>", f.name, base + 2, f.upem), &mut pos, &mut xref);
        emit(&mut data, base + 2, &format!("<<\n  /Type /FontDescriptor\n  /FontName /{}-Identity-H\n  /Flags {}\n  /FontBBox [{} {} {} {}]\n  /ItalicAngle {}\n  /Ascent {}\n  /Descent {}\n  /CapHeight {}\n  /StemV {}\n  /FontFile2 {} 0 R\n>>", f.name, f.flags, f.bbox[0] as i64, f.bbox[1] as i64, f.bbox[2] as i64, f.bbox[3] as i64, f.italic_angle, f.ascent as i64, f.descent as i64, f.cap_height as i64, 40, base + 3), &mut pos, &mut xref);
        let mut bytes: Vec<u8> = vec![];
        bytes.extend_from_slice(format!("{} 0 obj\n<<\n  /Length {}\n  /Length1 {}\n>>\nstream\n", base + 3, f.data.len(), f.data.len()).as_bytes());
        bytes.extend_from_slice(&f.data);
        bytes.extend_from_slice(b"\nendstream\n");
        xref.push((pos, String::new()));
        data.extend_from_slice(&bytes);
        pos += bytes.len();
    }
    // pages and contents
    for (i, p) in doc.iter().enumerate() {
        let n = page_nums[i];
        emit(&mut data, n, &format!("<<\n  /Type /Page\n  /Parent 1 0 R\n  /MediaBox [0 0 {} {}]\n  /Contents {} 0 R\n  /Group << /Type /Group /S /Transparency /CS /DeviceRGB >>\n  /Resources << /ColorSpace << /srgb << /ColorSpace /DeviceRGB >> >> /Font << {} >> >>\n>>", p.width, p.height, n + 1, font_dict(fonts)), &mut pos, &mut xref);
        let stream = p.ops.clone();
        emit(&mut data, n + 1, &format!("<<\n  /Length {}\n>>\nstream\n{}\nendstream", stream.len(), stream), &mut pos, &mut xref);
    }
    // catalog
    let catalog = page_nums[0] + 2;
    emit(&mut data, catalog, &format!("<<\n  /Type /Catalog\n  /Pages 1 0 R\n>>"), &mut pos, &mut xref);
    // xref
    let start = pos;
    let count = xref.len() + 1;
    let mut xr = format!("xref\n0 {}\n", count);
    xr.push_str("0000000000 65535 f \n");
    let mut idx = 1;
    for (o, _) in xref.iter() {
        xr.push_str(&format!("{:010} 00000 n \n", o));
        let _ = idx;
        idx += 1;
    }
    xr.push_str(&format!("trailer\n<<\n  /Size {}\n  /Root {} 0 R\n>>\nstartxref\n{}\n%%EOF\n", count, catalog, start));
    data.extend_from_slice(xr.as_bytes());
    data
}

fn font_dict(fonts: &[PdfFont]) -> String {
    let mut s = String::new();
    for (i, _) in fonts.iter().enumerate() {
        s.push_str(&format!("/F{} {} 0 R ", i, 2 + i * 4));
    }
    s
}
