//! Document rendering to PDF, SVG and PNG.

use crate::compile::{Doc, PageCfg};
use crate::font::Sfnt;
use crate::pdf::{PdfFont, PdfPage};

/// Loads the body font used for rendering.
pub fn load_font() -> Option<(Sfnt, String)> {
    let custom: Vec<std::path::PathBuf> = std::env::var("TYPST_FONT_PATHS")
        .ok()
        .map(|s| crate::fonts::split_paths(&s))
        .unwrap_or_default();
    let book = crate::fonts::discover(&custom, false, false);
    let candidates = ["Libertinus Serif", "DejaVu Serif", "DejaVu Sans", "New Computer Modern"];
    for fam in candidates {
        if let Some(f) = book.faces.iter().find(|f| f.family == fam) {
            if let Ok(data) = std::fs::read(&f.path) {
                if let Some(s) = Sfnt::parse(data, 0) {
                    return Some((s, fam.to_string()));
                }
            }
        }
    }
    for f in book.faces.iter() {
        if let Ok(data) = std::fs::read(&f.path) {
            if let Some(s) = Sfnt::parse(data, 0) {
                return Some((s, f.family.clone()));
            }
        }
    }
    None
}

fn pdf_font(sfnt: &Sfnt, family: &str) -> PdfFont {
    let upem = sfnt.units_per_em();
    let (asc, desc, _, _, _) = sfnt.hhea().unwrap_or((800, -200, 1, 0, 0));
    let bold = sfnt.weight() >= 600;
    PdfFont {
        name: font_name(family),
        data: sfnt.data.clone(),
        upem,
        ascent: asc as f64 * 1000.0 / upem as f64,
        descent: desc as f64 * 1000.0 / upem as f64,
        cap_height: (asc as f64 * 0.7) * 1000.0 / upem as f64,
        bbox: [0.0, desc as f64, upem as f64, asc as f64],
        flags: if bold { 0x24 } else { 0x20 },
        italic_angle: if sfnt.style() == crate::font::Style::Italic { -12.0 } else { 0.0 },
        family: family.to_string(),
        bold,
    }
}

fn font_name(family: &str) -> String {
    let mut out = String::new();
    for c in family.chars() {
        if c.is_alphanumeric() {
            out.push(c);
        }
    }
    out
}

pub fn render_doc(
    content: &crate::value::Content,
    page: &PageCfg,
    format: &str,
    _m: &crate::eval::Machine,
) -> Result<Vec<u8>, String> {
    let (sfnt, family) = match load_font() {
        Some(f) => f,
        None => return Err("error: no fonts found\n".to_string()),
    };
    let font_size = 11.0;
    let upem = sfnt.units_per_em() as f64;
    let shaper = crate::render::Shaper { font: &sfnt, upem, size: font_size };
    let doc = crate::compile::layout(content, page, &shaper);
    match format {
        "svg" => Ok(render_svg(&doc, page, &shaper, &family)),
        "png" => render_png(&doc, page, &shaper),
        _ => Ok(render_pdf(&doc, page, &shaper, &sfnt, &family)),
    }
}

fn render_pdf(
    doc: &Doc,
    page: &PageCfg,
    shaper: &crate::render::Shaper,
    sfnt: &Sfnt,
    family: &str,
) -> Vec<u8> {
    let mut pages = vec![];
    for lines in &doc.pages {
        let mut ops = String::new();
        let ascent = sfnt
            .hhea()
            .map(|h| h.0 as f64 / shaper.upem * shaper.size)
            .unwrap_or(8.0);
        let mut y = page.height - page.margin[1] - ascent;
        ops.push_str(&format!(
            "q\n0 0 {} {} re\nW n\n0 g\nBT\n/F0 {} Tf\n",
            page.width, page.height, shaper.size
        ));
        for l in lines {
            let glyphs = shaper.shape(&l.text);
            ops.push_str(&format!(
                "1 0 0 1 {} {} Tm\n[",
                page.margin[0],
                page.height - page.margin[1] - 0.0
            ));
            let mut prev = 0.0;
            for g in &glyphs {
                if g.x != prev {
                    ops.push_str(&format!("{:.3} ", -(g.x - prev) * 1000.0 / shaper.size));
                    prev = g.x;
                }
                ops.push_str(&format!("<{:04x}> ", g.gid as i64));
            }
            ops.push_str("] TJ\n");
            y -= doc.leading;
            let _ = y;
        }
        ops.push_str("ET\nQ\n");
        pages.push(PdfPage { width: page.width, height: page.height, ops });
    }
    let fonts = vec![pdf_font(sfnt, family)];
    crate::pdf::write_pdf(&pages, &fonts)
}

fn render_svg(
    doc: &Doc,
    page: &PageCfg,
    shaper: &crate::render::Shaper,
    _family: &str,
) -> Vec<u8> {
    let mut s = String::new();
    s.push_str(&format!(
        "<svg viewBox=\"0 0 {:.9} {:.9}\" width=\"{:.9}pt\" height=\"{:.9}pt\" xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" xmlns:h5=\"http://www.w3.org/1999/xhtml\">\n",
        page.width, page.height, page.width, page.height
    ));
    s.push_str(&format!(
        "  <path fill=\"#ffffff\" fill-rule=\"nonzero\" d=\"M 0 0v {:.9}h {:.9}v -{:.9}Z \"/>\n",
        page.height, page.width, page.height
    ));
    let ascent = shaper.font.hhea().map(|h| h.0 as f64 / shaper.upem * shaper.size).unwrap_or(8.0);
    let mut y = page.margin[1] + ascent;
    for lines in &doc.pages {
        for l in lines {
            let glyphs = shaper.shape(&l.text);
            s.push_str(&format!(
                "  <g transform=\"matrix(1 0 0 -1 {:.9} {:.9})\">\n",
                page.margin[0], page.height - y
            ));
            for g in &glyphs {
                s.push_str(&format!(
                    "    <use xlink:href=\"#g{:04X}\" x=\"{:.3}\" y=\"0\" fill=\"#000000\" fill-rule=\"nonzero\"/>\n",
                    g.gid, g.x
                ));
            }
            s.push_str("  </g>\n");
            y += doc.leading;
        }
        break;
    }
    // glyph definitions
    s.push_str("  <defs>\n");
    let mut done: Vec<u16> = vec![];
    for lines in doc.pages.iter() {
        for l in lines {
            for g in shaper.shape(&l.text) {
                if done.contains(&g.gid) {
                    continue;
                }
                done.push(g.gid);
                if let Some(o) = shaper.font.outline(g.gid) {
                    s.push_str(&format!("    <symbol id=\"g{:04X}\" overflow=\"visible\">\n", g.gid));
                    s.push_str(&format!("      <path d=\"{}\"/>\n", path_d(&o, shaper.upem)));
                    s.push_str("    </symbol>\n");
                }
            }
        }
    }
    s.push_str("  </defs>\n</svg>\n");
    s.into_bytes()
}

/// Converts a glyph outline to an SVG path (font units, y up).
fn path_d(o: &crate::font::Outline, _upem: f64) -> String {
    let mut d = String::new();
    for contour in &o.contours {
        if contour.is_empty() {
            continue;
        }
        let pts = &contour;
        // find a point that is on-curve to start from
        let start = pts.iter().position(|p| p.on).unwrap_or(0);
        let n = pts.len();
        let mut i = start;
        d.push_str(&format!("M {} {} ", pts[start].x, pts[start].y));
        for _ in 0..n {
            let cur = pts[i % n];
            let next = pts[(i + 1) % n];
            if next.on {
                d.push_str(&format!("l {} {} ", next.x, next.y));
                i += 1;
            } else {
                // quadratic curve
                let after = pts[(i + 2) % n];
                if after.on {
                    d.push_str(&format!("q {} {} {} {} ", next.x, next.y, after.x, after.y));
                    i += 2;
                } else {
                    let mid = ((next.x + after.x) / 2, (next.y + after.y) / 2);
                    d.push_str(&format!("q {} {} {} {} ", next.x, next.y, mid.0, mid.1));
                    i += 1;
                }
            }
            if i % n == start {
                break;
            }
        }
        d.push_str("Z ");
    }
    d
}

fn render_png(
    doc: &Doc,
    page: &PageCfg,
    shaper: &crate::render::Shaper,
) -> Result<Vec<u8>, String> {
    let ppi = 144.0;
    let scale = ppi / 72.0;
    let w = (page.width * scale) as usize;
    let h = (page.height * scale) as usize;
    let mut buf = vec![255u8; w * h * 3];
    let ascent = shaper.font.hhea().map(|x| x.0 as f64 / shaper.upem * shaper.size).unwrap_or(8.0);
    let mut y = page.margin[1] + ascent;
    'outer: for lines in doc.pages.iter() {
        for l in lines {
            for g in shaper.shape(&l.text) {
                let x0 = (page.margin[0] + g.x) * scale;
                let y0 = (page.height - y) * scale;
                fill_glyph(&mut buf, w, h, shaper, g.gid, x0, y0, scale);
            }
            y += doc.leading;
            if y > page.height {
                break 'outer;
            }
        }
    }
    Ok(crate::png::encode(&buf, w, h))
}

fn fill_glyph(
    buf: &mut [u8],
    w: usize,
    h: usize,
    shaper: &crate::render::Shaper,
    gid: u16,
    x0: f64,
    y0: f64,
    scale: f64,
) {
    let o = match shaper.font.outline(gid) {
        Some(o) => o,
        None => return,
    };
    let upem = shaper.upem;
    let size = shaper.size * scale / upem;
    for contour in &o.contours {
        // scanline fill using even-odd crossings on quadratic segments
        let pts: Vec<(f64, f64)> = contour.iter().map(|p| (p.x as f64 * size + x0, y0 - p.y as f64 * size)).collect();
        if pts.is_empty() {
            continue;
        }
        let ymin = pts.iter().map(|p| p.1).fold(f64::INFINITY, f64::min).floor() as i64;
        let ymax = pts.iter().map(|p| p.1).fold(f64::NEG_INFINITY, f64::max).ceil() as i64;
        for py in ymin..=ymax {
            if py < 0 || py as usize >= h {
                continue;
            }
            let yc = py as f64 + 0.5;
            let mut xs: Vec<f64> = vec![];
            for i in 0..pts.len() {
                let a = pts[i];
                let b = pts[(i + 1) % pts.len()];
                if (a.1 <= yc && b.1 > yc) || (b.1 <= yc && a.1 > yc) {
                    let t = (yc - a.1) / (b.1 - a.1);
                    xs.push(a.0 + t * (b.0 - a.0));
                }
            }
            xs.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
            let mut k = 0;
            while k + 1 < xs.len() {
                let xa = xs[k].max(0.0).ceil() as usize;
                let xb = (xs[k + 1].min(w as f64)).floor() as usize;
                for px in xa..xb.min(w) {
                    let idx = (py as usize * w + px) * 3;
                    if idx + 2 < buf.len() {
                        buf[idx] = 0;
                        buf[idx + 1] = 0;
                        buf[idx + 2] = 0;
                    }
                }
                k += 2;
            }
        }
    }
}
