pub fn write_pdf(doc: &[PdfPage], fonts: &[PdfFont]) -> Vec<u8> {
    let mut data: Vec<u8> = vec![];
    data.extend_from_slice(b"%PDF-1.7\n%\xe2\xe3\xcf\xd3\n\n");
    let mut offsets: Vec<usize> = vec![0];
    let mut pos = data.len();
    let mut put = |data: &mut Vec<u8>, obj: &str, pos: &mut usize, offsets: &mut Vec<usize>| {
        offsets.push(*pos);
        let b = obj.as_bytes();
        data.extend_from_slice(b);
        *pos += b.len();
    };
    // 1: Pages (kids filled later)
    put(&mut data, "PLACEHOLDER", &mut pos, &mut offsets);
    let font_base = 2usize;
    for (i, f) in fonts.iter().enumerate() {
        let base = font_base + i * 4;
        put(&mut data, &format!("<<\n  /Type /Font\n  /Subtype /Type0\n  /BaseFont /{}-Identity-H\n  /Encoding /Identity-H\n  /DescendantFonts [{} 0 R]\n>>", f.name, base + 1), &mut pos, &mut offsets);
        put(&mut data, &format!("<<\n  /Type /Font\n  /Subtype /CIDFontType2\n  /BaseFont /{}-Identity-H\n  /CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >>\n  /FontDescriptor {} 0 R\n  /DW {}\n>>", f.name, base + 2, f.upem), &mut pos, &mut offsets);
        put(&mut data, &format!("<<\n  /Type /FontDescriptor\n  /FontName /{}-Identity-H\n  /Flags {}\n  /FontBBox [{} {} {} {}]\n  /ItalicAngle {}\n  /Ascent {}\n  /Descent {}\n  /CapHeight {}\n  /StemV {}\n  /FontFile2 {} 0 R\n>>", f.name, f.flags, f.bbox[0] as i64, f.bbox[1] as i64, f.bbox[2] as i64, f.bbox[3] as i64, f.italic_angle, f.ascent as i64, f.descent as i64, f.cap_height as i64, 40, base + 3), &mut pos, &mut offsets);
        offsets.push(pos);
        let mut bytes: Vec<u8> = vec![];
        bytes.extend_from_slice(format!("{} 0 obj\n<<\n  /Length {}\n  /Length1 {}\n>>\nstream\n", base + 3, f.data.len(), f.data.len()).as_bytes());
        bytes.extend_from_slice(&f.data);
        bytes.extend_from_slice(b"\nendstream\n");
        data.extend_from_slice(&bytes);
        pos += bytes.len();
    }
    let mut page_nums = vec![];
    for p in doc {
        let n = offsets.len() + 1;
        page_nums.push(n);
        put(&mut data, &format!("{} 0 obj\n<<\n  /Type /Page\n  /Parent 1 0 R\n  /MediaBox [0 0 {} {}]\n  /Contents {} 0 R\n  /Group << /Type /Group /S /Transparency /CS /DeviceRGB >>\n  /Resources << /ColorSpace << /srgb << /ColorSpace /DeviceRGB >> >> /Font << {} >> >>\nendobj", p.width, p.height, p.height, n + 1, font_dict(fonts)), &mut pos, &mut offsets);
        offsets.push(pos);
        let mut b: Vec<u8> = vec![];
        b.extend_from_slice(format!("{} 0 obj\n<<\n  /Length {}\n>>\nstream\n", n + 1, p.ops.len()).as_bytes());
        b.extend_from_slice(p.ops.as_bytes());
        b.extend_from_slice(b"endstream\n");
        data.extend_from_slice(&b);
        pos += b.len();
    }
    let catalog = offsets.len() + 1;
    put(&mut data, &format!("{} 0 obj\n<<\n  /Type /Catalog\n  /Pages 1 0 R\n>>\nendobj", catalog), &mut pos, &mut offsets);
    // patch object 1
    let kids: Vec<String> = page_nums.iter().map(|n| format!("{} 0 R", n)).collect();
    let obj1 = format!("1 0 obj\n<<\n  /Type /Pages\n  /Count {}\n  /Kids [{}]\n>>\nendobj\n", doc.len(), kids.join(" "));
    let start = offsets[1];
    let mut nb: Vec<u8> = vec![];
    nb.extend_from_slice(obj1.as_bytes());
    for (i, c) in nb.iter().enumerate() {
        data[start + i] = *c;
    }
    let mut pos2 = start + nb.len();
    let _ = pos2;
    let xref_start = pos;
    let mut xr = format!("xref\n0 {}\n", offsets.len() + 1);
    xr.push_str("0000000000 65535 f \n");
    for o in offsets.iter().skip(1) {
        xr.push_str(&format!("{:010} 00000 n \n", o));
    }
    xr.push_str(&format!("trailer\n<<\n  /Size {}\n  /Root {} 0 R\n>>\nstartxref\n{}\n%%EOF\n", offsets.len() + 1, catalog, xref_start));
    data.extend_from_slice(xr.as_bytes());
    data
}

fn font_dict(fonts: &[PdfFont]) -> String {
    let mut s = String::new();
    for (i, _) in fonts.iter().enumerate() {
        s.push_str(&format!("/F{} {} 0 R ", i, 2 + i * 4));
    }
    s
}
