import struct
d=open('/usr/share/fonts/truetype/dejavu/DejaVuSerif.ttf','rb').read()
n=struct.unpack('>H',d[4:6])[0]
tabs={}
for i in range(n):
    off=12+16*i; tag=d[off:off+4].decode('latin1'); o,l=struct.unpack('>II',d[off+8:off+16]); tabs[tag]=(o,l)
co,cl=tabs['cmap']
num=struct.unpack('>H',d[co+2:co+4])[0]
def get_glyph(off,code):
    fmt=struct.unpack('>H',d[co+off:co+off+2])[0]
    if fmt==12:
        ng=struct.unpack('>I',d[co+off+12:co+off+16])[0]
        for g in range(ng):
            s,e2,sg=struct.unpack('>III',d[co+off+16+12*g:co+off+16+12*g+12])
            if s<=code<=e2: return sg+(code-s)
    if fmt==4:
        segx2=struct.unpack('>H',d[co+off+6:co+off+8])[0]
        segs=segx2//2
        ends=[struct.unpack('>H',d[co+off+14+2*i:co+off+14+2*i+2])[0] for i in range(segs)]
        starts=[struct.unpack('>H',d[co+off+16+segx2+2*i:co+off+16+segx2+2*i+2])[0] for i in range(segs)]
        deltas=[struct.unpack('>h',d[co+off+16+segx2+segx2+2*i:co+off+16+segx2+segx2+2*i+2])[0] for i in range(segs)]
        rngs=[struct.unpack('>H',d[co+off+16+segx2+segx2+segx2+2*i:co+off+16+segx2+segx2+segx2+2*i+2])[0] for i in range(segs)]
        for i in range(segs-1,-1,-1):
            if starts[i]<=code<=ends[i]:
                if rngs[i]==0: return (code+deltas[i])&0xffff
                addr=co+off+16+segx2+segx2+segx2+2*i+rngs[i]+(code-starts[i])*2
                g=struct.unpack('>H',d[addr:addr+2])[0]
                if g==0: return 0
                return (g+deltas[i])&0xffff
    return None
for i in range(num):
    pid,eid,off=struct.unpack('>HHI',d[co+4+8*i:co+4+8*i+8])
    print(pid,eid,'H ->',get_glyph(off,0x48),'e ->',get_glyph(off,0x65))
PYEOF"}

