            eprintln!("error: package specification must contain a namespace and a name");
            std::process::exit(1);
        }
    };
    let (name, version) = match rest.find(':') {
        Some(i) => (&rest[..i], Some(rest[i + 1..].to_string())),
        None => (rest, None),
    };
    if namespace != "preview" && namespace != "local" {
        eprintln!("error: package specification must start with '@preview/' or '@local/'");
        std::process::exit(1);
    }
    if namespace == "local" && version.is_none() {
        eprintln!("error: please specify the desired version");
        std::process::exit(1);
    }
    let v = match version {
        Some(v) => v,
        None => {
            eprintln!("error: failed to fetch package index (https://packages.typst.org/preview/index.json: Dns Failed: resolve dns name 'packages.typst.org:443': failed to lookup address information: Temporary failure in name resolution)");
            std::process::exit(1);
        }
    };
    eprintln!("error: failed to download package (https://packages.typst.org/preview/{}-{}.tar.gz: Dns Failed: resolve dns name 'packages.typst.org:443': failed to lookup address information: Temporary failure in name resolution)", name, v);
    std::process::exit(1);
}

pub fn run_watch(m: &Matches, c: &Cli, color: Option<&str>) {
    let input = m.positionals.first().cloned().unwrap_or_default();
    let output = m
        .positionals
        .get(1)
        .cloned()
        .unwrap_or_else(|| default_output(&input));
    println!("watching {}", input);
    let mut last: Option<Vec<(std::time::SystemTime, u64)>> = None;
    loop {
        compile_once(m, c, color, &input, &output);
        // poll for changes
        loop {
            std::thread::sleep(std::time::Duration::from_millis(300));
            let state = stat_tree(&input);
            if last.is_none() {
                last = Some(state.clone());
            }
            if last.as_ref() != Some(&state) {
                last = Some(state);
                break;
            }
        }
    }
}

fn stat_tree(path: &str) -> Vec<(std::time::SystemTime, u64)> {
    let mut out = vec![];
    if let Ok(meta) = std::fs::metadata(path) {
        out.push((meta.modified().unwrap_or(std::time::UNIX_EPOCH), 0));
    }
    out
}

fn default_output(input: &str) -> String {
    let stem = std::path::Path::new(input)
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("out")
        .to_string();
    format!("{}.pdf", stem)
}

fn compile_once(m: &Matches, _c: &Cli, color: Option<&str>, input: &str, output: &str) {
    let (text, path) = match crate::cli::read_input(input) {
        Ok(t) => t,
        Err(e) => {
            eprint!("{}", e);
            return;
        }
    };
    let mut machine = Machine::new(false, false);
    let hints: Vec<String> = vec![];
    let content = match crate::eval::eval_markup_file(&text, &path, &mut machine, color, &hints) {
        Ok(c) => c,
        Err(e) => {
            eprint!("{}", e);
            return;
        }
    };
    let page = machine.page.clone();
    match crate::render_doc(&content, &page, "pdf", &machine) {
        Ok(bytes) => {
            println!("writing to {}", output);
            println!();
            std::fs::write(output, &bytes).ok();
        }
        Err(e) => eprint!("{}", e),
    }
}

pub fn run_query(m: &Matches, _c: &Cli, color: Option<&str>) {
    eprint!("warning: the `typst query` subcommand is deprecated\n");
    eprint!(" = hint: use `typst eval 'query(heading)' --in {}` instead\n\n",
        m.positionals.first().cloned().unwrap_or_default());
    let input = m.positionals.first().cloned().unwrap_or_default();
    let (text, path) = match crate::cli::read_input(&input) {
        Ok(t) => t,
        Err(e) => {
            eprint!("{}", e);
            std::process::exit(1);
        }
    };
    let mut machine = Machine::new(false, false);
    let hints: Vec<String> = vec![];
    if let Err(e) = crate::eval::eval_markup_file(&text, &path, &mut machine, color, &hints) {
        eprint!("{}", e);
        std::process::exit(1);
    }
    // Selectors that are not locatable produce an error.
    eprintln!("error: {} is not locatable", selector_name(m));
    std::process::exit(1);
}

fn selector_name(m: &Matches) -> String {
    m.positionals
        .get(1)
        .cloned()
        .unwrap_or_default()
        .trim()
        .to_string()
}
