pub struct Style {
    pub size: f64,
    pub bold: bool,
    pub italic: bool,
}

fn push_seg(cur: &mut Vec<Seg>, s: &str, style: &Style) {
    if s.is_empty() {
        return;
    }
    match cur.last_mut() {
        Some(l) if l.size == style.size && l.bold == style.bold && l.italic == style.italic => {
            l.text.push_str(s)
        }
        _ => cur.push(Seg {
            text: s.to_string(),
            size: style.size,
            bold: style.bold,
            italic: style.italic,
        }),
    }
}

fn collect(c: &Content, cur: &mut Vec<Seg>, out: &mut Vec<Para>, style: &mut Style) {
    for e in &c.elems {
        match e {
            Elem::Text(t) => push_seg(cur, t, style),
            Elem::Space => push_seg(cur, " ", style),
            Elem::Linebreak => push_seg(cur, " ", style),
            Elem::Parbreak => {
                let text: String = cur.iter().map(|s| s.text.clone()).collect();
                if !text.trim().is_empty() {
                    out.push(Para { segs: std::mem::take(cur) });
                } else {
                    cur.clear();
                }
            }
            Elem::Strong { body } => {
                let saved = *style;
                style.bold = true;
                collect(body, cur, out, style);
                *style = saved;
            }
            Elem::Emph { body } => {
                let saved = *style;
                style.italic = true;
                collect(body, cur, out, style);
                *style = saved;
            }
            Elem::Item { body } | Elem::Term { term: body, .. } => collect(body, cur, out, style),
            Elem::Sequence(inner) => collect(inner, cur, out, style),
            Elem::Symbol(s) => push_seg(cur, s, style),
            Elem::Smartquote { double } => {
                push_seg(cur, if *double { "\\"" } else { "'" }, style)
            }
            Elem::Raw { text, .. } => push_seg(cur, text, style),
            Elem::Math { body } => push_seg(cur, &crate::ser::content_text(body), style),
