                    collect_body_field(fields, cur, out, style);
                    *style = saved;
                } else {
                    collect_other(fields, cur, out, style);
                }
            }
            _ => {}
        }
    }
}

fn collect_other(
    fields: &[(String, crate::value::JVal)],
