/// Serializes a JVal to compact JSON.
pub fn jval_str(v: &JVal) -> String {
    match v {
        JVal::Null => "null".to_string(),
        JVal::Bool(b) => b.to_string(),
        JVal::Int(i) => i.to_string(),
        JVal::Float(f) => crate::util::fmt_float(*f),
        JVal::Str(s) => jstr(s),
        JVal::Arr(items) => {
            let parts: Vec<String> = items.iter().map(jval_str).collect();
            format!("[{}]", parts.join(","))
        }
        JVal::Obj(items) => {
            let parts: Vec<String> = items
                .iter()
                .map(|(k, v)| format!("{}:{}", jstr(k), jval_str(v)))
                .collect();
            format!("{{{}}}", parts.join(","))
        }
    }
}

/// Serializes a JVal to pretty JSON.
pub fn pretty_json_str(v: &JVal) -> String {
    let mut s = String::new();
    pj(v, &mut s, 0);
    s
}

fn pj(v: &JVal, out: &mut String, level: usize) {
    match v {
        JVal::Obj(items) if !items.is_empty() => {
            out.push('{');
            for (i, (k, val)) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push_str(&format!("\n{}{}: ", indent(level + 1), jstr(k)));
                pj(val, out, level + 1);
            }
            out.push_str(&format!("\n{}}}", indent(level)));
        }
        JVal::Arr(items) if !items.is_empty() => {
            out.push('[');
            for (i, val) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push_str(&format!("\n{}", indent(level + 1)));
                pj(val, out, level + 1);
            }
            out.push_str(&format!("\n{}]", indent(level)));
        }
        other => out.push_str(&jval_str(other)),
    }
}

pub fn pretty_json_arr(items: &[JVal]) -> String {
    pretty_json_str(&JVal::Arr(items.to_vec()))
}

pub fn jval_yaml(v: &JVal, level: usize) -> String {
    let pad = indent(level);
    match v {
        JVal::Obj(items) => {
            let mut s = String::new();
            for (k, val) in items {
                s.push_str(&format!("{}{}: ", pad, k));
                match val {
                    JVal::Str(t) => s.push_str(&format!("{}\n", t)),
                    JVal::Null => s.push_str("null\n"),
                    other => s.push_str(&format!("{}\n", jval_str(other))),
                }
            }
            s
        }
        other => format!("{}\n", jval_str(other)),
    }
}

pub fn jval_yaml_inline(v: &JVal) -> String {
    match v {
        JVal::Obj(items) => {
            let parts: Vec<String> = items
                .iter()
                .map(|(k, v)| format!("{}: {}", k, y_simple(v)))
                .collect();
            format!("{{{}}}", parts.join(", "))
        }
        other => y_simple(other),
    }
}

fn y_simple(v: &JVal) -> String {
    match v {
        JVal::Null => "null".to_string(),
        JVal::Str(s) => s.clone(),
        other => jval_str(other),
    }
}
